def _copy_dist_flat(src: Path, out: Path) -> None:
    if not src.is_dir():
        msg = f"Build dist directory does not exist: {src}"
        raise RuntimeError(msg)
    out.mkdir(parents=True, exist_ok=True)
    copied = False
    for path in sorted(item for item in src.iterdir() if item.is_file()):
        destination = out / path.name
        if destination.exists():
            msg = (
                "Duplicate .NET release asset basename while flattening "
                f"variant outputs: {path.name}"
            )
            raise RuntimeError(msg)
        shutil.copy2(path, destination)
        copied = True
    if not copied:
        msg = f"Build dist directory contains no release asset files: {src}"
        raise RuntimeError(msg)


def _validate_dotnet_dist(
    plan: Mapping[str, Any], execution_sets: Mapping[str, Any], dist: Path
) -> None:
    """Validate merged .NET dist basenames against actual active publish nodes."""
    expected = _expected_dotnet_dist_asset_names(plan, execution_sets)
    if not expected:
        msg = "Finalized release plan contains no active .NET GitHub Release assets."
        raise RuntimeError(msg)
    if not dist.is_dir():
        msg = f"Merged .NET dist directory does not exist: {dist}"
        raise RuntimeError(msg)
    actual = sorted(item.name for item in dist.iterdir() if item.is_file())
    if not actual:
        msg = f"Merged .NET dist directory contains no release asset files: {dist}"
        raise RuntimeError(msg)
    expected_set = set(expected)
    actual_set = set(actual)
    if actual_set != expected_set:
        missing = sorted(expected_set - actual_set)
        unexpected = sorted(actual_set - expected_set)
        details: list[str] = []
        if missing:
            details.append(f"missing: {', '.join(missing)}")
        if unexpected:
            details.append(f"unexpected: {', '.join(unexpected)}")
        msg = (
            "Merged .NET release asset files do not match the finalized release "
            f"plan ({'; '.join(details)})."
        )
        raise RuntimeError(msg)


def _expected_dotnet_dist_asset_names(
    plan: Mapping[str, Any], execution_sets: Mapping[str, Any]
) -> list[str]:
    graph = _mapping(plan["graph"], "graph")
    projects = _mapping(plan["envelope"]["projects"], "envelope.projects")
    variants = _mapping(graph["variants"], "graph.variants")
    artifacts = _mapping(graph["artifacts"], "graph.artifacts")
    publish_nodes = _mapping(graph["publish-nodes"], "graph.publish-nodes")
    target_snapshots = _mapping(
        graph["target-instance-snapshots"],
        "graph.target-instance-snapshots",
    )
    active_variant_ids = {
        str(variant_id) for variant_id in execution_sets["active-variant-ids"]
    }
    names_by_artifact_id: dict[str, str] = {}
    artifacts_by_name: dict[str, str] = {}
    for raw_node_id in execution_sets["active-github-release-publish-node-ids"]:
        node_id = str(raw_node_id)
        node = _mapping(
            publish_nodes[node_id], f"graph.publish-nodes.{node_id}"
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if snapshot.get("family") != "github-release":
            msg = (
                f"active GitHub Release publish node {node_id!r} uses "
                f"non-GitHub-Release target {snapshot_id!r}"
            )
            raise RuntimeError(msg)
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{node_id}.projection",
        )
        asset_names = _mapping(
            projection.get("asset-names-by-artifact-id", {}),
            f"graph.publish-nodes.{node_id}.projection.asset-names-by-artifact-id",
        )
        for raw_artifact_id in node.get("artifact-ids", []):
            artifact_id = str(raw_artifact_id)
            artifact = _mapping(
                artifacts[artifact_id], f"graph.artifacts.{artifact_id}"
            )
            variant_id = str(artifact["variant-id"])
            if variant_id not in active_variant_ids:
                msg = (
                    f"active GitHub Release publish node {node_id!r} references "
                    f"artifact {artifact_id!r} from inactive variant {variant_id!r}"
                )
                raise RuntimeError(msg)
            variant = _mapping(
                variants[variant_id], f"graph.variants.{variant_id}"
            )
            project_id = str(variant["project-id"])
            project = _mapping(
                projects[project_id], f"envelope.projects.{project_id}"
            )
            if project.get("ecosystem") != "dotnet":
                continue
            asset_name = asset_names.get(artifact_id)
            if not isinstance(asset_name, str) or not asset_name:
                msg = (
                    f"active .NET GitHub Release artifact {artifact_id!r} for "
                    f"publish node {node_id!r} is missing a planned asset name"
                )
                raise RuntimeError(msg)
            existing = names_by_artifact_id.get(artifact_id)
            if existing is not None and existing != asset_name:
                msg = (
                    f"conflicting .NET GitHub Release asset names for artifact "
                    f"{artifact_id!r}: {existing!r} and {asset_name!r}"
                )
                raise RuntimeError(msg)
            other_artifact_id = artifacts_by_name.get(asset_name)
            if (
                other_artifact_id is not None
                and other_artifact_id != artifact_id
            ):
                msg = (
                    "duplicate planned .NET GitHub Release asset basename "
                    f"{asset_name!r} for artifacts {other_artifact_id!r} and "
                    f"{artifact_id!r}"
                )
                raise RuntimeError(msg)
            names_by_artifact_id[artifact_id] = asset_name
            artifacts_by_name[asset_name] = artifact_id
    return sorted(names_by_artifact_id.values())


def _build_request_artifacts(
    plan: Mapping[str, Any], variant: Mapping[str, Any]
) -> Json:
    """Materialize build-request artifacts with effective build projections."""
    graph = _mapping(plan["graph"], "graph")
    plan_artifacts = _mapping(graph["artifacts"], "graph.artifacts")
    artifacts = {
        str(artifact_id): dict(
            _mapping(
                plan_artifacts[artifact_id], f"graph.artifacts.{artifact_id}"
            )
        )
        for artifact_id in variant["artifact-ids"]
    }
    _materialize_npm_build_projections(graph, artifacts)
    return artifacts


def _materialize_npm_build_projections(
    graph: Mapping[str, Any], artifacts: Json
) -> None:
    """Apply legacy single-artifact npm target projection to build artifacts."""
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    effective_names: dict[str, str] = {}
    sources: dict[str, str] = {}
    for node_id, raw_node in _mapping(
        graph["publish-nodes"], "graph.publish-nodes"
    ).items():
        node = _mapping(raw_node, f"graph.publish-nodes.{node_id}")
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if snapshot.get("family") != "npm":
            continue
        node_artifact_ids = [
            item
            for item in node.get("artifact-ids", [])
            if isinstance(item, str)
        ]
        artifact_keys = {str(artifact_id) for artifact_id in artifacts}
        relevant = [
            artifact_id
            for artifact_id in node_artifact_ids
            if artifact_id in artifact_keys
        ]
        if not relevant:
            continue
        projection = _mapping(
            node.get("projection", {}), "publish-node.projection"
        )
        package_name = projection.get("package-name")
        if not isinstance(package_name, str):
            continue
        if len(node_artifact_ids) != 1:
            msg = (
                f"npm package-name projection for publish node {node_id!r} "
                "references multiple artifacts; use artifact-level projection"
            )
            raise ValueError(msg)
        artifact_id = relevant[0]
        artifact_projection = _mapping(
            artifacts[artifact_id].get("projection", {}),
            f"artifacts.{artifact_id}.projection",
        )
        if isinstance(artifact_projection.get("package-name"), str):
            continue
        previous = effective_names.get(artifact_id)
        if previous is not None and previous != package_name:
            msg = (
                f"conflicting npm package-name projections for artifact "
                f"{artifact_id!r}: {previous!r} from {sources[artifact_id]!r} "
                f"and {package_name!r} from {node_id!r}; use distinct "
                "artifact-level projections"
            )
            raise ValueError(msg)
        effective_names[artifact_id] = package_name
        sources[artifact_id] = str(node_id)
    for artifact_id, package_name in effective_names.items():
        projection = dict(
            _mapping(
                artifacts[artifact_id].get("projection", {}),
                f"artifacts.{artifact_id}.projection",
            )
        )
        projection["package-name"] = package_name
        artifacts[artifact_id]["projection"] = projection


def _cmd_download_publish_inputs(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    expected = _publish_input_names(
        plan, args.publish_node_id, args.run_id, args.attempt
    )
    if args.handoff:
        _validate_handoff_inputs(
            _read_json(Path(args.handoff)), args.publish_node_id, expected
        )
    for name in expected["build-result-artifact-names"]:
        _download_artifact(
            args.repository,
            args.run_id,
            name,
            Path(args.build_results_dir) / name,
        )
    for name in expected["build-bundle-artifact-names"]:
        _download_artifact(
            args.repository, args.run_id, name, Path(args.bundles_dir) / name
        )
    return 0


def _cmd_publish_request(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    if args.handoff:
        _validate_handoff_inputs(
            _read_json(Path(args.handoff)),
            args.publish_node_id,
            _publish_input_names(
                plan, args.publish_node_id, args.run_id, args.attempt
            ),
        )
    if args.github_release_asset_receipts:
        if not args.github_release_assets_dir:
            msg = (
                "--github-release-assets-dir is required with "
                "--github-release-asset-receipts"
            )
            raise ValueError(msg)
        request = _github_release_publish_request_from_asset_receipts(
            plan,
            args.publish_node_id,
            Path(args.github_release_asset_receipts),
            Path(args.github_release_assets_dir),
        )
    else:
        if not args.build_results_dir or not args.bundles_dir:
            msg = (
                "--build-results-dir and --bundles-dir are required unless "
                "--github-release-asset-receipts is provided"
            )
            raise ValueError(msg)
        request = _publish_request(
            plan,
            args.publish_node_id,
            args.run_id,
            args.attempt,
            Path(args.build_results_dir),
            Path(args.bundles_dir),
        )
    if args.attestation_source_sha:
        attestation_source_sha = _string(
            args.attestation_source_sha,
            "attestation-source-sha",
        )
        if not _ci_sha(attestation_source_sha):
            msg = "attestation-source-sha must be a 40-character lowercase hex SHA"
            raise ValueError(msg)
        request["attestation-source-sha"] = attestation_source_sha
    validate_contract(request)
    _write_json(Path(args.out), request)
    return 0


def _cmd_prepare_attestation(args: argparse.Namespace) -> int:
    request = _read_json(Path(args.publish_request))
    snapshot = request["target-instance-snapshot"]
    needs = snapshot["family"] == "github-release"
    artifact_ids = sorted(request["artifacts"].keys()) if needs else []
    Path(args.artifact_ids_out).write_text(
        json.dumps(artifact_ids, separators=(",", ":")) + "\n", encoding="utf-8"
    )
    lines = []
    asset_names = (
        request["publish-node"]
        .get("projection", {})
        .get("asset-names-by-artifact-id", {})
    )
    for artifact_id in artifact_ids:
        entry = request["artifacts"][artifact_id]
        subject_name = asset_names.get(artifact_id)
        if not isinstance(subject_name, str) or not subject_name:
            msg = f"missing planned GitHub Release asset name for {artifact_id}"
            raise ValueError(msg)
        lines.append(f"{entry['sha256']}  {subject_name}")
    Path(args.checksums_out).write_text(
        "\n".join(lines) + ("\n" if lines else ""), encoding="utf-8"
    )
    _write_outputs(args.github_output, {"needs_attestation": _bool_str(needs)})
    return 0


def _cmd_generate_proofs(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    publish_request = _read_json(Path(args.publish_request))
    validate_contract(plan)
    validate_contract(publish_request)
    if publish_request["publish-node-id"] != args.publish_node_id:
        msg = "publish request node does not match requested proof node"
        raise ValueError(msg)
    snapshot = _mapping(
        publish_request.get("target-instance-snapshot"),
        "publish-request.target-instance-snapshot",
    )
    is_github_release = snapshot.get("family") == "github-release"
    if is_github_release:
        if not args.github_release_result:
            msg = (
                "--github-release-result is required for GitHub Release proofs"
            )
            raise ValueError(msg)
        if not args.asset_attestations:
            msg = "--asset-attestations is required for GitHub Release proofs"
            raise ValueError(msg)
        publish_result = _read_json(Path(args.github_release_result))
        asset_attestations = _read_json(Path(args.asset_attestations))
    else:
        if not args.publish_result:
            msg = "--publish-result is required for package registry proofs"
            raise ValueError(msg)
        publish_result = _read_json(Path(args.publish_result))
        asset_attestations = None
        if publish_result["publish-node-id"] != args.publish_node_id:
            msg = "publish result node does not match requested proof node"
            raise ValueError(msg)
    validate_contract(publish_result)

    artifact_ids = (
        _read_json(Path(args.artifact_ids_json))
        if args.artifact_ids_json
        else _workflow_artifact_ids_by_name(args.repository, args.run_id)
    )
    run = {
        "repository": args.repository,
        "workflow": args.workflow,
        "run-id": args.run_id,
        "run-attempt": args.attempt,
        "head-sha": args.head_sha,
        "live": True,
        "dry-run": False,
        "validation-only": False,
    }
    proofs = _proof_documents(
        plan,
        publish_request,
        publish_result,
        args.publish_node_id,
        run,
        artifact_ids,
        Path(args.build_results_dir),
        args.run_id,
        args.attempt,
        asset_attestations,
    )
    out_dir = Path(args.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    manifest_entries = []
    for name, proof in proofs:
        validate_contract(proof)
        file_name = f"{name}.json"
        _write_json(out_dir / file_name, proof)
        manifest_entries.append({"name": name, "file": file_name})
    manifest = {
        "proofs": manifest_entries,
        "proof_artifact_names": [entry["name"] for entry in manifest_entries],
    }
    _write_json(Path(args.manifest_out), manifest)
    _write_outputs(
        args.github_output,
        {
            "has_proofs": _bool_str(bool(manifest_entries)),
            "proof_matrix": json.dumps(manifest_entries, separators=(",", ":")),
        },
    )
    return 0


def _cmd_github_release_asset_attestations(args: argparse.Namespace) -> int:
    publish_request = _read_json(Path(args.publish_request))
    validate_contract(publish_request)
    github_release_result = (
        _read_json(Path(args.github_release_result))
        if args.github_release_result
        else None
    )
    if github_release_result is not None:
        validate_contract(github_release_result)
    attestation_source_sha = _string(
        args.attestation_source_sha,
        "attestation-source-sha",
    )
    if not _ci_sha(attestation_source_sha):
        msg = "attestation-source-sha must be a 40-character lowercase hex SHA"
        raise ValueError(msg)
    node = _mapping(publish_request["publish-node"], "publish-node")
    projection = _mapping(node.get("projection"), "publish-node.projection")
    asset_names = _mapping(
        projection.get("asset-names-by-artifact-id"),
        "publish-node.projection.asset-names-by-artifact-id",
    )
    artifacts = _mapping(
        publish_request.get("artifacts"), "publish-request.artifacts"
    )
    node_attestation = _mapping(
        node.get("attestation"), "publish-node.attestation"
    )
    signer_workflow = _string(
        node_attestation.get("signer-workflow"),
        "publish-node.attestation.signer-workflow",
    )
    result_assets = (
        _github_release_result_assets_by_name(github_release_result)
        if github_release_result is not None
        else {}
    )
    attestations: Json = {}
    assets_dir = Path(args.assets_dir)
    for artifact_id in _string_list(
        node.get("artifact-ids"), "publish-node.artifact-ids"
    ):
        asset_name = _string(asset_names.get(artifact_id), "asset-name")
        artifact = _mapping(
            artifacts.get(artifact_id), f"artifacts[{artifact_id}]"
        )
        expected_size = _int(artifact.get("byte-size"), "artifact.byte-size")
        expected_sha256 = _string(artifact.get("sha256"), "artifact.sha256")
        if github_release_result is not None:
            result_asset = _mapping(
                result_assets.get(asset_name),
                f"github-release-result.assets[{asset_name}]",
            )
            if (
                result_asset.get("size") != expected_size
                or result_asset.get("sha256") != expected_sha256
            ):
                msg = (
                    f"GitHub Release result asset {asset_name!r} does not match "
                    "the publish request artifact receipt"
                )
                raise RuntimeError(msg)
        asset_path = assets_dir / asset_name
        if not asset_path.is_file():
            msg = f"staged GitHub Release asset {asset_name!r} is missing"
            raise RuntimeError(msg)
        if asset_path.stat().st_size != expected_size:
            msg = f"staged GitHub Release asset {asset_name!r} size mismatch"
            raise RuntimeError(msg)
        if _file_sha256_bytes(asset_path) != expected_sha256:
            msg = f"staged GitHub Release asset {asset_name!r} SHA-256 mismatch"
            raise RuntimeError(msg)
        evidence = _gh_attestation_verify_asset_evidence(
            repository=args.repository,
            asset_path=asset_path,
            asset_name=asset_name,
            expected_sha256=expected_sha256,
            signer_workflow=signer_workflow,
            commit_sha=attestation_source_sha,
        )
        if evidence is None:
            msg = f"GitHub Release asset {asset_name!r} lacks verified attestation evidence"
            raise RuntimeError(msg)
        attestations[artifact_id] = evidence
    _write_json(Path(args.out), attestations)
    return 0


def _cmd_validate_github_release_coverage(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    execution_sets = _read_json(Path(args.execution_sets))
    validate_contract(plan)
    validate_contract(execution_sets)
    _validate_github_release_coverage_inputs(
        plan=plan,
        execution_sets=execution_sets,
        tag=args.tag,
        active_node_ids=_read_string_array_file(
            Path(args.active_github_release_node_ids),
            "active_github_release_node_ids_json",
        ),
        asset_names=_read_string_array_file(
            Path(args.asset_names),
            "asset_names_json",
        ),
    )
    return 0


def _cmd_validate_github_release_asset_proof_sidecar(
    args: argparse.Namespace,
) -> int:
    proof = _read_receipt(Path(args.proof))
    if not _is_valid_github_release_asset_proof_sidecar_file(
        args.name,
        proof,
    ):
        return 1
    plan = _read_json(Path(args.plan))
    validate_contract(plan)
    node_ids = json.loads(
        Path(args.active_github_release_node_ids).read_text(encoding="utf-8"),
        object_pairs_hook=_ci_validation_reject_duplicate_json_keys,
    )
    if not isinstance(node_ids, list) or not all(
        isinstance(node_id, str) and node_id for node_id in node_ids
    ):
        return 1
    expected_assets_by_name = None
    asset_manifest = getattr(args, "asset_manifest", None)
    if asset_manifest:
        try:
            expected_assets_by_name = _read_github_release_payload_manifest(
                Path(asset_manifest),
            )
        except (OSError, ValueError):
            return 1
    nodes = _mapping(plan["graph"].get("publish-nodes"), "graph.publish-nodes")
    for node_id in node_ids:
        node = nodes.get(node_id)
        signer_workflow = (
            _planned_github_release_signer_workflow(node)
            if isinstance(node, Mapping)
            else None
        )
        if (
            isinstance(
                node,
                Mapping,
            )
            and _github_release_asset_proof_is_release_bound_sidecar(
                proof,
                node_id,
                node,
                args.tag,
                repository=args.repository,
                release_target_sha=getattr(args, "release_target_sha", None),
                signer_workflow=signer_workflow,
                artifact_variant_ids_by_id=(
                    _planned_artifact_variant_ids_for_node(plan, node)
                ),
            )
            and _github_release_asset_proof_matches_current_sidecar_coverage(
                proof,
                expected_plan_id=getattr(args, "expected_plan_id", None),
                expected_run_id=getattr(args, "expected_run_id", None),
                expected_run_attempt=getattr(
                    args, "expected_run_attempt", None
                ),
                expected_assets_by_name=expected_assets_by_name,
            )
        ):
            return 0
    return 1


def _cmd_package_publish_result(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    execution_sets = _read_json(Path(args.execution_sets))
    validate_contract(plan)
    validate_contract(execution_sets)
    publish_node_id = _active_package_publish_node_id_for_target(
        plan,
        execution_sets,
        args.target_key,
    )
    node = plan["graph"]["publish-nodes"][publish_node_id]
    snapshot_id = node["target-instance-snapshot-id"]
    result = {
        "api-version": "three.release.publish-result/v1alpha1",
        "kind": "publish-result",
        "plan-id": plan["envelope"]["plan-id"],
        "project-id": node["project-id"],
        "publish-node-id": publish_node_id,
        "target-instance-snapshot-id": snapshot_id,
        "resolved-publish-identity": node["resolved-publish-identity"],
        "outcome": "published",
        "evidence": _package_publish_result_evidence(
            plan,
            publish_node_id,
            args,
        ),
    }
    validate_contract(result)
    out_dir = Path(args.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    out_path = out_dir / "publish-result.json"
    _write_json(out_path, result)
    _write_outputs(
        args.github_output,
        {
            "plan_id": str(plan["envelope"]["plan-id"]),
            "publish_node_id": publish_node_id,
            "publish_result_path": out_path.as_posix(),
        },
    )
    return 0


def _cmd_skip_results(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    execution_sets = _read_json(Path(args.execution_sets))
    out_dir = Path(args.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    plan_id = str(plan["envelope"]["plan-id"])
    names: list[str] = []
    requested_node_id = getattr(args, "publish_node_id", "")
    skip_node_ids = list(execution_sets["skip-satisfied-publish-node-ids"])
    if requested_node_id:
        if requested_node_id not in skip_node_ids:
            msg = (
                f"publish node {requested_node_id!r} is not skip-satisfied "
                "in the finalized execution sets"
            )
            raise RuntimeError(msg)
        skip_node_ids = [requested_node_id]
    for node_id in skip_node_ids:
        node = plan["graph"]["publish-nodes"][node_id]
        snapshot_id = node["target-instance-snapshot-id"]
        result = {
            "api-version": "three.release.skip-result/v1alpha1",
            "kind": "skip-result",
            "plan-id": plan_id,
            "project-id": node["project-id"],
            "publish-node-id": node_id,
            "target-instance-snapshot-id": snapshot_id,
            "resolved-publish-identity": node["resolved-publish-identity"],
            "outcome": "skip-satisfied",
            "reason-source": "planner",
            "evidence": {"planner-disposition": "skip-satisfied"},
        }
        validate_contract(result)
        name = artifact_name(
            "skip-result",
            ArtifactNameInputs(
                args.run_id,
                args.attempt,
                plan_id=plan_id,
                publish_node_id=node_id,
            ),
        )
        item_dir = out_dir / name
        item_dir.mkdir(parents=True, exist_ok=True)
        _write_json(item_dir / "skip-result.json", result)
        names.append(name)
    _write_json(Path(args.manifest_out), {"skip-result-artifact-names": names})
    if getattr(args, "github_output", ""):
        _write_outputs(
            args.github_output,
            {"skip_result_artifact_name": names[0] if len(names) == 1 else ""},
        )
    return 0


def _cmd_official_frozen_versions(args: argparse.Namespace) -> int:
    try:
        document = _official_frozen_versions(
            repository=args.repository,
            project=args.project,
        )
    except (RuntimeError, TypeError, ValueError) as exc:
        diagnostic = _diagnostic(
            "OFFICIAL_FROZEN_VERSION",
            "classification",
            "project",
            "official-frozen version evidence lookup failed",
            {"error": str(exc)},
            project_id=args.project,
        )
        diagnostics_document = _diagnostics_document([diagnostic])
        _write_json(Path(args.diagnostics_out), diagnostics_document)
        sys.stderr.write(json.dumps(diagnostics_document) + "\n")
        return 1
    _write_json(Path(args.out), document)
    return 0


def _official_frozen_versions(
    *,
    repository: str,
    project: str,
) -> dict[str, list[str]]:
    if not project:
        msg = "selected project id is required for official-frozen evidence"
        raise ValueError(msg)
    releases = _gh_api_paginated(
        repository, f"repos/{repository}/releases?per_page=100"
    )
    tag_prefix = f"release/{project}/v"
    versions: set[str] = set()
    for release in releases:
        if not isinstance(release, Mapping):
            msg = "GitHub Releases API returned a non-object release item"
            raise TypeError(msg)
        if release.get("draft") is True:
            continue
        if release.get("prerelease") is not False:
            continue
        tag_name = release.get("tag_name")
        if not isinstance(tag_name, str):
            msg = "GitHub Releases API returned a release without tag_name"
            raise TypeError(msg)
        if not tag_name.startswith(tag_prefix):
            continue
        version = tag_name.removeprefix(tag_prefix)
        if version:
            versions.add(version)
    return {project: sorted(versions)}


def _cmd_observe_remote_publications(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    execution_sets = (
        _read_json(Path(args.execution_sets))
        if getattr(args, "execution_sets", None)
        else None
    )
    allow_official_tag_retarget = _plan_allows_official_tag_retarget(plan)
    try:
        enabled = _normalize_enablement(
            getattr(args, "enabled_external_oidc_targets", ""), plan
        )
    except RuntimeError as exc:
        diagnostics_document = _diagnostics_from_error(exc)
        if diagnostics_document is None:
            raise
        _write_json(Path(args.diagnostics_out), diagnostics_document)
        sys.stderr.write(json.dumps(diagnostics_document) + "\n")
        return 1
    diagnostics: list[Json] = []
    observations: dict[str, str] = {}
    disabled_package_target_keys = _comma_separated_items(
        getattr(args, "disabled_package_target_keys", ""),
    )
    github_release_group_nodes = _github_release_observation_group_nodes(
        plan,
        execution_sets,
    )
    github_release_group_variant_ids = {
        node_id: {
            group_node_id: _planned_artifact_variant_ids_for_node(
                plan,
                group_node,
            )
            for group_node_id, group_node in group_nodes.items()
        }
        for node_id, group_nodes in github_release_group_nodes.items()
    }
    for node_id, node in sorted(plan["graph"]["publish-nodes"].items()):
        if disabled_package_target_keys and _publish_node_has_target_key(
            plan,
            node_id,
            disabled_package_target_keys,
        ):
            continue
        snapshot_id = node["target-instance-snapshot-id"]
        snapshot = plan["graph"]["target-instance-snapshots"][snapshot_id]
        try:
            observation = _maybe_observe_remote_publication(
                args.repository,
                str(plan["envelope"]["commit-sha"]),
                node_id,
                node,
                snapshot_id,
                snapshot,
                execution_sets,
                enabled,
                allow_official_tag_retarget,
                plan_id=str(plan["envelope"]["plan-id"]),
                artifact_variant_ids_by_id=(
                    _planned_artifact_variant_ids_for_node(plan, node)
                ),
                github_release_group_nodes=github_release_group_nodes.get(
                    node_id,
                ),
                github_release_group_variant_ids=(
                    github_release_group_variant_ids.get(node_id)
                ),
            )
        except (RuntimeError, TypeError, ValueError) as exc:
            diagnostics.append(
                _publish_node_diagnostic(
                    "REMOTE_CLASSIFICATION_FAILED",
                    "remote publication lookup failed",
                    node_id,
                    node,
                    snapshot_id,
                    details={"error": str(exc)},
                )
            )
            continue
        if observation is not None:
            observations[node_id] = observation
    if diagnostics:
        _write_json(
            Path(args.diagnostics_out), _diagnostics_document(diagnostics)
        )
        return 1
    _write_json(Path(args.out), observations)
    return 0


def _github_release_observation_group_nodes(
    plan: Json,
    execution_sets: Mapping[str, Any] | None,
) -> dict[str, dict[str, Json]]:
    """Return active same-release GitHub Release nodes keyed by each member."""
    graph = plan.get("graph")
    if not isinstance(graph, Mapping):
        return {}
    publish_nodes = graph.get("publish-nodes")
    snapshots = graph.get("target-instance-snapshots")
    if not isinstance(publish_nodes, Mapping) or not isinstance(
        snapshots, Mapping
    ):
        return {}
    groups: dict[tuple[str, str], dict[str, Json]] = {}
    for node_id in _github_release_observation_candidate_ids(
        publish_nodes,
        execution_sets,
    ):
        group = _github_release_observation_group_member(
            publish_nodes,
            snapshots,
            node_id,
        )
        if group is None:
            continue
        group_key, node = group
        groups.setdefault(group_key, {})[node_id] = node
    result: dict[str, dict[str, Json]] = {}
    for group_nodes in groups.values():
        if len(group_nodes) < 2:
            continue
        for node_id in group_nodes:
            result[node_id] = group_nodes
    return result


def _github_release_observation_candidate_ids(
    publish_nodes: Mapping[str, object],
    execution_sets: Mapping[str, Any] | None,
) -> tuple[str, ...]:
    if execution_sets is None:
        return tuple(publish_nodes)
    active_ids = execution_sets.get(
        "active-github-release-publish-node-ids", []
    )
    active = _string_sequence(active_ids)
    if active:
        return active
    candidates: list[str] = []
    for key in (
        "selected-github-release-publish-node-ids",
        "publish-intent-node-ids",
    ):
        for node_id in _string_sequence(execution_sets.get(key, [])):
            if node_id not in candidates:
                candidates.append(node_id)
    return tuple(candidates)


def _expanded_active_github_release_publish_node_ids(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
) -> list[str]:
    """Return active GitHub Release nodes plus active same-release siblings."""
    active = set(
        _string_sequence(
            execution_sets.get("active-github-release-publish-node-ids", []),
        ),
    )
    if not active:
        return []
    graph = plan.get("graph")
    if not isinstance(graph, Mapping):
        return sorted(active)
    publish_nodes = graph.get("publish-nodes")
    snapshots = graph.get("target-instance-snapshots")
    if not isinstance(publish_nodes, Mapping) or not isinstance(
        snapshots, Mapping
    ):
        return sorted(active)
    candidate_ids = list(active)
    for node_id in _string_sequence(
        execution_sets.get("selected-github-release-publish-node-ids", []),
    ):
        if node_id not in candidate_ids:
            candidate_ids.append(node_id)
    groups: dict[tuple[str, str], set[str]] = {}
    for node_id in candidate_ids:
        group = _github_release_observation_group_member(
            publish_nodes,
            snapshots,
            node_id,
        )
        if group is None:
            continue
        group_key, _node = group
        groups.setdefault(group_key, set()).add(node_id)
    expanded = set(active)
    for group_nodes in groups.values():
        if expanded & group_nodes:
            expanded.update(group_nodes)
    return sorted(expanded)


def _string_sequence(value: object) -> tuple[str, ...]:
    if not isinstance(value, Sequence) or isinstance(value, str | bytes):
        return ()
    return tuple(item for item in value if isinstance(item, str))


def _github_release_observation_group_member(
    publish_nodes: Mapping[str, object],
    snapshots: Mapping[str, object],
    node_id: str,
) -> tuple[tuple[str, str], Json] | None:
    raw_node = publish_nodes.get(node_id)
    if not isinstance(raw_node, Mapping):
        return None
    node = cast("Json", raw_node)
    snapshot_id = node.get("target-instance-snapshot-id")
    if not isinstance(snapshot_id, str):
        return None
    snapshot = snapshots.get(snapshot_id)
    if (
        not isinstance(snapshot, Mapping)
        or snapshot.get("family") != "github-release"
    ):
        return None
    identity = node.get("resolved-publish-identity")
    release_tag = (
        identity.get("release-tag") if isinstance(identity, Mapping) else None
    )
    if not isinstance(release_tag, str) or not release_tag:
        return None
    return (snapshot_id, release_tag), node


def _maybe_observe_remote_publication(
    repository: str,
    commit_sha: str,
    node_id: str,
    node: Mapping[str, Any],
    snapshot_id: str,
    snapshot: Mapping[str, Any],
    execution_sets: Mapping[str, Any] | None,
    enabled: set[str],
    allow_official_tag_retarget: bool,
    plan_id: str | None = None,
    artifact_variant_ids_by_id: Mapping[str, object] | None = None,
    github_release_group_nodes: Mapping[str, Json] | None = None,
    github_release_group_variant_ids: (
        Mapping[str, Mapping[str, object]] | None
    ) = None,
) -> str | None:
    node_json: Json = dict(node)
    if snapshot["family"] == "github-release":
        return _observe_github_release_publication(
            repository,
            commit_sha,
            node_id,
            node_json,
            plan_id=plan_id,
            artifact_variant_ids_by_id=artifact_variant_ids_by_id,
            release_group_nodes=github_release_group_nodes,
            release_group_variant_ids=github_release_group_variant_ids,
            allow_official_tag_retarget=allow_official_tag_retarget,
        )
    if _supports_github_packages_remote_observation(
        snapshot
    ) and _requires_live_github_token_remote_observation(
        node_id, execution_sets
    ):
        return _observe_github_packages_publication(
            repository,
            node_json,
            snapshot,
        )
    if _supports_public_registry_remote_observation(
        snapshot
    ) and _requires_live_external_remote_observation(
        node_id, node, snapshot_id, snapshot, execution_sets, enabled
    ):
        return _observe_public_registry_publication(node_json, snapshot)
    return None


def _plan_allows_official_tag_retarget(plan: Mapping[str, Any]) -> bool:
    envelope = plan.get("envelope")
    if (
        not isinstance(envelope, Mapping)
        or envelope.get("profile") != "official"
    ):
        return False
    flags = envelope.get("request-flags")
    return isinstance(flags, Mapping) and flags.get("force") is True


def _cmd_ensure_tags(args: argparse.Namespace) -> int:
    plan = _read_json(Path(args.plan))
    execution_sets = _read_json(Path(args.execution_sets))
    plan_id = str(plan["envelope"]["plan-id"])
    commit_sha = str(plan["envelope"]["commit-sha"])
    profile = str(plan["envelope"]["profile"])
    force_update_tag = _parse_bool(getattr(args, "force_update_tag", "false"))
    allow_tag_retarget = force_update_tag and profile == "official"
    _validate_ensure_tag_bindings(
        plan,
        execution_sets,
        expected_project_id=getattr(args, "expected_project_id", None),
        expected_commit_sha=getattr(args, "expected_commit_sha", None),
        expected_release_tag=getattr(args, "expected_release_tag", None),
    )
    selected = set(execution_sets["selected-github-release-publish-node-ids"])
    active = set(execution_sets["active-github-release-publish-node-ids"])
    tags: dict[str, dict[str, bool]] = {}
    for node_id in selected:
        node = plan["graph"]["publish-nodes"][node_id]
        tag = str(node["resolved-publish-identity"]["release-tag"])
        requirement = tags.setdefault(
            tag, {"can-create": False, "requires-existing": False}
        )
        requirement["can-create"] = (
            requirement["can-create"] or node_id in active
        )
        requirement["requires-existing"] = (
            requirement["requires-existing"]
            or node.get("publish-disposition") != "publish"
        )
    tag_results = []
    missing: list[str] = []
    force_updates: list[str] = []
    for tag, requirement in sorted(tags.items()):
        peeled = _remote_tag_commit(args.repository, tag)
        if peeled is None:
            if requirement["requires-existing"]:
                msg = (
                    f"required tag {tag!r} is missing but at least one "
                    "skip-satisfied node references it"
                )
                raise RuntimeError(msg)
            if requirement["can-create"]:
                missing.append(tag)
            continue
        if peeled != commit_sha:
            if requirement["can-create"] and allow_tag_retarget:
                force_updates.append(tag)
                continue
            msg = f"required tag {tag!r} points to {peeled}, expected {commit_sha}"
            raise RuntimeError(msg)
        tag_results.append(
            {
                "release-tag": tag,
                "outcome": "verified",
                "expected-commit-sha": commit_sha,
                "peeled-commit-sha": peeled,
            }
        )
    for tag in force_updates:
        encoded_tag = urllib.parse.quote(tag, safe="")
        _gh_api(
            args.repository,
            f"repos/{args.repository}/git/refs/tags/{encoded_tag}",
            method="PATCH",
            fields={"sha": commit_sha, "force": True},
        )
        tag_results.append(
            {
                "release-tag": tag,
                "outcome": "created",
                "expected-commit-sha": commit_sha,
                "peeled-commit-sha": commit_sha,
            }
        )
    for tag in missing:
        _gh_api(
            args.repository,
            f"repos/{args.repository}/git/refs",
            method="POST",
            fields={"ref": f"refs/tags/{tag}", "sha": commit_sha},
        )
        tag_results.append(
            {
                "release-tag": tag,
                "outcome": "created",
                "expected-commit-sha": commit_sha,
                "peeled-commit-sha": commit_sha,
            }
        )
    result = {
        "api-version": "three.release.tag-result/v1alpha1",
        "kind": "tag-result",
        "plan-id": plan_id,
        "commit-sha": commit_sha,
        "tags": sorted(tag_results, key=lambda item: item["release-tag"]),
    }
    validate_contract(result)
    _write_json(Path(args.out), result)
    return 0


def _validate_ensure_tag_bindings(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    *,
    expected_project_id: str | None,
    expected_commit_sha: str | None,
    expected_release_tag: str | None,
) -> None:
    """Fail before ref mutation when downloaded plan data is not the resolved run."""
    envelope = _mapping(plan["envelope"], "envelope")
    plan_id = str(envelope["plan-id"])
    if str(execution_sets.get("plan-id")) != plan_id:
        msg = "execution sets plan-id does not match release plan"
        raise RuntimeError(msg)
    if (
        expected_commit_sha
        and envelope.get("commit-sha") != expected_commit_sha
    ):
        msg = (
            "release plan commit-sha does not match resolved target: "
            f"{envelope.get('commit-sha')!r} != {expected_commit_sha!r}"
        )
        raise RuntimeError(msg)
    if expected_project_id:
        selected_projects = envelope.get("selected-project-ids")
        if selected_projects != [expected_project_id]:
            msg = (
                "release plan selected-project-ids do not match resolved "
                f"project: {selected_projects!r} != {[expected_project_id]!r}"
            )
            raise RuntimeError(msg)
    selected = execution_sets.get("selected-github-release-publish-node-ids")
    if not isinstance(selected, Sequence) or isinstance(selected, str | bytes):
        msg = "selected GitHub Release publish node ids must be an array"
        raise TypeError(msg)
    publish_nodes = _mapping(
        plan["graph"]["publish-nodes"], "graph.publish-nodes"
    )
    for raw_node_id in selected:
        node_id = str(raw_node_id)
        if node_id not in publish_nodes:
            msg = f"selected GitHub Release publish node {node_id!r} is missing from the plan"
            raise RuntimeError(msg)
        node = _mapping(
            publish_nodes[node_id], f"graph.publish-nodes.{node_id}"
        )
        if (
            expected_project_id
            and node.get("project-id") != expected_project_id
        ):
            msg = (
                f"selected GitHub Release publish node {node_id!r} project-id "
                "does not match resolved project"
            )
            raise RuntimeError(msg)
        identity = _mapping(
            node["resolved-publish-identity"],
            f"graph.publish-nodes.{node_id}.resolved-publish-identity",
        )
        release_tag = identity.get("release-tag")
        if expected_release_tag and release_tag != expected_release_tag:
            msg = (
                f"selected GitHub Release publish node {node_id!r} release-tag "
                f"does not match resolved tag: {release_tag!r} != "
                f"{expected_release_tag!r}"
            )
            raise RuntimeError(msg)


def _cmd_report(args: argparse.Namespace) -> int:
    artifact_names = _collect_artifact_names(
        Path(args.artifacts_root) if args.artifacts_root else None,
        run_id=args.run_id,
        attempt=args.attempt,
    )
    artifacts_root = Path(args.artifacts_root) if args.artifacts_root else None
    plan_artifact_name = getattr(args, "plan_artifact_name", "") or ""
    execution_sets_artifact_name = (
        getattr(args, "execution_sets_artifact_name", "") or ""
    )
    entry_publish_handoff_artifact_name = (
        getattr(args, "entry_publish_handoff_artifact_name", "") or ""
    )
    if plan_artifact_name:
        artifact_names["plan-artifact-name"] = plan_artifact_name
    if execution_sets_artifact_name:
        artifact_names["execution-sets-artifact-name"] = (
            execution_sets_artifact_name
        )
    if entry_publish_handoff_artifact_name:
        artifact_names["entry-publish-handoff-artifact-name"] = (
            entry_publish_handoff_artifact_name
        )
    prepare_payloads = (
        _report_prepare_artifact_payloads(
            artifacts_root,
            plan_artifact_name=plan_artifact_name,
            execution_sets_artifact_name=execution_sets_artifact_name,
            entry_publish_handoff_artifact_name=(
                entry_publish_handoff_artifact_name
            ),
            run_id=args.run_id,
            attempt=args.attempt,
        )
        if args.plan_conclusion == "success"
        else None
    )
    if args.plan_conclusion == "success" and prepare_payloads is None:
        return 1
    if prepare_payloads:
        prepare_documents = _read_validated_prepare_artifact_tuple(
            prepare_payloads,
            plan_artifact_name=plan_artifact_name,
            execution_sets_artifact_name=execution_sets_artifact_name,
            entry_publish_handoff_artifact_name=(
                entry_publish_handoff_artifact_name
            ),
            run_id=args.run_id,
            attempt=args.attempt,
            context="Release report generation",
            validate_plan_execution_contracts=False,
        )
        if prepare_documents is None:
            return 1
        plan = prepare_documents["plan"]
        execution_sets = prepare_documents["execution_sets"]
    else:
        plan = _read_optional_json(args.plan)
        execution_sets = _read_optional_json(args.execution_sets)
    plan_id = plan["envelope"]["plan-id"] if plan else None
    selected_projects = (
        plan["envelope"]["selected-project-ids"] if plan else None
    )
    disabled_package_target_keys = _comma_separated_items(
        getattr(args, "disabled_package_target_keys", ""),
    )
    release_completed_check_conclusion = (
        _effective_release_completed_check_conclusion(
            args,
            plan,
            execution_sets,
            artifacts_root,
            artifact_names,
            disabled_package_target_keys=disabled_package_target_keys,
        )
    )
    report = {
        "api-version": "three.release.report/v1alpha1",
        "kind": "release-report",
        "run": {
            "repository": args.repository,
            "workflow": args.workflow,
            "run-id": args.run_id,
            "run-attempt": args.attempt,
            "head-sha": args.head_sha,
            "profile": args.profile,
            "dry-run": _parse_bool(args.dry_run),
            "validation-build": _parse_bool(args.validation_build),
            "canary-override-non-public-ref": _parse_bool(
                args.canary_override_non_public_ref
            ),
            "conclusion": _overall_conclusion(
                args,
                release_completed_check_conclusion,
            ),
        },
        "plan": {"plan-id": plan_id, "selected-project-ids": selected_projects},
        "artifacts": artifact_names,
        "jobs": {
            "authorize-entry": {"conclusion": args.authorize_conclusion},
            "validate-authoring": {"conclusion": args.validate_conclusion},
            "dotnet-metadata": {"conclusion": args.metadata_conclusion},
            "plan": {"conclusion": args.plan_conclusion},
            "build": {
                "conclusion": args.build_conclusion,
                "failed-variant-ids": _failed_variant_ids(
                    args.build_conclusion,
                    plan,
                    execution_sets,
                    artifacts_root,
                    artifact_names,
                ),
            },
            "ensure-tag": {"conclusion": args.tag_conclusion},
            "release-completed-check": {
                "conclusion": release_completed_check_conclusion
            },
            "publish": {
                "conclusion": args.publish_conclusion,
                "failed-publish-node-ids": _failed_publish_node_ids(
                    args.publish_conclusion,
                    plan,
                    execution_sets,
                    artifacts_root,
                    artifact_names,
                    release_completed_check_conclusion,
                    run_id=args.run_id,
                    attempt=args.attempt,
                    disabled_package_target_keys=disabled_package_target_keys,
                ),
            },
        },
        "counts": _report_counts(
            plan,
            execution_sets,
            artifact_names,
            artifacts_root,
            run_id=args.run_id,
            attempt=args.attempt,
            disabled_package_target_keys=disabled_package_target_keys,
        ),
    }
    validate_contract(report)
    _write_json(Path(args.out), report)
    _append_summary(report)
    return 0


def _report_prepare_artifact_payloads(
    root: Path | None,
    *,
    plan_artifact_name: str,
    execution_sets_artifact_name: str,
    entry_publish_handoff_artifact_name: str,
    run_id: int,
    attempt: int,
) -> dict[str, Path] | None:
    if root is None or not root.exists():
        print(
            "Release report generation requires downloaded prepare-release-plan "
            "artifacts when prepare-release-plan succeeded.",
            file=sys.stderr,
        )
        return None
    payloads: dict[str, Path] = {}
    for key, name, prefix, payload_name, label in (
        (
            "plan",
            plan_artifact_name,
            "release-plan-v1-",
            "release-plan.json",
            "release-plan",
        ),
        (
            "execution_sets",
            execution_sets_artifact_name,
            "release-execution-sets-v1-",
            "execution-sets.json",
            "execution-sets",
        ),
        (
            "entry_publish_handoff",
            entry_publish_handoff_artifact_name,
            "release-entry-publish-handoff-v1-",
            "entry-publish-handoff.json",
            "entry-publish-handoff",
        ),
    ):
        payload_path = _report_prepare_artifact_payload(
            root,
            name=name,
            payload_name=payload_name,
            prefix=prefix,
            label=label,
            run_id=run_id,
            attempt=attempt,
        )
        if payload_path is None:
            return None
        payloads[key] = payload_path
    return payloads


def _report_prepare_artifact_payload(
    root: Path,
    *,
    name: str,
    payload_name: str,
    prefix: str,
    label: str,
    run_id: int,
    attempt: int,
) -> Path | None:
    if not name or PurePosixPath(name).name != name or name in {".", ".."}:
        print(
            "Release report generation requires an exact "
            f"{label} artifact name from prepare-release-plan outputs.",
            file=sys.stderr,
        )
        return None
    if not name.startswith(prefix) or not _artifact_name_matches_run_attempt(
        name,
        prefix,
        run_id,
        attempt,
    ):
        print(
            "Release report generation requires the exact current-run "
            f"{label} artifact name from prepare-release-plan outputs.",
            file=sys.stderr,
        )
        return None
    payload_path = root / name / payload_name
    if not payload_path.is_file():
        print(
            "Release report generation requires the bound "
            f"{label} artifact payload at {name}/{payload_name}.",
            file=sys.stderr,
        )
        return None
    return payload_path


def _read_validated_prepare_artifact_tuple(
    paths: Mapping[str, Path],
    *,
    plan_artifact_name: str,
    execution_sets_artifact_name: str,
    entry_publish_handoff_artifact_name: str,
    run_id: int,
    attempt: int,
    context: str,
    validate_plan_execution_contracts: bool = True,
) -> dict[str, Json] | None:
    documents: dict[str, Json] = {}
    labels = {
        "plan": "release-plan",
        "execution_sets": "execution-sets",
        "entry_publish_handoff": "entry-publish-handoff",
    }
    for key, label in labels.items():
        try:
            documents[key] = _read_json(paths[key])
        except (KeyError, OSError, TypeError, ValueError) as exc:
            print(
                f"{context} requires a readable {label} artifact payload: {exc}",
                file=sys.stderr,
            )
            return None
        if key == "entry_publish_handoff" or validate_plan_execution_contracts:
            try:
                validate_contract(documents[key])
            except ContractValidationError as exc:
                print(
                    f"{context} requires a contract-valid {label} artifact "
                    f"payload: {exc}",
                    file=sys.stderr,
                )
                return None
    try:
        _validate_prepare_artifact_tuple(
            documents["plan"],
            documents["execution_sets"],
            documents["entry_publish_handoff"],
            plan_artifact_name=plan_artifact_name,
            execution_sets_artifact_name=execution_sets_artifact_name,
            entry_publish_handoff_artifact_name=(
                entry_publish_handoff_artifact_name
            ),
            run_id=run_id,
            attempt=attempt,
        )
    except (KeyError, TypeError, ValueError) as exc:
        print(
            f"{context} requires an internally consistent "
            f"prepare-release-plan artifact tuple: {exc}",
            file=sys.stderr,
        )
        return None
    return documents


def _validate_prepare_artifact_tuple(
    plan: Json,
    execution_sets: Json,
    entry_publish_handoff: Json,
    *,
    plan_artifact_name: str,
    execution_sets_artifact_name: str,
    entry_publish_handoff_artifact_name: str,
    run_id: int,
    attempt: int,
) -> None:
    envelope = _mapping(plan["envelope"], "$.envelope")
    plan_id = _string(envelope.get("plan-id"), "$.envelope.plan-id")
    commit_sha = _string(envelope.get("commit-sha"), "$.envelope.commit-sha")
    if execution_sets.get("plan-id") != plan_id:
        msg = (
            "execution-sets plan-id does not match release-plan envelope "
            f"plan-id: {execution_sets.get('plan-id')!r} != {plan_id!r}"
        )
        raise ValueError(msg)

    expected_names = {
        "plan-artifact-name": artifact_name(
            "plan",
            ArtifactNameInputs(run_id, attempt, plan_id=plan_id),
        ),
        "execution-sets-artifact-name": artifact_name(
            "execution-sets",
            ArtifactNameInputs(run_id, attempt, plan_id=plan_id),
        ),
        "entry-publish-handoff-artifact-name": artifact_name(
            "entry-publish-handoff",
            ArtifactNameInputs(run_id, attempt, plan_id=plan_id),
        ),
    }
    actual_names = {
        "plan-artifact-name": plan_artifact_name,
        "execution-sets-artifact-name": execution_sets_artifact_name,
        "entry-publish-handoff-artifact-name": (
            entry_publish_handoff_artifact_name
        ),
    }
    for field, expected in expected_names.items():
        actual = actual_names[field]
        if actual != expected:
            msg = (
                f"{field} is not bound to the release-plan tuple: "
                f"{actual!r} != {expected!r}"
            )
            raise ValueError(msg)

    expected_handoff = _entry_publish_handoff(
        plan,
        execution_sets,
        run_id,
        attempt,
    )
    for field, expected in (
        ("plan-id", plan_id),
        ("commit-sha", commit_sha),
        ("plan-artifact-name", plan_artifact_name),
        ("execution-sets-artifact-name", execution_sets_artifact_name),
    ):
        actual = entry_publish_handoff.get(field)
        if actual != expected:
            msg = (
                f"entry-publish-handoff {field} does not match the bound "
                f"prepare tuple: {actual!r} != {expected!r}"
            )
            raise ValueError(msg)
    if entry_publish_handoff != expected_handoff:
        msg = "entry-publish-handoff payload does not match the bound plan and execution sets"
        raise ValueError(msg)


def _effective_release_completed_check_conclusion(
    args: argparse.Namespace,
    plan: Json | None,
    execution_sets: Json | None,
    artifacts_root: Path | None,
    artifacts: Json,
    *,
    disabled_package_target_keys: Iterable[str] = (),
) -> str:
    conclusion = getattr(args, "release_completed_check_conclusion", "skipped")
    if (
        conclusion == "success"
        and args.publish_conclusion == "success"
        and plan is not None
        and execution_sets is not None
        and _unsatisfied_active_publish_node_ids(
            plan,
            execution_sets,
            artifacts_root,
            artifacts,
            run_id=args.run_id,
            attempt=args.attempt,
            disabled_package_target_keys=disabled_package_target_keys,
        )
    ):
        return "failure"
    return conclusion


def _cmd_release_completed_receipts(args: argparse.Namespace) -> int:
    root = Path(args.artifacts_root)
    artifacts = _collect_artifact_names(
        root,
        run_id=args.run_id,
        attempt=args.attempt,
    )
    plan_path = _bound_release_completed_artifact_payload(
        root,
        name=args.plan_artifact_name,
        payload_name="release-plan.json",
        prefix="release-plan-v1-",
        label="release-plan",
        run_id=args.run_id,
        attempt=args.attempt,
    )
    if plan_path is None:
        return 1
    execution_sets_path = _bound_release_completed_artifact_payload(
        root,
        name=args.execution_sets_artifact_name,
        payload_name="execution-sets.json",
        prefix="release-execution-sets-v1-",
        label="execution-sets",
        run_id=args.run_id,
        attempt=args.attempt,
    )
    if execution_sets_path is None:
        return 1
    entry_publish_handoff_path = _bound_release_completed_artifact_payload(
        root,
        name=args.entry_publish_handoff_artifact_name,
        payload_name="entry-publish-handoff.json",
        prefix="release-entry-publish-handoff-v1-",
        label="entry-publish-handoff",
        run_id=args.run_id,
        attempt=args.attempt,
    )
    if entry_publish_handoff_path is None:
        return 1
    prepare_documents = _read_validated_prepare_artifact_tuple(
        {
            "plan": plan_path,
            "execution_sets": execution_sets_path,
            "entry_publish_handoff": entry_publish_handoff_path,
        },
        plan_artifact_name=args.plan_artifact_name,
        execution_sets_artifact_name=args.execution_sets_artifact_name,
        entry_publish_handoff_artifact_name=(
            args.entry_publish_handoff_artifact_name
        ),
        run_id=args.run_id,
        attempt=args.attempt,
        context="Release completion receipt validation",
    )
    if prepare_documents is None:
        return 1
    plan = prepare_documents["plan"]
    execution_sets = prepare_documents["execution_sets"]
    missing = _unsatisfied_active_publish_node_ids(
        plan,
        execution_sets,
        root,
        artifacts,
        run_id=args.run_id,
        attempt=args.attempt,
        disabled_package_target_keys=_comma_separated_items(
            getattr(args, "disabled_package_target_keys", ""),
        ),
    )
    if missing:
        print(
            "Publish nodes missing valid completion receipts: "
            f"{', '.join(missing)}",
            file=sys.stderr,
        )
        return 1
    print(
        "All active and skip-satisfied publish nodes are satisfied by valid "
        "completion receipts."
    )
    return 0


def _bound_release_completed_artifact_payload(
    root: Path,
    *,
    name: str,
    payload_name: str,
    prefix: str,
    label: str,
    run_id: int,
    attempt: int,
) -> Path | None:
    if not name or PurePosixPath(name).name != name or name in {".", ".."}:
        print(
            "Release completion receipt validation requires an exact "
            f"{label} artifact name from prepare-release-plan outputs.",
            file=sys.stderr,
        )
        return None
    if not name.startswith(prefix) or not _artifact_name_matches_run_attempt(
        name,
        prefix,
        run_id,
        attempt,
    ):
        print(
            "Release completion receipt validation requires the exact "
            "current-run "
            f"{label} artifact name from prepare-release-plan outputs.",
            file=sys.stderr,
        )
        return None
    payload_path = root / name / payload_name
    if not payload_path.is_file():
        print(
            "Release completion receipt validation requires the bound "
            f"{label} artifact payload at {name}/{payload_name}.",
            file=sys.stderr,
        )
        return None
    return payload_path


def _external_oidc_diagnostics(
    plan: Json,
    execution_sets: Json,
    enablement: str,
    remote_observations: Mapping[str, Any] | None = None,
    *,
    disabled_package_target_keys: Iterable[str] = (),
) -> list[Json]:
    if plan["envelope"]["profile"] != "official":
        return []
    if execution_sets["dry-run"]:
        return []
    active_oidc_nodes = _active_external_oidc_publish_nodes(
        plan,
        execution_sets,
        disabled_package_target_keys,
    )
    if not active_oidc_nodes:
        return []
    enabled = _normalize_enablement(enablement, plan)
    diagnostics: list[Json] = []
    for node_id, node, snapshot_id, snapshot, capabilities in active_oidc_nodes:
        topology = capabilities["publish-topology"]
        if topology not in _TOPOLOGIES:
            diagnostics.append(
                _publish_node_diagnostic(
                    "REQ_EXTERNAL_TOPOLOGY_BLOCKED",
                    "selected official external OIDC target uses an unsupported topology",
                    node_id,
                    node,
                    snapshot_id,
                    details={
                        "target-family": snapshot["family"],
                        "publish-topology": topology,
                    },
                )
            )
            continue
        identity = node["resolved-publish-identity"]
        token = f"{snapshot_id}#{node['project-id']}#{identity['package-name']}"
        if token not in enabled:
            diagnostics.append(
                _publish_node_diagnostic(
                    "REQ_EXTERNAL_TARGET_DISABLED",
                    "selected official external OIDC target is not live-enabled",
                    node_id,
                    node,
                    snapshot_id,
                    details={
                        "required-enable-token": token,
                        "target-instance-ref": snapshot_id,
                        "project-id": node["project-id"],
                        "resolved-publish-identity": identity,
                    },
                )
            )
            continue
        if _supports_remote_observation(snapshot):
            if (
                remote_observations is not None
                and node_id in remote_observations
            ):
                continue
            diagnostics.append(
                _publish_node_diagnostic(
                    "REMOTE_CLASSIFICATION_FAILED",
                    "authoritative remote observation is missing for selected "
                    "official external OIDC target",
                    node_id,
                    node,
                    snapshot_id,
                    details={
                        "remote-observation": "missing",
                        "target-family": snapshot["family"],
                        "target-instance-ref": snapshot_id,
                        "publish-topology": topology,
                    },
                )
            )
            continue
        diagnostics.append(
            _publish_node_diagnostic(
                "REMOTE_CLASSIFICATION_FAILED",
                "authoritative remote observation is unsupported for selected "
                "official external OIDC target",
                node_id,
                node,
                snapshot_id,
                details={
                    "remote-observation": "unsupported",
                    "target-family": snapshot["family"],
                    "target-instance-ref": snapshot_id,
                    "publish-topology": topology,
                },
            )
        )
    return diagnostics


def _active_external_oidc_publish_nodes(
    plan: Json,
    execution_sets: Json,
    disabled_package_target_keys: Iterable[str],
) -> list[tuple[str, Json, str, Json, Json]]:
    disabled_keys = {key for key in disabled_package_target_keys if key}
    nodes: list[tuple[str, Json, str, Json, Json]] = []
    for raw_node_id in execution_sets["active-publish-node-ids"]:
        node_id = str(raw_node_id)
        if disabled_keys and _publish_node_has_target_key(
            plan, node_id, disabled_keys
        ):
            continue
        node = plan["graph"]["publish-nodes"][node_id]
        snapshot_id = node["target-instance-snapshot-id"]
        snapshot = plan["graph"]["target-instance-snapshots"][snapshot_id]
        capabilities = snapshot["capabilities"]
        if capabilities["credential-posture"] != "oidc":
            continue
        nodes.append(
            (node_id, node, snapshot_id, snapshot, capabilities),
        )
    return nodes


def _variant_runner(plan: Json, variant_id: str) -> str:
    variant = plan["graph"]["variants"][variant_id]
    project = plan["envelope"]["projects"][variant["project-id"]]
    if project["ecosystem"] == "dotnet":
        if _dotnet_variant_has_executable_artifact(plan, variant):
            runner = _runner_for_variant_dimensions(variant.get("dimensions"))
            if runner is not None:
                return runner
        return "windows-latest"
    return "ubuntu-latest"


def _dotnet_variant_has_executable_artifact(plan: Json, variant: Json) -> bool:
    artifact_ids = variant.get("artifact-ids")
    if not isinstance(artifact_ids, list):
        return False
    artifacts = plan["graph"]["artifacts"]
    return any(
        isinstance(artifact_id, str)
        and artifacts[artifact_id].get("concrete-kind") == "executable"
        for artifact_id in artifact_ids
    )


def _runner_for_variant_dimensions(dimensions: object) -> str | None:
    if not isinstance(dimensions, dict):
        return None
    os_value = dimensions.get("os")
    if isinstance(os_value, str):
        runner = _runner_for_os_token(os_value)
        if runner is not None:
            return runner
    rid = dimensions.get("rid")
    if isinstance(rid, str):
        return _runner_for_os_token(rid.split("-", 1)[0])
    return None


def _runner_for_os_token(value: str) -> str | None:
    normalized = value.casefold()
    if normalized in {"windows", "win"}:
        return "windows-latest"
    if normalized == "linux":
        return "ubuntu-latest"
    if normalized in {"macos", "osx"}:
        return "macos-latest"
    return None


def _publish_permission_class(plan: Json, publish_node_id: str) -> str:
    publish_node = plan["graph"]["publish-nodes"][publish_node_id]
    target_id = publish_node["target-instance-snapshot-id"]
    target = plan["graph"]["target-instance-snapshots"][target_id]
    topology = target["capabilities"]["publish-topology"]
    if topology.startswith("external-oidc-"):
        return "external-oidc"
    if target.get("family") == "github-release":
        return "github-release"
    destination_host = target.get("destination", {}).get("host", "")
    if target.get(
        "instance-id"
    ) == "github-packages" or destination_host.endswith("pkg.github.com"):
        return "github-packages"
    msg = (
        "unsupported reusable publish permission class for "
        f"{publish_node_id}: target {target_id}"
    )
    raise RuntimeError(msg)


def _reusable_publish_classes(
    plan: Json, selectors: Mapping[str, list[str]]
) -> dict[str, list[str]]:
    classes = {
        "github-release": [],
        "github-packages": [],
        "external-oidc": [],
    }
    reusable = sorted(
        selectors["github-token"]
        + selectors["external-oidc-caller-workflow"]
        + selectors["external-oidc-reusable-workflow"]
    )
    for publish_node_id in reusable:
        classes[_publish_permission_class(plan, publish_node_id)].append(
            publish_node_id
        )
    return classes


def _planned_target_keys(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> set[str]:
    """Return coarse workflow target keys represented by publish nodes."""
    keys: set[str] = set()
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            plan["graph"]["publish-nodes"][node_id],
            f"graph.publish-nodes.{node_id}",
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            plan["graph"]["target-instance-snapshots"][snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        key = _planned_target_key(snapshot)
        if key is not None:
            keys.add(key)
    return keys


def _active_package_publish_node_id_for_target(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    target_key: str,
) -> str:
    """Return the unique publish node id for an active package target key."""
    active_node_ids = execution_sets.get("active-publish-node-ids")
    if not isinstance(active_node_ids, Sequence) or isinstance(
        active_node_ids,
        (str, bytes),
    ):
        msg = "active-publish-node-ids must be an array"
        raise TypeError(msg)
    matches: list[str] = []
    for raw_node_id in active_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            plan["graph"]["publish-nodes"][node_id],
            f"graph.publish-nodes.{node_id}",
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            plan["graph"]["target-instance-snapshots"][snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if _planned_target_key(snapshot) == target_key:
            matches.append(node_id)
    if len(matches) != 1:
        msg = (
            f"expected exactly one active publish node for {target_key!r}, "
            f"found {len(matches)}"
        )
        raise RuntimeError(msg)
    return matches[0]


def _package_publish_result_evidence(
    plan: Mapping[str, Any],
    publish_node_id: str,
    args: argparse.Namespace,
) -> Json:
    node = _mapping(
        plan["graph"]["publish-nodes"][publish_node_id],
        f"graph.publish-nodes.{publish_node_id}",
    )
    snapshot_id = str(node["target-instance-snapshot-id"])
    snapshot = _mapping(
        plan["graph"]["target-instance-snapshots"][snapshot_id],
        f"graph.target-instance-snapshots.{snapshot_id}",
    )
    projection = _mapping(
        node.get("projection", {}),
        f"graph.publish-nodes.{publish_node_id}.projection",
    )
    evidence: Json = {
        "source": "release-orchestrate-inline-package-registry-publish",
        "repository": args.repository,
        "workflow": args.workflow,
        "run-id": args.run_id,
        "run-attempt": args.attempt,
        "head-sha": args.head_sha,
        "environment": args.environment,
        "target-key": args.target_key,
        "target-family": snapshot.get("family"),
        "target-instance-id": snapshot.get("instance-id"),
        "publish-script": args.publish_script,
        "result-source": "successful-idempotent-publish-step",
    }
    for key in ("final-distribution-filenames-by-artifact-id",):
        value = projection.get(key)
        if isinstance(value, Mapping) and value:
            evidence[key] = dict(value)
    return evidence


def _planned_package_identity(
    plan: Mapping[str, Any],
    publish_node_ids: Iterable[object],
    target_key: str,
) -> tuple[str, str]:
    """Return the unique package name/version planned for one target key."""
    identity: tuple[str, str] | None = None
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            plan["graph"]["publish-nodes"][node_id],
            f"graph.publish-nodes.{node_id}",
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            plan["graph"]["target-instance-snapshots"][snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if _planned_target_key(snapshot) != target_key:
            continue
        publish_identity = _mapping(
            node["resolved-publish-identity"],
            f"graph.publish-nodes.{node_id}.resolved-publish-identity",
        )
        package_name = publish_identity.get("package-name")
        package_version = publish_identity.get("version")
        if not isinstance(package_name, str) or not package_name:
            msg = (
                f"{target_key} publish node {node_id!r} is missing package-name"
            )
            raise RuntimeError(msg)
        if not isinstance(package_version, str) or not package_version:
            msg = f"{target_key} publish node {node_id!r} is missing version"
            raise RuntimeError(msg)
        candidate = (package_name, package_version)
        if identity is not None and identity != candidate:
            msg = (
                f"conflicting {target_key} publish identities in finalized "
                f"plan: {identity!r} and {candidate!r}"
            )
            raise RuntimeError(msg)
        identity = candidate
    return identity if identity is not None else ("", "")


def _planned_distribution_digests_for_target(
    plan: Mapping[str, Any],
    publish_node_ids: Iterable[object],
    target_key: str,
) -> dict[str, str]:
    """Return legacy compatibility distribution digest metadata, when present."""
    digests: dict[str, str] | None = None
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            plan["graph"]["publish-nodes"][node_id],
            f"graph.publish-nodes.{node_id}",
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            plan["graph"]["target-instance-snapshots"][snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if _planned_target_key(snapshot) != target_key:
            continue
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{node_id}.projection",
        )
        raw_artifact_ids = node.get("artifact-ids", [])
        if not isinstance(raw_artifact_ids, Sequence) or isinstance(
            raw_artifact_ids, (str, bytes)
        ):
            msg = f"graph.publish-nodes.{node_id}.artifact-ids must be an array"
            raise TypeError(msg)
        artifact_ids = [str(value) for value in raw_artifact_ids]
        raw_by_artifact_id = _mapping(
            projection.get("final-distribution-digests-by-artifact-id", {}),
            "final-distribution-digests-by-artifact-id",
        )
        if len(artifact_ids) != 1:
            return {}
        artifact_id = artifact_ids[0]
        candidate = _normalize_digest_map(raw_by_artifact_id.get(artifact_id))
        if not {"sha256", "sha512"} <= set(candidate):
            return {}
        if digests is not None and digests != candidate:
            msg = (
                f"conflicting {target_key} tarball digests in finalized plan: "
                f"{digests!r} and {candidate!r}"
            )
            raise RuntimeError(msg)
        digests = candidate
    return digests or {}


def _planned_python_distribution_filenames(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> list[str]:
    """Return planned Python distribution filenames."""
    graph = _mapping(plan["graph"], "graph")
    artifacts = _mapping(graph["artifacts"], "graph.artifacts")
    publish_nodes = _mapping(graph["publish-nodes"], "graph.publish-nodes")
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    expected: set[str] = set()
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            publish_nodes[node_id], f"graph.publish-nodes.{node_id}"
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        family = snapshot.get("family")
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{node_id}.projection",
        )
        if family == "pypi":
            names_by_artifact_id = _mapping(
                projection.get(
                    "final-distribution-filenames-by-artifact-id", {}
                ),
                (
                    f"graph.publish-nodes.{node_id}.projection."
                    "final-distribution-filenames-by-artifact-id"
                ),
            )
        elif family == "github-release":
            names_by_artifact_id = _mapping(
                projection.get("asset-names-by-artifact-id", {}),
                (
                    f"graph.publish-nodes.{node_id}.projection."
                    "asset-names-by-artifact-id"
                ),
            )
        else:
            continue
        for raw_artifact_id in node.get("artifact-ids", []):
            artifact_id = str(raw_artifact_id)
            artifact = _mapping(
                artifacts[artifact_id], f"graph.artifacts.{artifact_id}"
            )
            if artifact.get("concrete-kind") not in {"wheel", "sdist"}:
                continue
            filename = names_by_artifact_id.get(artifact_id)
            if not isinstance(filename, str) or not filename:
                msg = (
                    f"Python distribution artifact {artifact_id!r} for publish "
                    f"node {node_id!r} has no planned filename"
                )
                raise RuntimeError(msg)
            expected.add(filename)
    return sorted(expected)


def _planned_python_distribution_sha256_by_filename(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> dict[str, str]:
    """Return no Python distribution SHA-256 evidence from the planner."""
    _ = plan, tuple(publish_node_ids)
    return {}


def _planned_ruby_gem_identity_and_distribution(  # noqa: C901
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> tuple[str, str, str, str]:
    """Return the unique active Ruby gem package identity and distribution."""
    graph = _mapping(plan["graph"], "graph")
    artifacts = _mapping(graph["artifacts"], "graph.artifacts")
    publish_nodes = _mapping(graph["publish-nodes"], "graph.publish-nodes")
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    expected_identity: tuple[str, str, str] | None = None
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            publish_nodes[node_id], f"graph.publish-nodes.{node_id}"
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        family = snapshot.get("family")
        if family not in {"rubygems", "github-release"}:
            continue
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{node_id}.projection",
        )
        if family == "rubygems":
            names_by_artifact_id = _mapping(
                projection.get(
                    "final-distribution-filenames-by-artifact-id", {}
                ),
                (
                    f"graph.publish-nodes.{node_id}.projection."
                    "final-distribution-filenames-by-artifact-id"
                ),
            )
            publish_identity = _mapping(
                node["resolved-publish-identity"],
                (f"graph.publish-nodes.{node_id}.resolved-publish-identity"),
            )
            package_name = publish_identity.get("package-name")
            package_version = publish_identity.get("version")
            if not isinstance(package_name, str) or not package_name:
                msg = (
                    f"Ruby gem publish node {node_id!r} is missing package-name"
                )
                raise RuntimeError(msg)
            if not isinstance(package_version, str) or not package_version:
                msg = f"Ruby gem publish node {node_id!r} is missing version"
                raise RuntimeError(msg)
        else:
            names_by_artifact_id = _mapping(
                projection.get("asset-names-by-artifact-id", {}),
                (
                    f"graph.publish-nodes.{node_id}.projection."
                    "asset-names-by-artifact-id"
                ),
            )
            package_name = ""
            package_version = ""
        for raw_artifact_id in node.get("artifact-ids", []):
            artifact_id = str(raw_artifact_id)
            artifact = _mapping(
                artifacts[artifact_id], f"graph.artifacts.{artifact_id}"
            )
            if artifact.get("concrete-kind") != "rubygem":
                continue
            filename = names_by_artifact_id.get(artifact_id)
            if not isinstance(filename, str) or not filename:
                msg = (
                    f"Ruby gem artifact {artifact_id!r} for publish node "
                    f"{node_id!r} has no planned filename"
                )
                raise RuntimeError(msg)
            if family == "github-release":
                package_name, package_version = (
                    _ruby_github_release_asset_identity(plan, node, filename)
                )
            candidate_identity = (package_name, package_version, filename)
            if (
                expected_identity is not None
                and expected_identity != candidate_identity
            ):
                msg = (
                    "conflicting active Ruby gem identities in finalized "
                    f"plan: {expected_identity!r} and {candidate_identity!r}"
                )
                raise RuntimeError(msg)
            expected_identity = candidate_identity
    if expected_identity is None:
        return ("", "", "", "")
    return (*expected_identity, "")


def _ruby_github_release_asset_identity(
    plan: Mapping[str, Any],
    node: Mapping[str, Any],
    filename: str,
) -> tuple[str, str]:
    """Derive Ruby package identity from a planned GitHub Release gem asset."""
    identity = _ruby_gem_filename_identity(filename)
    if identity is None:
        msg = (
            f"Ruby GitHub Release asset {filename!r} is not a normalized "
            "RubyGems asset filename"
        )
        raise RuntimeError(msg)
    return identity


def _ruby_gem_filename_identity(filename: str) -> tuple[str, str] | None:
    """Return package name/version from a normalized RubyGems asset filename."""
    match = re.fullmatch(
        r"(.+)-([0-9][0-9A-Za-z]*(?:\.[0-9A-Za-z]+)*)\.gem", filename
    )
    if match is None:
        return None
    return match.group(1), match.group(2)


def _planned_node_github_release_package_asset_name(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> str:
    """Return the unique GitHub Release npm package asset name, if planned."""
    graph = _mapping(plan["graph"], "graph")
    artifacts = _mapping(graph["artifacts"], "graph.artifacts")
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    identity: str | None = None
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            graph["publish-nodes"][node_id], f"graph.publish-nodes.{node_id}"
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if snapshot.get("family") != "github-release":
            continue
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{node_id}.projection",
        )
        asset_names = _mapping(
            projection.get("asset-names-by-artifact-id", {}),
            f"graph.publish-nodes.{node_id}.projection.asset-names-by-artifact-id",
        )
        for raw_artifact_id in node.get("artifact-ids", []):
            artifact_id = str(raw_artifact_id)
            artifact = _mapping(
                artifacts[artifact_id], f"graph.artifacts.{artifact_id}"
            )
            if artifact.get("concrete-kind") != "npm-package":
                continue
            candidate = asset_names.get(artifact_id)
            if not isinstance(candidate, str) or not candidate:
                msg = (
                    f"GitHub Release npm package artifact {artifact_id!r} for "
                    f"publish node {node_id!r} is missing an asset name"
                )
                raise RuntimeError(msg)
            if identity is not None and identity != candidate:
                msg = (
                    "conflicting GitHub Release npm package asset names in "
                    f"finalized plan: {identity!r} and {candidate!r}"
                )
                raise RuntimeError(msg)
            identity = candidate
    return identity or ""


def _planned_node_github_release_package_asset_sha256(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> str:
    """Return no GitHub Release npm asset SHA-256 evidence from the planner."""
    _ = plan, tuple(publish_node_ids)
    return ""


def _planned_node_github_release_package_name(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> str:
    """Return the unique projected GitHub Release npm package name, if planned."""
    graph = _mapping(plan["graph"], "graph")
    artifacts = {
        str(artifact_id): dict(
            _mapping(artifact, f"graph.artifacts.{artifact_id}")
        )
        for artifact_id, artifact in _mapping(
            graph["artifacts"], "graph.artifacts"
        ).items()
    }
    _materialize_npm_build_projections(graph, artifacts)
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    identity: str | None = None
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            graph["publish-nodes"][node_id], f"graph.publish-nodes.{node_id}"
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if snapshot.get("family") != "github-release":
            continue
        for raw_artifact_id in node.get("artifact-ids", []):
            artifact_id = str(raw_artifact_id)
            artifact = _mapping(
                artifacts[artifact_id], f"graph.artifacts.{artifact_id}"
            )
            if artifact.get("concrete-kind") != "npm-package":
                continue
            projection = _mapping(
                artifact.get("projection", {}),
                f"graph.artifacts.{artifact_id}.projection",
            )
            candidate = projection.get("package-name")
            if candidate is None:
                continue
            if not isinstance(candidate, str) or not candidate:
                msg = (
                    f"GitHub Release npm package artifact {artifact_id!r} has "
                    "a malformed projected package name"
                )
                raise RuntimeError(msg)
            if identity is not None and identity != candidate:
                msg = (
                    "conflicting GitHub Release npm package names in finalized "
                    f"plan: {identity!r} and {candidate!r}"
                )
                raise RuntimeError(msg)
            identity = candidate
    return identity or ""


def _planned_github_release_asset_labels_by_name(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> dict[str, str]:
    """Return planned GitHub Release asset labels keyed by asset basename."""
    graph = _mapping(plan["graph"], "graph")
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    labels_by_name: dict[str, str] = {}
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            graph["publish-nodes"][node_id], f"graph.publish-nodes.{node_id}"
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if snapshot.get("family") != "github-release":
            continue
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{node_id}.projection",
        )
        asset_names = _mapping(
            projection.get("asset-names-by-artifact-id", {}),
            f"graph.publish-nodes.{node_id}.projection.asset-names-by-artifact-id",
        )
        asset_labels = _mapping(
            projection.get("asset-labels-by-artifact-id", {}),
            f"graph.publish-nodes.{node_id}.projection.asset-labels-by-artifact-id",
        )
        for artifact_id, raw_label in asset_labels.items():
            asset_name = asset_names.get(str(artifact_id))
            if not isinstance(asset_name, str) or not asset_name:
                msg = (
                    f"GitHub Release asset label for artifact {artifact_id!r} "
                    f"on publish node {node_id!r} has no planned asset name"
                )
                raise RuntimeError(msg)
            if not isinstance(raw_label, str) or not raw_label:
                msg = (
                    f"GitHub Release asset label for artifact {artifact_id!r} "
                    f"on publish node {node_id!r} is malformed"
                )
                raise RuntimeError(msg)
            previous = labels_by_name.get(asset_name)
            if previous is not None and previous != raw_label:
                msg = (
                    f"conflicting GitHub Release labels for asset {asset_name!r}: "
                    f"{previous!r} and {raw_label!r}"
                )
                raise RuntimeError(msg)
            labels_by_name[asset_name] = raw_label
    return labels_by_name


def _planned_github_release_asset_names(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> list[str]:
    """Return planned GitHub Release asset basenames in deterministic order."""
    graph = _mapping(plan["graph"], "graph")
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    names: set[str] = set()
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            graph["publish-nodes"][node_id], f"graph.publish-nodes.{node_id}"
        )
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        if snapshot.get("family") != "github-release":
            continue
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{node_id}.projection",
        )
        asset_names = _mapping(
            projection.get("asset-names-by-artifact-id", {}),
            f"graph.publish-nodes.{node_id}.projection.asset-names-by-artifact-id",
        )
        for raw_artifact_id in node.get("artifact-ids", []):
            artifact_id = str(raw_artifact_id)
            candidate = asset_names.get(artifact_id)
            if not isinstance(candidate, str) or not candidate:
                msg = (
                    f"GitHub Release artifact {artifact_id!r} for publish node "
                    f"{node_id!r} is missing an asset name"
                )
                raise RuntimeError(msg)
            names.add(candidate)
    return sorted(names)


def _validate_github_release_coverage_inputs(
    *,
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    tag: str,
    active_node_ids: Sequence[str],
    asset_names: Sequence[str],
) -> None:
    """Fail closed unless caller GitHub Release coverage matches the plan."""
    if not tag:
        msg = "GitHub Release coverage validation requires a release tag"
        raise ValueError(msg)
    plan_id = _string(
        _mapping(plan["envelope"], "envelope").get("plan-id"),
        "envelope.plan-id",
    )
    if execution_sets.get("plan-id") != plan_id:
        msg = "execution-sets plan-id does not match release-plan envelope plan-id"
        raise ValueError(msg)
    _reject_duplicate_strings(
        active_node_ids,
        "active_github_release_node_ids_json",
    )
    _reject_duplicate_strings(asset_names, "asset_names_json")
    expected_node_ids = _expected_github_release_coverage_node_ids(
        plan,
        execution_sets,
        tag,
    )
    if not expected_node_ids:
        msg = (
            f"no active GitHub Release publish nodes for tag {tag!r} were "
            "present in the frozen execution sets"
        )
        raise ValueError(msg)
    if sorted(active_node_ids) != expected_node_ids:
        missing = sorted(set(expected_node_ids) - set(active_node_ids))
        extra = sorted(set(active_node_ids) - set(expected_node_ids))
        details = []
        if missing:
            details.append(f"missing coverage node ids: {', '.join(missing)}")
        if extra:
            details.append(f"unexpected coverage node ids: {', '.join(extra)}")
        suffix = f" ({'; '.join(details)})" if details else ""
        msg = (
            "active_github_release_node_ids_json must exactly match complete "
            f"same-release GitHub Release coverage for {tag!r}{suffix}"
        )
        raise ValueError(msg)
    expected_asset_names = _planned_github_release_asset_names(
        plan,
        expected_node_ids,
    )
    if sorted(asset_names) != expected_asset_names:
        missing = sorted(set(expected_asset_names) - set(asset_names))
        extra = sorted(set(asset_names) - set(expected_asset_names))
        details = []
        if missing:
            details.append(f"missing coverage assets: {', '.join(missing)}")
        if extra:
            details.append(f"unexpected coverage assets: {', '.join(extra)}")
        suffix = f" ({'; '.join(details)})" if details else ""
        msg = (
            "asset_names_json must exactly match complete same-release GitHub "
            f"Release coverage for {tag!r}{suffix}"
        )
        raise ValueError(msg)


def _expected_github_release_coverage_node_ids(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    tag: str,
) -> list[str]:
    graph = _mapping(plan["graph"], "graph")
    nodes = _mapping(graph["publish-nodes"], "graph.publish-nodes")
    snapshots = _mapping(
        graph["target-instance-snapshots"],
        "graph.target-instance-snapshots",
    )
    active_ids = _string_list(
        execution_sets.get("active-github-release-publish-node-ids", []),
        "execution-sets.active-github-release-publish-node-ids",
    )
    active_for_tag = [
        node_id
        for node_id in active_ids
        if _is_github_release_node_for_tag(nodes, snapshots, node_id, tag)
    ]
    if not active_for_tag:
        return []
    candidate_ids: list[str] = []
    for execution_set_key in (
        "active-github-release-publish-node-ids",
        "selected-github-release-publish-node-ids",
        "skip-satisfied-publish-node-ids",
    ):
        for node_id in _string_list(
            execution_sets.get(execution_set_key, []),
            f"execution-sets.{execution_set_key}",
        ):
            if node_id not in candidate_ids:
                candidate_ids.append(node_id)
    return sorted(
        node_id
        for node_id in candidate_ids
        if _is_github_release_node_for_tag(nodes, snapshots, node_id, tag)
    )


def _is_github_release_node_for_tag(
    nodes: Mapping[str, Any],
    snapshots: Mapping[str, Any],
    node_id: str,
    tag: str,
) -> bool:
    node = nodes.get(node_id)
    if not isinstance(node, Mapping):
        return False
    snapshot_id = node.get("target-instance-snapshot-id")
    if not isinstance(snapshot_id, str):
        return False
    snapshot = snapshots.get(snapshot_id)
    if (
        not isinstance(snapshot, Mapping)
        or snapshot.get("family") != "github-release"
    ):
        return False
    identity = node.get("resolved-publish-identity")
    release_tag = (
        identity.get("release-tag") if isinstance(identity, Mapping) else None
    )
    if release_tag != tag:
        return False
    disposition = node.get("publish-disposition")
    return disposition in {"publish", "skip-satisfied"}


def _reject_duplicate_strings(values: Sequence[str], label: str) -> None:
    seen: set[str] = set()
    duplicates: list[str] = []
    for value in values:
        if value in seen and value not in duplicates:
            duplicates.append(value)
        seen.add(value)
    if duplicates:
        msg = f"{label} contains duplicate entries: {', '.join(duplicates)}"
        raise ValueError(msg)


def _active_github_release_overwrite_mutable_authorized(
    plan: Mapping[str, Any], publish_node_ids: Iterable[object]
) -> bool:
    """Return whether active overwrite-mutable nodes carry planner authorization."""
    graph = _mapping(plan["graph"], "graph")
    target_snapshots = _mapping(
        graph["target-instance-snapshots"], "graph.target-instance-snapshots"
    )
    saw_overwrite = False
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        node = _mapping(
            graph["publish-nodes"][node_id], f"graph.publish-nodes.{node_id}"
        )
        if node.get("publish-mode") != "overwrite-mutable":
            continue
        saw_overwrite = True
        snapshot_id = str(node["target-instance-snapshot-id"])
        snapshot = _mapping(
            target_snapshots[snapshot_id],
            f"graph.target-instance-snapshots.{snapshot_id}",
        )
        capabilities = _mapping(
            snapshot.get("capabilities", {}),
            f"graph.target-instance-snapshots.{snapshot_id}.capabilities",
        )
        authorization = _mapping(
            node.get("overwrite-mutable-authorization", {}),
            f"graph.publish-nodes.{node_id}.overwrite-mutable-authorization",
        )
        if not (
            node.get("profile") == "buddy"
            and snapshot.get("family") == "github-release"
            and capabilities.get("mutability") == "mutable-prerelease"
            and authorization.get("kind") == "planner-validated-buddy-force"
            and authorization.get("profile") == "buddy"
            and authorization.get("force") is True
            and authorization.get("remote-observation") == "partial"
            and authorization.get("mutability") == "mutable-prerelease"
        ):
            return False
    return saw_overwrite


def _planned_target_key(snapshot: Mapping[str, Any]) -> str | None:
    """Map a target snapshot to an orchestrator coarse target key."""
    family = snapshot.get("family")
    instance_id = snapshot.get("instance-id")
    destination = snapshot.get("destination")
    host = destination.get("host") if isinstance(destination, Mapping) else None
    if family == "pypi" and (instance_id == "pypi" or host == "pypi.org"):
        return "python-pypi"
    if family == "npm":
        if instance_id == "github-packages" or host == "npm.pkg.github.com":
            return "node-gpr"
        if instance_id == "npmjs" or host == "registry.npmjs.org":
            return "node-npmjs"
    if family == "rubygems":
        if (
            instance_id == "github-packages"
            or host == "rubygems.pkg.github.com"
        ):
            return "ruby-gpr"
        if instance_id == "rubygems-org" or host == "rubygems.org":
            return "ruby-rubygems"
    return None


def _entry_publish_handoff(
    plan: Json, execution_sets: Json, run_id: int, attempt: int
) -> Json:
    plan_id = str(plan["envelope"]["plan-id"])
    entry_node_ids = sorted(
        execution_sets["active-publish-selectors"][
            "external-oidc-entry-workflow"
        ]
    )
    inputs = {
        node_id: _publish_input_names(plan, node_id, run_id, attempt)
        for node_id in entry_node_ids
    }
    return {
        "api-version": "three.release.entry-publish-handoff/v1alpha1",
        "kind": "entry-publish-handoff",
        "plan-id": plan_id,
        "commit-sha": plan["envelope"]["commit-sha"],
        "plan-artifact-name": artifact_name(
            "plan", ArtifactNameInputs(run_id, attempt, plan_id=plan_id)
        ),
        "execution-sets-artifact-name": artifact_name(
            "execution-sets",
            ArtifactNameInputs(run_id, attempt, plan_id=plan_id),
        ),
        "entry-publish-node-ids": entry_node_ids,
        "publish-inputs-by-node-id": inputs,
    }


def _publish_input_names(
    plan: Json, publish_node_id: str, run_id: int, attempt: int
) -> Json:
    plan_id = str(plan["envelope"]["plan-id"])
    node = plan["graph"]["publish-nodes"][publish_node_id]
    variant_ids = sorted(
        {
            plan["graph"]["artifacts"][artifact_id]["variant-id"]
            for artifact_id in node["artifact-ids"]
        }
    )
    return {
        "target-instance-snapshot-id": node["target-instance-snapshot-id"],
        "build-result-artifact-names": [
            artifact_name(
                "build-result",
                ArtifactNameInputs(
                    run_id, attempt, plan_id=plan_id, variant_id=variant_id
                ),
            )
            for variant_id in variant_ids
        ],
        "build-bundle-artifact-names": [
            artifact_name(
                "variant-bundle",
                ArtifactNameInputs(
                    run_id, attempt, plan_id=plan_id, variant_id=variant_id
                ),
            )
            for variant_id in variant_ids
        ],
    }


def _validate_handoff_inputs(
    handoff: Json, publish_node_id: str, expected: Json
) -> None:
    validate_contract(handoff)
    if publish_node_id not in handoff["entry-publish-node-ids"]:
        msg = f"{publish_node_id} is not present in entry-publish-handoff.json"
        raise ValueError(msg)
    actual = handoff["publish-inputs-by-node-id"][publish_node_id]
    if actual != expected:
        msg = f"{publish_node_id} build input names do not match the handoff"
        raise ValueError(msg)


def _download_artifact(
    repository: str, run_id: int, artifact_name_value: str, destination: Path
) -> None:
    destination.mkdir(parents=True, exist_ok=True)
    env = os.environ.copy()
    if "GH_TOKEN" not in env and "GITHUB_TOKEN" in env:
        env["GH_TOKEN"] = env["GITHUB_TOKEN"]
    result = subprocess.run(
        [
            "gh",
            "run",
            "download",
            str(run_id),
            "--repo",
            repository,
            "--name",
            artifact_name_value,
            "--dir",
            str(destination),
        ],
        cwd=Path.cwd(),
        env=env,
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        msg = (
            f"failed to download required artifact {artifact_name_value}: "
            f"{result.stderr.strip()}"
        )
        raise RuntimeError(msg)


def _download_artifact_by_id(
    repository: str,
    artifact_api: Mapping[str, object] | None,
    artifact_name_value: str,
    destination: Path,
) -> None:
    if artifact_api is None:
        msg = f"expected batch artifact {artifact_name_value} has no admitted artifact API identity"
        raise RuntimeError(msg)
    artifact_id = artifact_api.get("id")
    if artifact_id is None or not str(artifact_id):
        msg = f"expected batch artifact {artifact_name_value} has no admitted artifact id"
        raise RuntimeError(msg)
    if artifact_api.get("expired") is True:
        msg = f"expected batch artifact {artifact_name_value} is expired"
        raise RuntimeError(msg)
    destination.mkdir(parents=True, exist_ok=True)
    env = os.environ.copy()
    if "GH_TOKEN" not in env and "GITHUB_TOKEN" in env:
        env["GH_TOKEN"] = env["GITHUB_TOKEN"]
    endpoint = f"repos/{repository}/actions/artifacts/{artifact_id}/zip"
    result = subprocess.run(
        ["gh", "api", endpoint],
        cwd=Path.cwd(),
        env=env,
        capture_output=True,
        check=False,
    )
    if result.returncode != 0:
        msg = (
            f"failed to download admitted artifact id {artifact_id} "
            f"for {artifact_name_value}: {result.stderr.decode('utf-8', 'replace').strip()}"
        )
        raise RuntimeError(msg)
    try:
        with zipfile.ZipFile(io.BytesIO(result.stdout)) as archive:
            archive.extractall(destination)
    except zipfile.BadZipFile as exc:
        msg = (
            f"GitHub artifact id {artifact_id} for {artifact_name_value} "
            "did not return a readable zip archive"
        )
        raise RuntimeError(msg) from exc


def _workflow_artifact_ids_by_name(repository: str, run_id: int) -> Json:
    artifacts: Json = {}
    page = 1
    while True:
        payload = _gh_api(
            repository,
            f"repos/{repository}/actions/runs/{run_id}/artifacts?per_page=100&page={page}",
        )
        items = payload.get("artifacts", [])
        if not items:
            break
        for item in items:
            if not item.get("expired", False):
                artifacts[str(item["name"])] = int(item["id"])
        if len(items) < 100:
            break
        page += 1
    return artifacts


def _normalize_enablement(value: str, plan: Json) -> set[str]:
    known_oidc = _known_oidc_target_instance_refs()
    tokens = sorted(
        {
            item.strip()
            for chunk in value.split("\n")
            for item in chunk.split(",")
            if item.strip()
        }
    )
    for token in tokens:
        parts = token.split("#")
        if (
            len(parts) != 3
            or any(part == "" or "*" in part for part in parts)
            or parts[0] not in known_oidc
        ):
            diag = _diagnostic(
                "REQ_INVALID_INPUT",
                "validation",
                "request",
                "invalid external OIDC live-enable token",
                {"token": token},
            )
            raise RuntimeError(json.dumps(_diagnostics_document([diag])))
    return set(tokens)


def _known_oidc_target_instance_refs() -> set[str]:
    catalog = yaml.safe_load(
        (_REPO_ROOT / "eng/release/target-instances.yml").read_text(
            encoding="utf-8"
        )
    )
    if not isinstance(catalog, Mapping):
        return set()
    families = catalog.get("families", {})
    if not isinstance(families, Mapping):
        return set()
    return {
        f"{family_id}/{instance['id']}"
        for family_id, family in families.items()
        if isinstance(family, Mapping)
        for instance in family.get("instances", [])
        if isinstance(instance, Mapping)
        if instance.get("capabilities", {}).get("credential-posture") == "oidc"
    }


def _diagnostics_from_error(error: RuntimeError) -> Json | None:
    text = str(error)
    if not text.startswith("{"):
        return None
    try:
        document = json.loads(text)
    except json.JSONDecodeError:
        return None
    if not isinstance(document, dict):
        return None
    if document.get("kind") != "planner-diagnostics":
        return None
    validate_contract(document)
    return document


def _publish_request(
    plan: Json,
    node_id: str,
    run_id: int,
    attempt: int,
    build_results_dir: Path,
    bundles_dir: Path,
) -> Json:
    envelope = plan["envelope"]
    node = plan["graph"]["publish-nodes"][node_id]
    _require_publish_request_disposition(node, node_id)
    project_id = node["project-id"]
    snapshot_id = node["target-instance-snapshot-id"]
    artifacts: Json = {}
    for artifact_id in node["artifact-ids"]:
        artifact = plan["graph"]["artifacts"][artifact_id]
        variant_id = artifact["variant-id"]
        build_name = artifact_name(
            "build-result",
            ArtifactNameInputs(
                run_id,
                attempt,
                plan_id=envelope["plan-id"],
                variant_id=variant_id,
            ),
        )
        bundle_name = artifact_name(
            "variant-bundle",
            ArtifactNameInputs(
                run_id,
                attempt,
                plan_id=envelope["plan-id"],
                variant_id=variant_id,
            ),
        )
        build_result = _read_json(
            build_results_dir / build_name / "build-result.json"
        )
        receipt = build_result["artifacts"][artifact_id]
        artifacts[artifact_id] = {
            "artifact": artifact,
            "input-path": (
                bundles_dir / bundle_name / receipt["bundle-relative-path"]
            ).as_posix(),
            "bundle-relative-path": receipt["bundle-relative-path"],
            "sha256": receipt["sha256"],
            "byte-size": receipt["byte-size"],
        }
        if "archive" in receipt:
            artifacts[artifact_id]["archive"] = receipt["archive"]
    return {
        "api-version": "three.release.publish-request/v1alpha1",
        "kind": "publish-request",
        "plan-id": envelope["plan-id"],
        "profile": envelope["profile"],
        "commit-sha": envelope["commit-sha"],
        "publish-node-id": node_id,
        "project": envelope["projects"][project_id],
        "publish-node": {**node, "publish-node-id": node_id},
        "target-instance-snapshot": plan["graph"]["target-instance-snapshots"][
            snapshot_id
        ],
        "artifacts": artifacts,
    }


def _github_release_publish_request_from_asset_receipts(
    plan: Json,
    node_id: str,
    asset_receipts_path: Path,
    assets_dir: Path,
) -> Json:
    """Build a GitHub Release publish request from staged asset receipts."""
    envelope = plan["envelope"]
    node = plan["graph"]["publish-nodes"][node_id]
    _require_publish_request_disposition(node, node_id)
    project_id = node["project-id"]
    snapshot_id = node["target-instance-snapshot-id"]
    snapshot = plan["graph"]["target-instance-snapshots"][snapshot_id]
    if snapshot.get("family") != "github-release":
        msg = "--github-release-asset-receipts is valid only for GitHub Release nodes"
        raise ValueError(msg)
    projection = _mapping(
        node.get("projection"), f"publish-nodes.{node_id}.projection"
    )
    asset_names = _mapping(
        projection.get("asset-names-by-artifact-id"),
        f"publish-nodes.{node_id}.projection.asset-names-by-artifact-id",
    )
    receipts = _release_asset_receipts_by_name(asset_receipts_path)
    planned_names = {
        str(asset_names[str(artifact_id)])
        for artifact_id in node["artifact-ids"]
        if str(artifact_id) in asset_names
    }
    missing_names = planned_names - set(receipts)
    if missing_names:
        msg = (
            "GitHub Release asset receipts do not match the planned asset set: "
            f"missing {sorted(missing_names)!r} from {sorted(receipts)!r}"
        )
        raise ValueError(msg)
    artifacts: Json = {}
    for raw_artifact_id in node["artifact-ids"]:
        artifact_id = str(raw_artifact_id)
        asset_name = _string(asset_names.get(artifact_id), "asset-name")
        receipt = receipts[asset_name]
        asset_path = assets_dir / asset_name
        if not asset_path.is_file():
            msg = f"planned GitHub Release asset {asset_name!r} is missing"
            raise RuntimeError(msg)
        size = _int(receipt.get("size"), "asset-receipt.size")
        sha256 = _string(receipt.get("sha256"), "asset-receipt.sha256")
        if asset_path.stat().st_size != size:
            msg = f"planned GitHub Release asset {asset_name!r} size mismatch"
            raise RuntimeError(msg)
        if _file_sha256_bytes(asset_path) != sha256:
            msg = (
                f"planned GitHub Release asset {asset_name!r} SHA-256 mismatch"
            )
            raise RuntimeError(msg)
        artifacts[artifact_id] = {
            "artifact": plan["graph"]["artifacts"][artifact_id],
            "input-path": f"release-assets/{asset_name}",
            "bundle-relative-path": f"dist/{asset_name}",
            "sha256": sha256,
            "byte-size": size,
        }
    return {
        "api-version": "three.release.publish-request/v1alpha1",
        "kind": "publish-request",
        "plan-id": envelope["plan-id"],
        "profile": envelope["profile"],
        "commit-sha": envelope["commit-sha"],
        "publish-node-id": node_id,
        "project": envelope["projects"][project_id],
        "publish-node": {**node, "publish-node-id": node_id},
        "target-instance-snapshot": snapshot,
        "artifacts": artifacts,
    }


def _require_publish_request_disposition(
    node: Mapping[str, Any],
    node_id: str,
) -> None:
    if node.get("publish-disposition") != "publish":
        msg = (
            "publish-request materialization requires publish-disposition "
            f"'publish' for {node_id}"
        )
        raise ValueError(msg)


def _release_asset_receipts_by_name(path: Path) -> dict[str, Mapping[str, Any]]:
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, Sequence) or isinstance(payload, str | bytes):
        msg = "release asset receipts must be an array"
        raise TypeError(msg)
    receipts: dict[str, Mapping[str, Any]] = {}
    for item in payload:
        if not isinstance(item, Mapping):
            msg = "release asset receipt entries must be objects"
            raise TypeError(msg)
        name = _string(item.get("name"), "asset-receipt.name")
        if PurePosixPath(name).name != name:
            msg = f"release asset receipt name must be a basename: {name!r}"
            raise ValueError(msg)
        _int(item.get("size"), "asset-receipt.size")
        sha256 = _string(item.get("sha256"), "asset-receipt.sha256")
        if re.fullmatch(r"[0-9a-f]{64}", sha256) is None:
            msg = f"release asset receipt {name!r} has invalid sha256"
            raise ValueError(msg)
        if name in receipts:
            msg = f"duplicate release asset receipt for {name!r}"
            raise ValueError(msg)
        receipts[name] = item
    return receipts


def _proof_documents(
    plan: Json,
    publish_request: Json,
    publish_result: Json,
    publish_node_id: str,
    run: Json,
    artifact_ids_by_name: Json,
    build_results_dir: Path,
    run_id: int,
    attempt: int,
    asset_attestations: Json | None = None,
) -> list[tuple[str, Json]]:
    from three_workflow_release_proof import (  # noqa: PLC0415
        github_release_asset_proofs,
        immutable_proofs,
    )

    node = plan["graph"]["publish-nodes"][publish_node_id]
    snapshot = plan["graph"]["target-instance-snapshots"][
        node["target-instance-snapshot-id"]
    ]
    family = snapshot["family"]
    proofs: list[tuple[str, Json]] = []
    if family in {"nuget", "pypi", "npm", "rubygems"}:
        plan_id = str(plan["envelope"]["plan-id"])
        for variant_id in _publish_node_variant_ids(plan, publish_node_id):
            build_result_name = artifact_name(
                "build-result",
                ArtifactNameInputs(
                    run_id, attempt, plan_id=plan_id, variant_id=variant_id
                ),
            )
            bundle_name = artifact_name(
                "variant-bundle",
                ArtifactNameInputs(
                    run_id, attempt, plan_id=plan_id, variant_id=variant_id
                ),
            )
            build_result = _read_json(
                build_results_dir / build_result_name / "build-result.json"
            )
            build_result_artifact_id = artifact_ids_by_name.get(
                build_result_name
            )
            if not isinstance(build_result_artifact_id, int):
                msg = f"missing Actions artifact id for {build_result_name}"
                raise TypeError(msg)
            for proof in immutable_proofs(
                plan=plan,
                build_result=build_result,
                publish_node_id=publish_node_id,
                run=run,
                build_result_artifact_name=build_result_name,
                build_result_artifact_id=build_result_artifact_id,
                bundle_artifact_name=bundle_name,
            ):
                binding = proof["binding"]
                if not isinstance(binding, Mapping):
                    msg = "immutable proof binding must be an object"
                    raise TypeError(msg)
                name = artifact_name(
                    "immutable-proof",
                    ArtifactNameInputs(
                        run_id,
                        attempt,
                        binding_json=immutable_binding_json(
                            publish_node_id=str(binding["publish-node-id"]),
                            artifact_id=str(binding["artifact-id"]),
                            package_name=str(binding["package-name"]),
                            version=str(binding["version"]),
                        ),
                    ),
                )
                proofs.append((name, proof))
    elif family == "github-release":
        if asset_attestations is None:
            msg = "GitHub Release asset attestations are required for proof generation"
            raise TypeError(msg)
        for proof in github_release_asset_proofs(
            publish_request=publish_request,
            github_release_result=publish_result,
            asset_attestations=asset_attestations,
            run=run,
        ):
            binding = proof["binding"]
            if not isinstance(binding, Mapping):
                msg = "GitHub Release asset proof binding must be an object"
                raise TypeError(msg)
            name = artifact_name(
                "github-release-asset-proof",
                ArtifactNameInputs(
                    run_id,
                    attempt,
                    binding_json=github_release_asset_binding_json(
                        publish_node_id=str(binding["publish-node-id"]),
                        artifact_id=str(binding["artifact-id"]),
                        release_tag=str(binding["release-tag"]),
                        asset_name=str(binding["asset-name"]),
                    ),
                ),
            )
            proofs.append((name, proof))
    return proofs


def _entry_proof_upload_matrix(
    plan: Json,
    publish_node_ids: Sequence[str],
    run_id: int,
    attempt: int,
) -> list[Json]:
    plan_id = str(plan["envelope"]["plan-id"])
    matrix: list[Json] = []
    for publish_node_id in publish_node_ids:
        node = plan["graph"]["publish-nodes"][publish_node_id]
        snapshot = plan["graph"]["target-instance-snapshots"][
            node["target-instance-snapshot-id"]
        ]
        if snapshot["family"] == "github-release":
            identity = node["resolved-publish-identity"]
            result_name = artifact_name(
                "github-release-result",
                ArtifactNameInputs(
                    run_id,
                    attempt,
                    binding_json=json.dumps(
                        {
                            "tagName": identity["release-tag"],
                            "targetSha": plan["envelope"]["commit-sha"],
                        },
                        separators=(",", ":"),
                    ),
                ),
            )
        else:
            result_name = artifact_name(
                "publish-result",
                ArtifactNameInputs(
                    run_id,
                    attempt,
                    plan_id=plan_id,
                    publish_node_id=publish_node_id,
                ),
            )
        staging_artifact_name = f"proof-staging-{result_name}"
        for name in _planned_proof_artifact_names(
            plan, publish_node_id, run_id, attempt
        ):
            matrix.append(
                {
                    "name": name,
                    "file": f"{name}.json",
                    "staging-artifact-name": staging_artifact_name,
                }
            )
    return matrix


def _planned_proof_artifact_names(
    plan: Json,
    publish_node_id: str,
    run_id: int,
    attempt: int,
) -> list[str]:
    node = plan["graph"]["publish-nodes"][publish_node_id]
    snapshot = plan["graph"]["target-instance-snapshots"][
        node["target-instance-snapshot-id"]
    ]
    family = snapshot["family"]
    names: list[str] = []
    if family in {"nuget", "pypi", "npm", "rubygems"}:
        identity = node["resolved-publish-identity"]
        for artifact_id in node["artifact-ids"]:
            names.append(
                artifact_name(
                    "immutable-proof",
                    ArtifactNameInputs(
                        run_id,
                        attempt,
                        binding_json=immutable_binding_json(
                            publish_node_id=publish_node_id,
                            artifact_id=str(artifact_id),
                            package_name=str(identity["package-name"]),
                            version=str(identity["version"]),
                        ),
                    ),
                )
            )
    elif family == "github-release":
        identity = node["resolved-publish-identity"]
        projection = _mapping(
            node.get("projection", {}),
            f"graph.publish-nodes.{publish_node_id}.projection",
        )
        asset_names = _mapping(
            projection.get("asset-names-by-artifact-id", {}),
            (
                f"graph.publish-nodes.{publish_node_id}.projection."
                "asset-names-by-artifact-id"
            ),
        )
        for artifact_id in node["artifact-ids"]:
            names.append(
                artifact_name(
                    "github-release-asset-proof",
                    ArtifactNameInputs(
                        run_id,
                        attempt,
                        binding_json=github_release_asset_binding_json(
                            publish_node_id=publish_node_id,
                            artifact_id=str(artifact_id),
                            release_tag=str(identity["release-tag"]),
                            asset_name=str(asset_names[str(artifact_id)]),
                        ),
                    ),
                )
            )
    return names


def _publish_node_variant_ids(plan: Json, publish_node_id: str) -> list[str]:
    node = plan["graph"]["publish-nodes"][publish_node_id]
    return sorted(
        {
            plan["graph"]["artifacts"][artifact_id]["variant-id"]
            for artifact_id in node["artifact-ids"]
        }
    )


def _collect_artifact_names(
    root: Path | None,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
) -> Json:
    result: Json = {
        "plan-artifact-name": None,
        "planner-diagnostics-artifact-name": None,
        "dotnet-planner-metadata-input-artifact-name": None,
        "dotnet-planner-metadata-artifact-name": None,
        "execution-sets-artifact-name": None,
        "entry-publish-handoff-artifact-name": None,
        "tag-result-artifact-name": None,
        "build-result-artifact-names": [],
        "github-release-result-artifact-names": [],
        "publish-result-artifact-names": [],
        "skip-result-artifact-names": [],
    }
    if root is None or not root.exists():
        return result
    names = sorted(path.name for path in root.iterdir() if path.is_dir())
    prefix_fields = {
        "release-plan-v1-": "plan-artifact-name",
        "release-planner-diagnostics-v1-": "planner-diagnostics-artifact-name",
        "release-dotnet-planner-metadata-input-v1-": "dotnet-planner-metadata-input-artifact-name",
        "release-dotnet-planner-metadata-v1-": "dotnet-planner-metadata-artifact-name",
        "release-execution-sets-v1-": "execution-sets-artifact-name",
        "release-entry-publish-handoff-v1-": "entry-publish-handoff-artifact-name",
        "release-tag-result-v1-": "tag-result-artifact-name",
    }
    arrays = {
        "release-build-result-v1-": "build-result-artifact-names",
        "release-github-release-result-v1-": "github-release-result-artifact-names",
        "release-publish-result-v1-": "publish-result-artifact-names",
        "release-skip-result-v1-": "skip-result-artifact-names",
    }
    for name in names:
        for prefix, field in prefix_fields.items():
            if name.startswith(prefix):
                if not _artifact_name_matches_run_attempt(
                    name, prefix, run_id, attempt
                ):
                    continue
                result[field] = name
        for prefix, field in arrays.items():
            if name.startswith(prefix):
                if not _artifact_name_matches_run_attempt(
                    name, prefix, run_id, attempt
                ):
                    continue
                if (
                    field == "github-release-result-artifact-names"
                    and not (
                        root / name / "github-release-result.json"
                    ).is_file()
                ):
                    continue
                result[field].append(name)
    return result


def _artifact_name_matches_run_attempt(
    name: str,
    prefix: str,
    run_id: int | None,
    attempt: int | None,
) -> bool:
    if run_id is None or attempt is None:
        return True
    rest = name.removeprefix(prefix)
    expected = f"{run_id}-{attempt}"
    return rest == expected or rest.startswith(f"{expected}-")


def _failed_variant_ids(
    conclusion: str,
    plan: Json | None,
    execution_sets: Json | None,
    root: Path | None,
    artifacts: Json,
) -> list[str]:
    if conclusion != "failure" or plan is None or execution_sets is None:
        return []
    if root is None or not root.exists():
        return sorted(execution_sets["active-variant-ids"])
    plan_id = plan["envelope"]["plan-id"]
    succeeded = set()
    for name in artifacts["build-result-artifact-names"]:
        receipt = _read_receipt(root / name / "build-result.json")
        if (
            _is_valid_receipt(receipt)
            and receipt.get("kind") == "build-result"
            and receipt.get("api-version")
            == "three.release.build-result/v1alpha1"
            and receipt.get("plan-id") == plan_id
        ):
            variant_id = receipt.get("variant-id")
            if isinstance(variant_id, str):
                succeeded.add(variant_id)
    return sorted(set(execution_sets["active-variant-ids"]) - succeeded)


def _failed_publish_node_ids(
    conclusion: str,
    plan: Json | None,
    execution_sets: Json | None,
    root: Path | None,
    artifacts: Json,
    release_completed_check_conclusion: str | None = None,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
    disabled_package_target_keys: Iterable[str] = (),
) -> list[str]:
    if plan is None or execution_sets is None:
        return []
    if release_completed_check_conclusion == "failure":
        return _unsatisfied_active_publish_node_ids(
            plan,
            execution_sets,
            root,
            artifacts,
            run_id=run_id,
            attempt=attempt,
            disabled_package_target_keys=disabled_package_target_keys,
        )
    if conclusion == "success":
        return _unsatisfied_github_release_publish_node_ids(
            plan,
            execution_sets,
            root,
            artifacts,
            run_id=run_id,
            attempt=attempt,
        )
    if conclusion != "failure":
        return []
    active = _enabled_active_publish_node_ids(
        plan,
        execution_sets,
        disabled_package_target_keys,
    )
    if root is None or not root.exists():
        return sorted(active)
    succeeded = _succeeded_publish_node_ids(
        plan,
        execution_sets,
        root,
        artifacts,
        run_id=run_id,
        attempt=attempt,
    )
    return sorted(active - succeeded)


def _unsatisfied_active_publish_node_ids(
    plan: Json,
    execution_sets: Json,
    root: Path | None,
    artifacts: Json,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
    disabled_package_target_keys: Iterable[str] = (),
) -> list[str]:
    active = _enabled_publish_satisfaction_node_ids(
        plan,
        execution_sets,
        disabled_package_target_keys,
    )
    if not active:
        return []
    if root is None or not root.exists():
        return sorted(active)
    succeeded = _succeeded_publish_node_ids(
        plan,
        execution_sets,
        root,
        artifacts,
        run_id=run_id,
        attempt=attempt,
    )
    skip_required = _enabled_skip_satisfied_publish_node_ids(
        plan,
        execution_sets,
        disabled_package_target_keys,
    )
    if skip_required:
        succeeded.difference_update(skip_required)
        succeeded.update(
            _skip_satisfied_publish_node_ids(
                plan,
                execution_sets,
                root,
                artifacts,
                disabled_package_target_keys=disabled_package_target_keys,
            )
        )
    return sorted(active - succeeded)


def _enabled_publish_satisfaction_node_ids(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    disabled_package_target_keys: Iterable[str],
) -> set[str]:
    """Return enabled publish nodes that require completion receipts."""
    active = _enabled_active_publish_node_ids(
        plan,
        execution_sets,
        disabled_package_target_keys,
    )
    active.update(
        _expanded_active_github_release_publish_node_ids(plan, execution_sets),
    )
    active.update(
        _enabled_skip_satisfied_publish_node_ids(
            plan,
            execution_sets,
            disabled_package_target_keys,
        ),
    )
    return active


def _comma_separated_items(value: str) -> tuple[str, ...]:
    return tuple(item.strip() for item in value.split(",") if item.strip())


def _enabled_active_publish_node_ids(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    disabled_package_target_keys: Iterable[str],
) -> set[str]:
    active = {
        str(node_id) for node_id in execution_sets["active-publish-node-ids"]
    }
    disabled_keys = {key for key in disabled_package_target_keys if key}
    if not disabled_keys:
        return active
    return {
        node_id
        for node_id in active
        if not _publish_node_has_target_key(plan, node_id, disabled_keys)
    }


def _enabled_active_variant_ids(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    disabled_package_target_keys: Iterable[str],
) -> list[str]:
    """Return active variant ids still required after target disablement."""
    raw_active = [
        str(variant_id) for variant_id in execution_sets["active-variant-ids"]
    ]
    raw_active_set = set(raw_active)
    disabled_keys = {key for key in disabled_package_target_keys if key}
    if not disabled_keys:
        return raw_active
    active_nodes = _enabled_active_publish_node_ids(
        plan,
        execution_sets,
        disabled_keys,
    )
    active_nodes.update(
        _expanded_active_github_release_publish_node_ids(plan, execution_sets),
    )
    graph = plan.get("graph")
    if not isinstance(graph, Mapping):
        return []
    publish_nodes = graph.get("publish-nodes")
    artifacts = graph.get("artifacts")
    if not isinstance(publish_nodes, Mapping) or not isinstance(
        artifacts, Mapping
    ):
        return []
    required: set[str] = set()
    for node_id in active_nodes:
        node = publish_nodes.get(node_id)
        if not isinstance(node, Mapping):
            continue
        artifact_ids = node.get("artifact-ids", [])
        if not isinstance(artifact_ids, Sequence) or isinstance(
            artifact_ids,
            str | bytes,
        ):
            continue
        for raw_artifact_id in artifact_ids:
            artifact = artifacts.get(str(raw_artifact_id))
            if not isinstance(artifact, Mapping):
                continue
            variant_id = artifact.get("variant-id")
            if isinstance(variant_id, str) and variant_id in raw_active_set:
                required.add(variant_id)
    return [variant_id for variant_id in raw_active if variant_id in required]


def _enabled_publish_node_ids(
    plan: Mapping[str, Any],
    publish_node_ids: Iterable[object],
    disabled_package_target_keys: Iterable[str],
) -> list[str]:
    """Return publish node ids after removing explicitly disabled targets."""
    disabled_keys = {key for key in disabled_package_target_keys if key}
    result: list[str] = []
    for raw_node_id in publish_node_ids:
        node_id = str(raw_node_id)
        if disabled_keys and _publish_node_has_target_key(
            plan, node_id, disabled_keys
        ):
            continue
        result.append(node_id)
    return result


def _publish_selectors_without_disabled_target_keys(
    plan: Mapping[str, Any],
    selectors: Mapping[str, Any],
    disabled_package_target_keys: Iterable[str],
) -> dict[str, list[str]]:
    """Return active publish selectors with disabled target nodes removed."""
    disabled_keys = {key for key in disabled_package_target_keys if key}
    filtered: dict[str, list[str]] = {}
    for selector, node_ids in selectors.items():
        if not isinstance(node_ids, Sequence) or isinstance(
            node_ids, str | bytes
        ):
            filtered[str(selector)] = []
            continue
        filtered_node_ids: list[str] = []
        for raw_node_id in node_ids:
            node_id = str(raw_node_id)
            if disabled_keys and _publish_node_has_target_key(
                plan, node_id, disabled_keys
            ):
                continue
            filtered_node_ids.append(node_id)
        filtered[str(selector)] = filtered_node_ids
    return filtered


def _publish_node_has_target_key(
    plan: Mapping[str, Any],
    publish_node_id: str,
    target_keys: Collection[str],
) -> bool:
    """Return whether a publish node maps to one of the target keys."""
    graph = plan.get("graph")
    if not isinstance(graph, Mapping):
        return False
    nodes = graph.get("publish-nodes")
    snapshots = graph.get("target-instance-snapshots")
    if not isinstance(nodes, Mapping) or not isinstance(snapshots, Mapping):
        return False
    node = nodes.get(publish_node_id)
    if not isinstance(node, Mapping):
        return False
    snapshot_id = node.get("target-instance-snapshot-id")
    snapshot = (
        snapshots.get(snapshot_id) if isinstance(snapshot_id, str) else None
    )
    if not isinstance(snapshot, Mapping):
        return False
    key = _planned_target_key(snapshot)
    return key in target_keys


def _succeeded_publish_node_ids(
    plan: Json,
    execution_sets: Json,
    root: Path,
    artifacts: Json,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
) -> set[str]:
    succeeded = _package_registry_succeeded_publish_node_ids(
        plan,
        execution_sets,
        root,
        artifacts,
    )
    succeeded.update(
        _github_release_succeeded_publish_node_ids(
            plan,
            execution_sets,
            root,
            artifacts,
            run_id=run_id,
            attempt=attempt,
        ),
    )
    return succeeded


def _package_registry_succeeded_publish_node_ids(
    plan: Json,
    execution_sets: Json,
    root: Path,
    artifacts: Json,
) -> set[str]:
    plan_id = plan["envelope"]["plan-id"]
    active_publish_nodes = set(execution_sets["active-publish-node-ids"])
    active_github_release_nodes = set(
        execution_sets.get("active-github-release-publish-node-ids", []),
    )
    active_package_registry_nodes = (
        active_publish_nodes - active_github_release_nodes
    )
    succeeded: set[str] = set()
    for name in artifacts["publish-result-artifact-names"]:
        receipt = _read_receipt(root / name / "publish-result.json")
        if (
            _is_valid_receipt(receipt)
            and receipt.get("kind") == "publish-result"
            and receipt.get("api-version")
            == "three.release.publish-result/v1alpha1"
            and receipt.get("plan-id") == plan_id
        ):
            publish_node_id = receipt.get("publish-node-id")
            if (
                isinstance(publish_node_id, str)
                and publish_node_id in active_package_registry_nodes
            ):
                node = plan["graph"]["publish-nodes"].get(publish_node_id)
                if isinstance(
                    node, Mapping
                ) and _publish_result_matches_planned_node(receipt, node):
                    succeeded.add(publish_node_id)
    return succeeded


def _publish_result_matches_planned_node(
    receipt: Json,
    node: Mapping[str, Any],
) -> bool:
    identity = node.get("resolved-publish-identity")
    return (
        receipt.get("project-id") == node.get("project-id")
        and receipt.get("target-instance-snapshot-id")
        == node.get("target-instance-snapshot-id")
        and isinstance(identity, Mapping)
        and receipt.get("resolved-publish-identity") == identity
    )


def _skip_result_matches_planned_node(
    receipt: Json,
    node: Mapping[str, Any],
) -> bool:
    return (
        receipt.get("outcome") == "skip-satisfied"
        and receipt.get("reason-source") == "planner"
        and _publish_result_matches_planned_node(receipt, node)
    )


def _skip_satisfied_publish_node_ids(
    plan: Json,
    execution_sets: Json,
    root: Path,
    artifacts: Json,
    *,
    disabled_package_target_keys: Iterable[str] = (),
) -> set[str]:
    plan_id = plan["envelope"]["plan-id"]
    enabled_skip_nodes = _enabled_skip_satisfied_publish_node_ids(
        plan,
        execution_sets,
        disabled_package_target_keys,
    )
    succeeded: set[str] = set()
    for name in artifacts.get("skip-result-artifact-names", []):
        receipt = _read_receipt(root / name / "skip-result.json")
        if (
            _is_valid_receipt(receipt)
            and receipt.get("kind") == "skip-result"
            and receipt.get("api-version")
            == "three.release.skip-result/v1alpha1"
            and receipt.get("plan-id") == plan_id
        ):
            publish_node_id = receipt.get("publish-node-id")
            if (
                isinstance(publish_node_id, str)
                and publish_node_id in enabled_skip_nodes
            ):
                node = plan["graph"]["publish-nodes"].get(publish_node_id)
                if isinstance(
                    node,
                    Mapping,
                ) and _skip_result_matches_planned_node(receipt, node):
                    succeeded.add(publish_node_id)
    return succeeded


def _enabled_skip_satisfied_publish_node_ids(
    plan: Mapping[str, Any],
    execution_sets: Mapping[str, Any],
    disabled_package_target_keys: Iterable[str],
) -> set[str]:
    return set(
        _enabled_publish_node_ids(
            plan,
            execution_sets["skip-satisfied-publish-node-ids"],
            disabled_package_target_keys,
        ),
    )


def _github_release_succeeded_publish_node_ids(
    plan: Json,
    execution_sets: Json,
    root: Path,
    artifacts: Json,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
) -> set[str]:
    commit_sha = plan["envelope"]["commit-sha"]
    active_github_release_nodes = set(
        _expanded_active_github_release_publish_node_ids(plan, execution_sets),
    )
    succeeded: set[str] = set()
    for name in artifacts.get("github-release-result-artifact-names", []):
        receipt = _read_receipt(root / name / "github-release-result.json")
        if not _is_valid_receipt(receipt):
            continue
        if (
            receipt.get("kind") != "github-release-result"
            or receipt.get("api-version")
            != "three.release.github-release-result/v1alpha1"
            or receipt.get("targetSha") != commit_sha
        ):
            continue
        candidate_nodes = _github_release_receipt_candidate_nodes(
            plan,
            active_github_release_nodes,
            receipt,
        )
        if not _github_release_receipt_matches_planned_asset_union(
            receipt,
            candidate_nodes,
        ):
            continue
        for node_id, node in candidate_nodes.items():
            if _github_release_receipt_covers_planned_node_assets(
                receipt,
                node_id,
                node,
                plan,
                root,
                artifacts,
                run_id=run_id,
                attempt=attempt,
            ):
                succeeded.add(node_id)
    return succeeded


def _github_release_receipt_candidate_nodes(
    plan: Json,
    active_github_release_nodes: Iterable[str],
    receipt: Mapping[str, Any],
) -> dict[str, Mapping[str, Any]]:
    candidate_nodes: dict[str, Mapping[str, Any]] = {}
    for node_id in active_github_release_nodes:
        node = plan["graph"]["publish-nodes"].get(node_id)
        if not isinstance(node, Mapping):
            continue
        identity = node.get("resolved-publish-identity")
        if not isinstance(identity, Mapping) or identity.get(
            "release-tag"
        ) != receipt.get("tagName"):
            continue
        if not _github_release_receipt_matches_publish_mode(receipt, node):
            continue
        candidate_nodes[str(node_id)] = node
    return candidate_nodes


def _github_release_receipt_matches_publish_mode(
    receipt: Mapping[str, Any],
    node: Mapping[str, Any],
) -> bool:
    publish_mode = node.get("publish-mode")
    release_existed = receipt.get("releaseExisted")
    if node.get("publish-disposition") == "skip-satisfied":
        return "publish-mode" not in node and release_existed is True
    if publish_mode == "create-only":
        return release_existed is False or release_existed is True
    if not isinstance(publish_mode, str):
        return False
    expected = {
        "overwrite-mutable": True,
        "replace-authoritative": True,
    }.get(publish_mode)
    return expected is not None and release_existed is expected


def _github_release_result_assets_by_name(
    receipt: Mapping[str, Any],
) -> dict[str, Mapping[str, Any]]:
    assets: dict[str, Mapping[str, Any]] = {}
    raw_assets = receipt.get("assets")
    if not isinstance(raw_assets, Sequence) or isinstance(
        raw_assets, str | bytes
    ):
        return {}
    for asset in raw_assets:
        if not isinstance(asset, Mapping):
            return {}
        name = asset.get("name")
        size = asset.get("size")
        sha256 = asset.get("sha256")
        if (
            not isinstance(name, str)
            or type(size) is not int
            or not isinstance(sha256, str)
        ):
            return {}
        if name in assets:
            return {}
        assets[name] = asset
    return assets


def _github_release_receipt_matches_planned_asset_union(
    receipt: Json,
    nodes: Mapping[str, Mapping[str, Any]],
) -> bool:
    receipt_assets = _github_release_result_assets_by_name(receipt)
    if not nodes or not receipt_assets:
        return False
    planned_names: set[str] = set()
    for node in nodes.values():
        projection = node.get("projection")
        if not isinstance(projection, Mapping):
            return False
        asset_names = projection.get("asset-names-by-artifact-id")
        if not isinstance(asset_names, Mapping) or not asset_names:
            return False
        for raw_artifact_id in node.get("artifact-ids", []):
            artifact_id = str(raw_artifact_id)
            raw_name = asset_names.get(artifact_id)
            if not isinstance(raw_name, str) or not raw_name:
                return False
            planned_names.add(raw_name)
    return set(receipt_assets) == planned_names


def _github_release_receipt_covers_planned_node_assets(  # noqa: PLR0911
    receipt: Json,
    node_id: str,
    node: Mapping[str, Any],
    plan: Json,
    root: Path,
    _artifacts: Json,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
) -> bool:
    receipt_assets = _github_release_result_assets_by_name(receipt)
    planned_asset_names = _github_release_planned_node_asset_names(
        node,
        receipt_assets,
    )
    if planned_asset_names is None:
        return False

    disposition = node.get("publish-disposition")
    if disposition == "skip-satisfied":
        return True
    if disposition != "publish":
        return False

    proof_receipts = _github_release_asset_proof_receipts_by_artifact_id(
        plan,
        root,
        node_id,
        run_id=run_id,
        attempt=attempt,
    )

    planned: dict[str, tuple[str, int, str]] = {}
    for artifact_id, raw_name in planned_asset_names.items():
        proof_receipt = proof_receipts.get(artifact_id)
        if proof_receipt is None:
            return False
        proof_size = proof_receipt.get("byte-size")
        proof_sha256 = proof_receipt.get("sha256")
        if type(proof_size) is not int or not isinstance(proof_sha256, str):
            return False
        planned[raw_name] = (artifact_id, proof_size, proof_sha256)

    for asset_name, (
        _artifact_id,
        expected_size,
        expected_sha256,
    ) in planned.items():
        result_asset = receipt_assets[asset_name]
        if (
            result_asset.get("size") != expected_size
            or result_asset.get("sha256") != expected_sha256
        ):
            return False
    return True


def _github_release_planned_node_asset_names(
    node: Mapping[str, Any],
    receipt_assets: Mapping[str, Mapping[str, Any]],
) -> dict[str, str] | None:
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        return None
    asset_names = projection.get("asset-names-by-artifact-id")
    if not isinstance(asset_names, Mapping) or not asset_names:
        return None

    planned_asset_names: dict[str, str] = {}
    for raw_artifact_id in node.get("artifact-ids", []):
        artifact_id = str(raw_artifact_id)
        raw_name = asset_names.get(artifact_id)
        if not isinstance(raw_name, str) or not raw_name:
            return None
        if raw_name not in receipt_assets:
            return None
        planned_asset_names[artifact_id] = raw_name
    return planned_asset_names


def _github_release_asset_proof_receipts_by_artifact_id(  # noqa: C901, PLR0912
    plan: Json,
    root: Path,
    node_id: str,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
) -> dict[str, Mapping[str, Any]]:
    proofs: dict[str, Mapping[str, Any]] = {}
    conflicts: set[str] = set()
    node = plan["graph"]["publish-nodes"].get(node_id)
    if not isinstance(node, Mapping):
        return {}
    identity = node.get("resolved-publish-identity")
    projection = node.get("projection")
    if not isinstance(identity, Mapping) or not isinstance(projection, Mapping):
        return {}
    asset_names = projection.get("asset-names-by-artifact-id")
    if not isinstance(asset_names, Mapping):
        return {}
    for artifact_dir in sorted(root.iterdir() if root.exists() else []):
        if not artifact_dir.is_dir() or not artifact_dir.name.startswith(
            "release-github-release-asset-proof"
        ):
            continue
        if not _github_release_asset_proof_dir_matches_run_attempt(
            artifact_dir.name,
            run_id=run_id,
            attempt=attempt,
        ):
            continue
        for proof_path in sorted(artifact_dir.rglob("*.json")):
            if not _github_release_asset_proof_file_matches_run_attempt(
                proof_path.name,
                run_id=run_id,
                attempt=attempt,
            ):
                continue
            proof = _read_receipt(proof_path)
            if not _is_valid_receipt(proof):
                continue
            if (
                _github_release_asset_proof_sidecar_filename(proof)
                != proof_path.name
            ):
                continue
            if not _github_release_asset_proof_matches_completion_node(
                proof,
                plan,
                node_id,
                node,
                identity,
                asset_names,
                run_id=run_id,
                attempt=attempt,
            ):
                continue
            binding = cast("Mapping[str, Any]", proof["binding"])
            artifact = cast("Mapping[str, Any]", proof["artifact"])
            artifact_id = str(binding["artifact-id"])
            if artifact_id in conflicts:
                continue
            existing = proofs.get(artifact_id)
            if existing is not None and (
                existing.get("byte-size") != artifact.get("byte-size")
                or existing.get("sha256") != artifact.get("sha256")
            ):
                proofs.pop(artifact_id, None)
                conflicts.add(artifact_id)
                continue
            proofs[artifact_id] = artifact
    return proofs


def _github_release_asset_proof_dir_matches_run_attempt(
    name: str,
    *,
    run_id: int | None,
    attempt: int | None,
) -> bool:
    if run_id is None or attempt is None:
        return True
    plural_prefix = (
        f"release-github-release-asset-proofs-v1-{run_id}-{attempt}-"
    )
    if name.startswith(plural_prefix):
        return True
    singular_prefix = "release-github-release-asset-proof-v1-"
    if not name.startswith(singular_prefix):
        return False
    return name.endswith(f"-{run_id}-{attempt}")


def _github_release_asset_proof_file_matches_run_attempt(
    name: str,
    *,
    run_id: int | None,
    attempt: int | None,
) -> bool:
    if run_id is None or attempt is None:
        return True
    match = _GITHUB_RELEASE_ASSET_PROOF_SIDECAR_RE.fullmatch(name)
    return (
        match is not None
        and match.group("run_id") == str(run_id)
        and match.group("attempt") == str(attempt)
    )


def _github_release_asset_proof_matches_completion_node(  # noqa: PLR0911
    proof: Json,
    plan: Json,
    node_id: str,
    node: Mapping[str, Any],
    identity: Mapping[str, Any],
    asset_names: Mapping[str, Any],
    *,
    run_id: int | None = None,
    attempt: int | None = None,
) -> bool:
    if (
        proof.get("kind") != "github-release-asset-proof"
        or proof.get("api-version")
        != "three.release.github-release-asset-proof/v1alpha1"
        or proof.get("plan-id") != plan["envelope"]["plan-id"]
        or proof.get("project-id") != node.get("project-id")
    ):
        return False
    binding = proof.get("binding")
    artifact = proof.get("artifact")
    attestation = proof.get("attestation")
    run = proof.get("run")
    if (
        not isinstance(binding, Mapping)
        or not isinstance(artifact, Mapping)
        or not isinstance(attestation, Mapping)
        or not isinstance(run, Mapping)
    ):
        return False
    artifact_id = binding.get("artifact-id")
    if not isinstance(artifact_id, str) or artifact_id not in node.get(
        "artifact-ids",
        [],
    ):
        return False
    plan_artifact = plan["graph"]["artifacts"].get(artifact_id)
    if not isinstance(plan_artifact, Mapping):
        return False
    asset_name = asset_names.get(artifact_id)
    proof_size = artifact.get("byte-size")
    proof_sha256 = artifact.get("sha256")
    plan_id = plan["envelope"].get("plan-id")
    commit_sha = plan["envelope"].get("commit-sha")
    release_tag = identity.get("release-tag")
    signer_workflow = _planned_github_release_signer_workflow(node)
    repository = _planned_github_release_repository(plan, node)
    if (
        not isinstance(asset_name, str)
        or type(proof_size) is not int
        or not isinstance(proof_sha256, str)
        or not isinstance(plan_id, str)
        or not isinstance(commit_sha, str)
        or not isinstance(release_tag, str)
        or signer_workflow is None
        or repository is None
    ):
        return False
    if proof.get("variant-id") != plan_artifact.get("variant-id"):
        return False
    if run_id is not None and run.get("run-id") != run_id:
        return False
    if attempt is not None and run.get("run-attempt") != attempt:
        return False
    return _github_release_asset_wrapper_proof_matches(
        proof=proof,
        name=asset_name,
        artifact_id=artifact_id,
        expected_size=proof_size,
        expected_sha256=proof_sha256,
        node_id=node_id,
        node=cast("Json", node),
        repository=repository,
        commit_sha=commit_sha,
        tag=release_tag,
        signer_workflow=signer_workflow,
        plan_id=plan_id,
    )


def _unsatisfied_github_release_publish_node_ids(
    plan: Json,
    execution_sets: Json,
    root: Path | None,
    artifacts: Json,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
) -> list[str]:
    active = {
        str(node_id)
        for node_id in _expanded_active_github_release_publish_node_ids(
            plan,
            execution_sets,
        )
    }
    if not active:
        return []
    if root is None or not root.exists():
        return sorted(active)
    succeeded = _github_release_succeeded_publish_node_ids(
        plan,
        execution_sets,
        root,
        artifacts,
        run_id=run_id,
        attempt=attempt,
    )
    return sorted(active - succeeded)


def _is_valid_receipt(receipt: Json) -> bool:
    try:
        validate_contract(receipt)
    except ContractValidationError:
        return False
    return True


def _read_receipt(path: Path) -> Json:
    try:
        return _read_json(path)
    except (OSError, TypeError, ValueError):
        return {}


def _report_counts(
    plan: Json | None,
    execution_sets: Json | None,
    artifacts: Json,
    root: Path | None,
    *,
    run_id: int | None = None,
    attempt: int | None = None,
    disabled_package_target_keys: Iterable[str] = (),
) -> Json:
    if plan is None or execution_sets is None:
        published_nodes = len(artifacts["publish-result-artifact-names"]) + len(
            artifacts["github-release-result-artifact-names"]
        )
        return {
            "selected-projects": 0,
            "active-variants": 0,
            "active-publish-nodes": 0,
            "published-nodes": published_nodes,
            "skipped-publish-nodes": len(
                artifacts["skip-result-artifact-names"]
            ),
        }
    if root is not None and root.exists():
        enabled_active_publish_nodes = _enabled_active_publish_node_ids(
            plan,
            execution_sets,
            disabled_package_target_keys,
        )
        published_nodes = len(
            _succeeded_publish_node_ids(
                plan,
                execution_sets,
                root,
                artifacts,
                run_id=run_id,
                attempt=attempt,
            )
            & enabled_active_publish_nodes,
        )
        skipped_publish_nodes = len(
            _skip_satisfied_publish_node_ids(
                plan,
                execution_sets,
                root,
                artifacts,
                disabled_package_target_keys=disabled_package_target_keys,
            ),
        )
    else:
        published_nodes = len(artifacts["publish-result-artifact-names"]) + len(
            artifacts["github-release-result-artifact-names"]
        )
        skipped_publish_nodes = len(artifacts["skip-result-artifact-names"])
    return {
        "selected-projects": len(plan["envelope"]["selected-project-ids"]),
        "active-variants": len(
            _enabled_active_variant_ids(
                plan,
                execution_sets,
                disabled_package_target_keys,
            ),
        ),
        "active-publish-nodes": len(
            _enabled_active_publish_node_ids(
                plan,
                execution_sets,
                disabled_package_target_keys,
            ),
        ),
        "published-nodes": published_nodes,
        "skipped-publish-nodes": skipped_publish_nodes,
    }


def _overall_conclusion(
    args: argparse.Namespace,
    release_completed_check_conclusion: str | None = None,
) -> str:
    if release_completed_check_conclusion is None:
        release_completed_check_conclusion = getattr(
            args, "release_completed_check_conclusion", "skipped"
        )
    conclusions = [
        args.authorize_conclusion,
        args.validate_conclusion,
        args.metadata_conclusion,
        args.plan_conclusion,
        args.build_conclusion,
        args.tag_conclusion,
        release_completed_check_conclusion,
        args.publish_conclusion,
    ]
    if "failure" in conclusions:
        return "failure"
    if "cancelled" in conclusions:
        return "cancelled"
    if "success" in conclusions:
        return "success"
    return "skipped"


def _append_summary(report: Json) -> None:
    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if not summary:
        return
    lines = [
        "## Workflow Release Report",
        "",
        f"Conclusion: `{report['run']['conclusion']}`",
        f"Plan: `{report['plan']['plan-id']}`",
        "Canary non-public-ref override: "
        f"`{_bool_str(report['run']['canary-override-non-public-ref'])}`",
        "",
        "| Count | Value |",
        "| --- | ---: |",
    ]
    for key, value in report["counts"].items():
        lines.append(f"| {key} | {value} |")
    Path(summary).open("a", encoding="utf-8").write("\n".join(lines) + "\n")


def _actor_permission(repository: str, actor: str) -> str:
    try:
        return str(
            _gh_api(
                repository,
                f"repos/{repository}/collaborators/{urllib.parse.quote(actor, safe='')}/permission",
            )["permission"]
        )
    except (RuntimeError, KeyError, TypeError):
        return "none"


def _resolve_ref(
    repository: str, ref_type: str, ref_name: str
) -> tuple[str | None, Json]:
    api_ref = (
        f"heads/{ref_name}" if ref_type == "branch" else f"tags/{ref_name}"
    )
    try:
        payload = _gh_api(
            repository,
            f"repos/{repository}/git/ref/{urllib.parse.quote(api_ref, safe='/')}",
        )
        obj = payload["object"]
        obj_type = str(obj["type"])
        sha = str(obj["sha"])
        if obj_type == "commit":
            return sha, {"object-type": obj_type}
        if obj_type == "tag":
            return _peel_tag(repository, sha), {
                "object-type": obj_type,
                "tag-object-sha": sha,
            }
    except (RuntimeError, KeyError, TypeError):
        return None, {"error": "ref lookup failed"}
    return None, {"object-type": obj_type}


def _peel_tag(repository: str, sha: str) -> str | None:
    current = sha
    for _ in range(8):
        payload = _gh_api(repository, f"repos/{repository}/git/tags/{current}")
        obj = payload["object"]
        obj_type = str(obj["type"])
        current = str(obj["sha"])
        if obj_type == "commit":
            return current
        if obj_type != "tag":
            return None
    return None


def _trusted_ref(repository: str, ref_type: str, ref_name: str) -> bool:
    if ref_type == "branch":
        repo = _gh_api(repository, f"repos/{repository}")
        if ref_name == repo.get("default_branch"):
            return True
        try:
            branch = _gh_api(
                repository,
                f"repos/{repository}/branches/{urllib.parse.quote(ref_name, safe='')}",
            )
            if branch.get("protected") is True:
                return True
        except RuntimeError:
            pass
        try:
            return bool(
                _gh_api(
                    repository,
                    f"repos/{repository}/rules/branches/{urllib.parse.quote(ref_name, safe='')}",
                )
                or []
            )
        except RuntimeError:
            return False
    return _tag_has_active_ruleset(repository, ref_name)


def _official_public_ref_diagnostics(
    full_ref: str,
    requested_project_ids: Sequence[str],
    *,
    canary_override: bool,
) -> list[Json]:
    projects = _release_project_public_ref_specs()
    release_tag_identity = _release_tag_identity(full_ref)
    selected_ids = (
        list(requested_project_ids)
        if requested_project_ids
        else sorted(projects)
    )
    diagnostics: list[Json] = []
    unknown_ids = [
        project_id for project_id in selected_ids if project_id not in projects
    ]
    for project_id in unknown_ids:
        diagnostics.append(
            _diagnostic(
                "REQ_PROJECT_NOT_FOUND",
                "validation",
                "project",
                f"requested project {project_id!r} is not an in-scope releasable project",
                {"requested-project-id": project_id},
                project_id=project_id,
            )
        )
    selected_known = [
        project_id for project_id in selected_ids if project_id in projects
    ]
    disallowed = [
        project_id
        for project_id in selected_known
        if not _matches_public_release_ref_spec(full_ref, projects[project_id])
    ]
    if release_tag_identity is not None and selected_known == [
        release_tag_identity[0]
    ]:
        disallowed = []
    if not disallowed:
        if (
            canary_override
            and set(selected_ids) - _OFFICIAL_NON_PUBLIC_REF_CANARY_PROJECTS
        ):
            diagnostics.append(_canary_override_scope_diagnostic(selected_ids))
        return diagnostics
    if canary_override:
        if set(selected_ids) <= _OFFICIAL_NON_PUBLIC_REF_CANARY_PROJECTS:
            return diagnostics
        diagnostics.append(_canary_override_scope_diagnostic(selected_ids))
        return diagnostics
    for project_id in disallowed:
        diagnostic_details = {
            "ref": full_ref,
            "publicReleaseRefSpec": projects[project_id],
            "canary-override-non-public-ref": False,
        }
        if release_tag_identity is not None:
            diagnostic_details["release-tag-project"] = release_tag_identity[0]
            diagnostic_details["release-tag-version"] = release_tag_identity[1]
        diagnostics.append(
            _diagnostic(
                "REQ_UNTRUSTED_WORKFLOW_REF",
                "validation",
                "project",
                (
                    "official release tag does not match the selected project's "
                    "release identity"
                    if release_tag_identity is not None
                    else "official release ref does not match the project's NBGV "
                    "publicReleaseRefSpec"
                ),
                diagnostic_details,
                project_id=project_id,
            )
        )
    return diagnostics


def _canary_override_scope_diagnostic(project_ids: Sequence[str]) -> Json:
    return _diagnostic(
        "REQ_INVALID_INPUT",
        "validation",
        "request",
        "canary non-public-ref override is allowlisted only for dedicated release-smoke projects",
        {
            "requested-project-ids": sorted(project_ids),
            "allowed-project-ids": sorted(
                _OFFICIAL_NON_PUBLIC_REF_CANARY_PROJECTS
            ),
            "canary-override-non-public-ref": True,
        },
    )


@functools.lru_cache(maxsize=1)
def _release_project_aliases() -> dict[str, str]:
    aliases: dict[str, str] = {}
    for descriptor in sorted(_REPO_ROOT.glob("src/**/three.release.yml")):
        document = yaml.safe_load(descriptor.read_text(encoding="utf-8"))
        if not isinstance(document, Mapping):
            continue
        project = document.get("project")
        if not isinstance(project, Mapping) or not isinstance(
            project.get("id"), str
        ):
            continue
        project_id = str(project["id"])
        _register_release_project_alias(aliases, project_id, project_id)
        display_name = project.get("display-name")
        if isinstance(display_name, str) and display_name:
            _register_release_project_alias(aliases, display_name, project_id)
    return aliases


def _register_release_project_alias(
    aliases: dict[str, str], alias: str, project_id: str
) -> None:
    existing = aliases.get(alias)
    if existing is None:
        aliases[alias] = project_id
        return
    if existing != project_id:
        msg = (
            f"release project alias {alias!r} maps to multiple project ids: "
            f"{existing!r}, {project_id!r}"
        )
        raise RuntimeError(msg)


def _resolve_release_project_id(project: str) -> str | None:
    return _release_project_aliases().get(project)


def _cmd_resolve_project(args: argparse.Namespace) -> int:
    project_id = _resolve_release_project_id(args.project)
    if project_id is None:
        print(f"Unknown release project: {args.project}", file=sys.stderr)
        return 1
    _write_outputs(args.github_output, {"project_id": project_id})
    if not args.github_output:
        print(json.dumps({"project_id": project_id}, separators=(",", ":")))
    return 0


@functools.lru_cache(maxsize=1)
def _release_project_public_ref_specs() -> dict[str, list[str]]:
    projects: dict[str, list[str]] = {}
    for descriptor in sorted(_REPO_ROOT.glob("src/**/three.release.yml")):
        document = yaml.safe_load(descriptor.read_text(encoding="utf-8"))
        if not isinstance(document, Mapping):
            continue
        project = document.get("project")
        if not isinstance(project, Mapping) or not isinstance(
            project.get("id"), str
        ):
            continue
        spec = _nearest_public_release_ref_spec(descriptor.parent)
        project_id = str(project["id"])
        projects[project_id] = spec
        display_name = project.get("display-name")
        if isinstance(display_name, str) and display_name not in projects:
            projects[display_name] = spec
    return projects


def _nearest_public_release_ref_spec(project_dir: Path) -> list[str]:
    for current in (project_dir, *_repo_relative_parents(project_dir)):
        version_json = current / "version.json"
        if not version_json.is_file():
            continue
        document = json.loads(version_json.read_text(encoding="utf-8"))
        spec = document.get("publicReleaseRefSpec")
        if isinstance(spec, list) and all(
            isinstance(item, str) for item in spec
        ):
            return list(spec)
    return []


def _repo_relative_parents(path: Path) -> list[Path]:
    parents: list[Path] = []
    current = path
    while current != _REPO_ROOT and _REPO_ROOT in current.parents:
        current = current.parent
        parents.append(current)
    return parents


def _matches_public_release_ref_spec(
    full_ref: str, patterns: Sequence[str]
) -> bool:
    return any(re.fullmatch(pattern, full_ref) for pattern in patterns)


def _release_tag_identity(full_ref: str) -> tuple[str, str] | None:
    match = _OFFICIAL_RELEASE_TAG_REF_RE.fullmatch(full_ref)
    if match is None:
        return None
    return match["project"], match["version"]


def _tag_has_active_ruleset(repository: str, tag_name: str) -> bool:
    try:
        rulesets = _gh_api(
            repository,
            f"repos/{repository}/rulesets?targets=tag&includes_parents=true&per_page=100",
        )
    except RuntimeError:
        return False
    if not isinstance(rulesets, list):
        return False
    for item in rulesets:
        if item.get("enforcement") not in {"active", "enabled"}:
            continue
        ruleset_id = item.get("id")
        if not isinstance(ruleset_id, int):
            continue
        detail = _gh_api(
            repository, f"repos/{repository}/rulesets/{ruleset_id}"
        )
        if (
            detail.get("target") == "tag"
            and detail.get("enforcement") in {"active", "enabled"}
            and _ruleset_ref_matches(detail, tag_name)
        ):
            return True
    return False


def _ruleset_ref_matches(ruleset: Mapping[str, Any], ref_name: str) -> bool:
    ref = f"refs/tags/{ref_name}"
    conditions = ruleset.get("conditions")
    if not isinstance(conditions, Mapping):
        return True
    ref_condition = conditions.get("ref_name")
    if not isinstance(ref_condition, Mapping):
        return True
    include_value = ref_condition.get("include")
    includes = include_value if isinstance(include_value, list) else ["~ALL"]
    exclude_value = ref_condition.get("exclude")
    excludes = exclude_value if isinstance(exclude_value, list) else []
    return any(
        _ref_pattern_matches(str(pattern), ref_name, ref)
        for pattern in includes
    ) and not any(
        _ref_pattern_matches(str(pattern), ref_name, ref)
        for pattern in excludes
    )


def _ref_pattern_matches(pattern: str, name: str, full_ref: str) -> bool:
    if pattern == "~ALL":
        return True
    return fnmatch.fnmatchcase(name, pattern) or fnmatch.fnmatchcase(
        full_ref, pattern
    )


def _remote_tag_commit(repository: str, tag: str) -> str | None:
    try:
        payload = _gh_api(
            repository,
            f"repos/{repository}/git/ref/{urllib.parse.quote(f'tags/{tag}', safe='/')}",
        )
    except RuntimeError as exc:
        if _is_github_not_found_error(exc):
            return None
        raise
    obj = payload["object"]
    if obj["type"] == "commit":
        return str(obj["sha"])
    if obj["type"] == "tag":
        peeled = _peel_tag(repository, str(obj["sha"]))
        if peeled is not None:
            return peeled
        msg = f"existing tag {tag!r} cannot be peeled to a commit"
        raise RuntimeError(msg)
    msg = f"existing tag {tag!r} points to unsupported object type {obj['type']!r}"
    raise RuntimeError(msg)


def _observe_github_release_publication(
    repository: str,
    commit_sha: str,
    node_id: str,
    node: Json,
    *,
    plan_id: str | None = None,
    artifact_variant_ids_by_id: Mapping[str, object] | None = None,
    release_group_nodes: Mapping[str, Json] | None = None,
    release_group_variant_ids: Mapping[str, Mapping[str, object]] | None = None,
    allow_official_tag_retarget: bool = False,
) -> str:
    identity = node["resolved-publish-identity"]
    tag = str(identity["release-tag"])
    tag_commit = _remote_tag_commit(repository, tag)
    tag_mismatch = tag_commit is not None and tag_commit != commit_sha
    if tag_mismatch and not allow_official_tag_retarget:
        return "conflicting"
    release = _github_release_by_tag(repository, tag)
    if release is None:
        return "absent"
    if tag_commit is None:
        return "conflicting"
    observation = _classify_github_release_payload(
        release,
        node_id,
        node,
        repository,
        commit_sha,
        tag,
        plan_id=plan_id,
        artifact_variant_ids_by_id=artifact_variant_ids_by_id,
        release_group_nodes=release_group_nodes,
        release_group_variant_ids=release_group_variant_ids,
    )
    if tag_mismatch and observation == "exact-satisfied":
        desired = node.get("desired-publish-state", {})
        if (
            isinstance(desired, Mapping)
            and desired.get("release-state") == "release"
        ):
            return "partial-authoritative"
    return observation


def _observe_pypi_publication(node: Json) -> str:  # noqa: C901, PLR0911
    package_name, version = _package_publish_identity(node, "PyPI")
    payload = _pypi_project_json(package_name)
    if payload is None:
        return "absent"
    releases = payload.get("releases")
    if not isinstance(releases, Mapping):
        msg = f"PyPI JSON API payload for {package_name!r} is missing releases"
        raise TypeError(msg)
    if version not in releases:
        return "absent"
    files = releases[version]
    if not isinstance(files, list):
        msg = (
            f"PyPI JSON API payload for {package_name!r} version {version!r} "
            "has malformed release files"
        )
        raise TypeError(msg)
    expected_filenames_by_artifact_id = _planned_distribution_filenames(
        node, "PyPI"
    )
    if len(set(expected_filenames_by_artifact_id.values())) != len(
        expected_filenames_by_artifact_id
    ):
        return "conflicting"
    expected_filenames = set(expected_filenames_by_artifact_id.values())
    observed_files = _pypi_release_files_by_filename(
        files, package_name, version
    )
    if observed_files is None:
        return "conflicting"
    observed_filenames = set(observed_files)
    extra_filenames = observed_filenames - expected_filenames
    if extra_filenames:
        return "conflicting"
    if expected_filenames - observed_filenames:
        return "partial"
    expected_sha256_by_filename = _planned_distribution_sha256_by_filename(
        node, expected_filenames_by_artifact_id
    )
    if set(expected_sha256_by_filename) != expected_filenames:
        return "partial"
    for filename, expected_sha256 in expected_sha256_by_filename.items():
        observed_sha256 = _pypi_release_file_sha256(observed_files[filename])
        if observed_sha256 is None:
            return "partial"
        if observed_sha256 != expected_sha256:
            return "conflicting"
    return "exact-satisfied"


def _planned_distribution_filenames(
    node: Json, registry_name: str
) -> dict[str, str]:
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        msg = f"{registry_name} publish node is missing projection"
        raise TypeError(msg)
    filenames = projection.get("final-distribution-filenames-by-artifact-id")
    if not isinstance(filenames, Mapping):
        msg = (
            f"{registry_name} publish node projection is missing final "
            "distribution filenames"
        )
        raise TypeError(msg)
    result: dict[str, str] = {}
    for artifact_id, filename in filenames.items():
        if not isinstance(artifact_id, str) or not artifact_id:
            msg = (
                f"{registry_name} publish node projection has malformed "
                "artifact id"
            )
            raise TypeError(msg)
        if not isinstance(filename, str) or not filename:
            msg = (
                f"{registry_name} publish node projection has malformed "
                "distribution filename"
            )
            raise TypeError(msg)
        result[artifact_id] = filename
    if not result:
        msg = f"{registry_name} publish node projection has no distribution filenames"
        raise TypeError(msg)
    return result


def _pypi_release_files_by_filename(
    files: Sequence[object], package_name: str, version: str
) -> dict[str, Mapping[str, Any]] | None:
    observed: dict[str, Mapping[str, Any]] = {}
    for item in files:
        if not isinstance(item, Mapping):
            msg = (
                f"PyPI JSON API payload for {package_name!r} version {version!r} "
                "contains a malformed release file"
            )
            raise TypeError(msg)
        filename = item.get("filename")
        if not isinstance(filename, str) or not filename:
            msg = (
                f"PyPI JSON API payload for {package_name!r} version {version!r} "
                "contains a release file without filename"
            )
            raise TypeError(msg)
        if filename in observed:
            return None
        observed[filename] = item
    return observed


def _planned_distribution_sha256_by_filename(
    node: Json, filenames_by_artifact_id: Mapping[str, str]
) -> dict[str, str]:
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        return {}
    expected: dict[str, str] = {}
    raw_by_artifact_id = projection.get(
        "final-distribution-sha256-by-artifact-id"
    )
    if not isinstance(raw_by_artifact_id, Mapping):
        return expected
    for artifact_id, raw_digest in raw_by_artifact_id.items():
        if not isinstance(artifact_id, str):
            continue
        filename = filenames_by_artifact_id.get(artifact_id)
        if filename is None:
            continue
        digest = _normalize_sha256_digest(raw_digest)
        if digest is not None:
            expected[filename] = digest
    return expected


def _pypi_release_file_sha256(file: Mapping[str, Any]) -> str | None:
    digests = file.get("digests")
    if not isinstance(digests, Mapping):
        return None
    value = digests.get("sha256")
    if not isinstance(value, str):
        return None
    if re.fullmatch(r"[0-9a-f]{64}", value) is None:
        return None
    return value


def _normalize_sha256_digest(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    digest = value.removeprefix("sha256:")
    if re.fullmatch(r"[0-9a-f]{64}", digest) is None:
        return None
    return digest


def _observe_nuget_publication(node: Json) -> str:
    package_name, version = _package_publish_identity(node, "NuGet")
    planned_version = _nuget_version_key(version)
    payload = _nuget_versions_json(package_name)
    if payload is None:
        return "absent"
    versions = payload.get("versions")
    if not isinstance(versions, list) or not all(
        isinstance(item, str) and item for item in versions
    ):
        msg = (
            f"NuGet flat-container payload for {package_name!r} "
            "is missing valid versions"
        )
        raise TypeError(msg)
    observed = {_nuget_version_key(item) for item in versions}
    if planned_version in observed:
        return "exact-satisfied"
    return "absent"


def _observe_github_packages_nuget_publication(
    repository: str,
    node: Json,
    snapshot: Mapping[str, Any],
) -> str:
    package_name, version = _package_publish_identity(
        node, "GitHub Packages NuGet"
    )
    planned_version = _nuget_version_key(version)
    owner = _github_packages_owner(repository, snapshot)
    package = _github_packages_nuget_package(
        repository,
        owner,
        package_name,
    )
    if package is None:
        return "absent"
    remote_package_name = str(package["name"])
    versions = _github_packages_nuget_versions(
        repository, owner, remote_package_name
    )
    observed: set[str] = set()
    for item in versions:
        if not isinstance(item, Mapping):
            msg = (
                "GitHub Packages NuGet versions API returned a malformed "
                f"version item for {remote_package_name!r}"
            )
            raise TypeError(msg)
        version_name = item.get("name")
        if not isinstance(version_name, str) or not version_name:
            msg = (
                "GitHub Packages NuGet versions API returned a version item "
                f"without name for {remote_package_name!r}"
            )
            raise TypeError(msg)
        observed.add(_nuget_version_key(version_name))
    if planned_version in observed:
        return "exact-satisfied"
    return "absent"


def _observe_github_packages_publication(
    repository: str,
    node: Json,
    snapshot: Mapping[str, Any],
) -> str:
    family = str(snapshot.get("family"))
    if family == "nuget":
        return _observe_github_packages_nuget_publication(
            repository,
            node,
            snapshot,
        )
    if family in {"npm", "rubygems"}:
        return "absent"
    package_name, version = _package_publish_identity(
        node, f"GitHub Packages {family}"
    )
    owner = _github_packages_owner(repository, snapshot)
    package = _github_packages_package(
        repository,
        owner,
        family,
        package_name,
    )
    if package is None:
        return "absent"
    remote_package_name = str(package["name"])
    versions = _github_packages_versions(
        repository, owner, family, remote_package_name
    )
    for item in versions:
        if not isinstance(item, Mapping):
            msg = (
                f"GitHub Packages {family} versions API returned a malformed "
                f"version item for {remote_package_name!r}"
            )
            raise TypeError(msg)
        version_name = item.get("name")
        if not isinstance(version_name, str) or not version_name:
            msg = (
                f"GitHub Packages {family} versions API returned a version item "
                f"without name for {remote_package_name!r}"
            )
            raise TypeError(msg)
        if version_name == version:
            return "partial"
    return "absent"


def _observe_npm_publication(node: Json) -> str:
    package_name, version = _package_publish_identity(node, "npm")
    payload = _npm_package_json(package_name)
    if payload is None:
        return "absent"
    versions = payload.get("versions")
    if not isinstance(versions, Mapping):
        msg = f"npm registry payload for {package_name!r} is missing versions"
        raise TypeError(msg)
    if version not in versions:
        return "absent"
    version_payload = versions[version]
    if not isinstance(version_payload, Mapping):
        msg = (
            f"npm registry payload for {package_name!r} version {version!r} "
            "is malformed"
        )
        raise TypeError(msg)
    return _classify_npm_version_payload(node, version_payload)


def _classify_npm_version_payload(
    node: Json, version_payload: Mapping[str, Any]
) -> str:
    expected_filenames_by_artifact_id = _planned_distribution_filenames(
        node, "npm"
    )
    if len(set(expected_filenames_by_artifact_id.values())) != len(
        expected_filenames_by_artifact_id
    ):
        return "conflicting"
    expected_filenames = set(expected_filenames_by_artifact_id.values())
    observed_filename = _npm_version_tarball_filename(version_payload, node)
    if observed_filename is None:
        return "partial"
    filename_classification = _classify_distribution_filename_sets(
        expected_filenames, {observed_filename}
    )
    if filename_classification is not None:
        return filename_classification
    dist = version_payload.get("dist")
    return _classify_npm_digest_evidence(
        node, expected_filenames_by_artifact_id, dist
    )


def _classify_distribution_filename_sets(
    expected_filenames: set[str], observed_filenames: set[str]
) -> str | None:
    if observed_filenames - expected_filenames:
        return "conflicting"
    if expected_filenames - observed_filenames:
        return "partial"
    return None


def _classify_npm_digest_evidence(  # noqa: PLR0911
    node: Json,
    expected_filenames_by_artifact_id: Mapping[str, str],
    dist: object,
) -> str:
    expected_digests_by_filename = _planned_distribution_digests_by_filename(
        node, expected_filenames_by_artifact_id
    )
    if set(expected_digests_by_filename) != set(
        expected_filenames_by_artifact_id.values()
    ):
        return "partial"
    if not isinstance(dist, Mapping):
        return "partial"
    observed_digests = _npm_dist_digests(dist)
    if not observed_digests:
        return "partial"
    if any(len(digests) > 1 for digests in observed_digests.values()):
        return "conflicting"
    observed_single_digests = _single_npm_dist_digests(observed_digests)
    for expected_digests in expected_digests_by_filename.values():
        shared_algorithms = set(expected_digests) & set(observed_single_digests)
        if not shared_algorithms:
            return "partial"
        if any(
            observed_single_digests[algorithm] != expected_digests[algorithm]
            for algorithm in shared_algorithms
        ):
            return "conflicting"
    return "exact-satisfied"


def _npm_version_tarball_filename(
    version_payload: Mapping[str, Any], node: Json
) -> str | None:
    dist = version_payload.get("dist")
    if not isinstance(dist, Mapping):
        return None
    tarball = dist.get("tarball")
    if not isinstance(tarball, str) or not tarball:
        return None
    path = urllib.parse.urlparse(tarball).path
    filename = urllib.parse.unquote(PurePosixPath(path).name)
    package_name, version = _package_publish_identity(node, "npm")
    filename = _normalize_npm_registry_tarball_filename(
        filename, package_name, version
    )
    return filename or None


def _normalize_npm_registry_tarball_filename(
    filename: str, package_name: str, version: str
) -> str:
    if not package_name.startswith("@"):
        return filename
    scope_and_name = package_name[1:]
    scope, separator, unscoped_name = scope_and_name.partition("/")
    if not separator or not scope or not unscoped_name:
        return filename
    if filename == f"{unscoped_name}-{version}.tgz":
        return f"{scope}-{unscoped_name}-{version}.tgz"
    return filename


def _npm_dist_has_digest_evidence(dist: Mapping[str, Any]) -> bool:
    if _npm_dist_digests(dist):
        return True
    shasum = dist.get("shasum")
    return (
        isinstance(shasum, str)
        and re.fullmatch(r"[0-9a-f]{40}", shasum) is not None
    )


def _npm_integrity_has_digest_evidence(value: object) -> bool:
    return bool(_digest_values_from_sri(value))


def _npm_dist_sha256(dist: Mapping[str, Any]) -> str | None:
    digests = _npm_dist_digests(dist).get("sha256")
    if digests is None or len(digests) != 1:
        return None
    return next(iter(digests))


def _planned_distribution_digests_by_filename(
    node: Json, filenames_by_artifact_id: Mapping[str, str]
) -> dict[str, dict[str, str]]:
    expected: dict[str, dict[str, str]] = {}
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        return expected
    raw_by_artifact_id = projection.get(
        "final-distribution-digests-by-artifact-id"
    )
    if not isinstance(raw_by_artifact_id, Mapping):
        return expected
    for artifact_id, raw_digests in raw_by_artifact_id.items():
        if not isinstance(artifact_id, str):
            continue
        filename = filenames_by_artifact_id.get(artifact_id)
        if filename is None:
            continue
        digests = _normalize_digest_map(raw_digests)
        if digests:
            expected.setdefault(filename, {}).update(digests)
    return expected


def _normalize_digest_map(value: object) -> dict[str, str]:
    if not isinstance(value, Mapping):
        return {}
    result: dict[str, str] = {}
    for algorithm, digest in value.items():
        if not isinstance(algorithm, str):
            continue
        normalized = _normalize_algorithm_digest(algorithm, digest)
        if normalized is not None:
            result[algorithm] = normalized
    return result


def _normalize_algorithm_digest(algorithm: str, value: object) -> str | None:
    if not isinstance(value, str):
        return None
    lengths = {"sha256": 64, "sha384": 96, "sha512": 128}
    length = lengths.get(algorithm)
    if length is None:
        return None
    if re.fullmatch(rf"[0-9a-f]{{{length}}}", value) is None:
        return None
    return value


def _npm_dist_digests(dist: Mapping[str, Any]) -> dict[str, set[str]]:
    result: dict[str, set[str]] = {}
    for key, algorithm in (
        ("sha256", "sha256"),
        ("sha256_digest", "sha256"),
        ("sha384", "sha384"),
        ("sha384_digest", "sha384"),
        ("sha512", "sha512"),
        ("sha512_digest", "sha512"),
    ):
        digest = _normalize_algorithm_digest(algorithm, dist.get(key))
        if digest is not None:
            result.setdefault(algorithm, set()).add(digest)
    for algorithm, digests in _digest_values_from_sri(
        dist.get("integrity")
    ).items():
        result.setdefault(algorithm, set()).update(digests)
    return result


def _single_npm_dist_digests(digests: Mapping[str, set[str]]) -> dict[str, str]:
    return {
        algorithm: next(iter(values))
        for algorithm, values in digests.items()
        if len(values) == 1
    }


def _npm_dist_has_conflicting_digest_evidence(dist: Mapping[str, Any]) -> bool:
    return any(len(digests) > 1 for digests in _npm_dist_digests(dist).values())


def _digests_from_sri(value: object) -> dict[str, str]:
    return {
        algorithm: next(iter(digests))
        for algorithm, digests in _digest_values_from_sri(value).items()
        if len(digests) == 1
    }


def _digest_values_from_sri(value: object) -> dict[str, set[str]]:
    result: dict[str, set[str]] = {}
    if not isinstance(value, str):
        return result
    lengths = {"sha256": 32, "sha384": 48, "sha512": 64}
    for token in value.split():
        algorithm, separator, encoded = token.partition("-")
        expected_length = lengths.get(algorithm)
        if expected_length is None or not separator or not encoded:
            continue
        encoded = encoded.partition("?")[0]
        try:
            raw = base64.b64decode(encoded, validate=True)
        except (binascii.Error, ValueError):
            continue
        if len(raw) == expected_length:
            result.setdefault(algorithm, set()).add(raw.hex())
    return result


def _observe_rubygems_publication(node: Json) -> str:
    package_name, version = _package_publish_identity(node, "RubyGems")
    payload = _rubygems_versions_json(package_name)
    if payload is None:
        return "absent"
    if not isinstance(payload, list):
        msg = (
            f"RubyGems versions API payload for {package_name!r} is not a list"
        )
        raise TypeError(msg)
    for item in payload:
        if not isinstance(item, Mapping):
            msg = (
                f"RubyGems versions API payload for {package_name!r} "
                "contains a malformed version item"
            )
            raise TypeError(msg)
        number = item.get("number")
        if not isinstance(number, str) or not number:
            msg = (
                f"RubyGems versions API payload for {package_name!r} "
                "contains a version item without number"
            )
            raise TypeError(msg)
        if number == version:
            return _classify_rubygems_version_payload(
                node, payload, package_name, version
            )
    return "absent"


def _classify_rubygems_version_payload(
    node: Json,
    payload: Sequence[object],
    package_name: str,
    version: str,
) -> str:
    expected_filenames_by_artifact_id = _planned_distribution_filenames(
        node, "RubyGems"
    )
    if len(set(expected_filenames_by_artifact_id.values())) != len(
        expected_filenames_by_artifact_id
    ):
        return "conflicting"
    expected_filenames = set(expected_filenames_by_artifact_id.values())
    observed_files = _rubygems_version_files(payload, package_name, version)
    if observed_files is None:
        return "partial"
    filename_classification = _classify_distribution_filename_sets(
        expected_filenames, set(observed_files)
    )
    if filename_classification is not None:
        return filename_classification
    return _classify_rubygems_digest_evidence(
        node,
        expected_filenames_by_artifact_id,
        expected_filenames,
        observed_files,
    )


def _classify_rubygems_digest_evidence(
    node: Json,
    expected_filenames_by_artifact_id: Mapping[str, str],
    expected_filenames: set[str],
    observed_files: Mapping[str, str | None],
) -> str:
    expected_sha256_by_filename = _planned_distribution_sha256_by_filename(
        node, expected_filenames_by_artifact_id
    )
    if set(expected_sha256_by_filename) != expected_filenames:
        return "partial"
    for filename, expected_sha256 in expected_sha256_by_filename.items():
        observed_sha256 = observed_files[filename]
        if observed_sha256 is None:
            return "partial"
        if observed_sha256 != expected_sha256:
            return "conflicting"
    if any(observed_files[filename] is None for filename in expected_filenames):
        return "partial"
    return "exact-satisfied"


def _rubygems_version_files(
    payload: Sequence[object],
    package_name: str,
    version: str,
) -> dict[str, str | None] | None:
    observed: dict[str, str | None] = {}
    for item in payload:
        if not isinstance(item, Mapping):
            msg = (
                f"RubyGems versions API payload for {package_name!r} "
                "contains a malformed version item"
            )
            raise TypeError(msg)
        number = item.get("number")
        if number != version:
            continue
        platform = item.get("platform")
        if not isinstance(platform, str) or not platform:
            return None
        filename = _rubygems_filename_for_platform(
            package_name, version, platform
        )
        if filename in observed:
            return None
        observed[filename] = _normalize_sha256_digest(item.get("sha"))
    return observed


def _rubygems_filename_for_platform(
    package_name: str, version: str, platform: str
) -> str:
    if platform == "ruby":
        return f"{package_name}-{version}.gem"
    return f"{package_name}-{version}-{platform}.gem"


def _observe_public_registry_publication(
    node: Json, snapshot: Mapping[str, Any]
) -> str:
    family = snapshot.get("family")
    if family == "pypi":
        return _observe_pypi_publication(node)
    if family == "nuget":
        return _observe_nuget_publication(node)
    if family == "npm":
        return _observe_npm_publication(node)
    if family == "rubygems":
        return _observe_rubygems_publication(node)
    msg = f"unsupported public registry family for observation: {family!r}"
    raise RuntimeError(msg)


def _package_publish_identity(
    node: Json, registry_name: str
) -> tuple[str, str]:
    identity = node.get("resolved-publish-identity")
    if not isinstance(identity, Mapping):
        msg = (
            f"{registry_name} publish node is missing resolved-publish-identity"
        )
        raise TypeError(msg)
    package_name = identity.get("package-name")
    version = identity.get("version")
    if not isinstance(package_name, str) or not package_name:
        msg = f"{registry_name} publish identity is missing package-name"
        raise TypeError(msg)
    if not isinstance(version, str) or not version:
        msg = f"{registry_name} publish identity is missing version"
        raise TypeError(msg)
    return package_name, version


def _github_packages_owner(repository: str, snapshot: Mapping[str, Any]) -> str:
    destination = snapshot.get("destination")
    owner = (
        destination.get("owner") if isinstance(destination, Mapping) else None
    )
    if isinstance(owner, str) and owner:
        return owner
    repo_owner, _, _ = repository.partition("/")
    if repo_owner:
        return repo_owner
    msg = "GitHub Packages NuGet target is missing destination owner"
    raise TypeError(msg)


def _github_packages_owner_endpoint_prefix(repository: str, owner: str) -> str:
    repo_owner, separator, repo_name = repository.partition("/")
    if separator and owner == repo_owner:
        payload = _gh_api(
            repository,
            f"repos/{urllib.parse.quote(repo_owner, safe='')}/"
            f"{urllib.parse.quote(repo_name, safe='')}",
        )
        owner_payload = (
            payload.get("owner") if isinstance(payload, Mapping) else None
        )
        owner_type = (
            owner_payload.get("type")
            if isinstance(owner_payload, Mapping)
            else None
        )
    else:
        payload = _gh_api(
            repository, f"users/{urllib.parse.quote(owner, safe='')}"
        )
        owner_type = (
            payload.get("type") if isinstance(payload, Mapping) else None
        )
    if owner_type == "Organization":
        return f"orgs/{urllib.parse.quote(owner, safe='')}"
    if owner_type == "User":
        return f"users/{urllib.parse.quote(owner, safe='')}"
    msg = (
        f"GitHub Packages owner {owner!r} has unsupported or missing "
        f"GitHub owner type {owner_type!r}"
    )
    raise TypeError(msg)


def _github_packages_nuget_package(
    repository: str,
    owner: str,
    package_name: str,
) -> Mapping[str, Any] | None:
    return _github_packages_package(
        repository,
        owner,
        "nuget",
        package_name,
    )


def _github_packages_package(
    repository: str,
    owner: str,
    package_type: str,
    package_name: str,
) -> Mapping[str, Any] | None:
    prefix = _github_packages_owner_endpoint_prefix(repository, owner)
    endpoint = (
        f"{prefix}/packages/{urllib.parse.quote(package_type, safe='')}/"
        f"{urllib.parse.quote(package_name, safe='')}"
    )
    try:
        payload = _gh_api(repository, endpoint)
    except RuntimeError as exc:
        if _is_github_not_found_error(exc):
            sys.stderr.write(
                "GitHub Packages 404 treated as absent; publish remains the "
                "authority for permissions and conflicts: "
                f"package-name={package_name!r}, owner={owner!r}, "
                f"package-type={package_type!r}\n"
            )
            return None
        raise
    if not isinstance(payload, Mapping):
        msg = (
            "GitHub Packages package API returned a malformed package "
            f"payload for {package_name!r}"
        )
        raise TypeError(msg)
    remote_name = payload.get("name")
    if not isinstance(remote_name, str) or not remote_name:
        msg = (
            "GitHub Packages package API returned a package payload without "
            f"name for {package_name!r}"
        )
        raise TypeError(msg)
    return payload


def _github_packages_nuget_versions(
    repository: str, owner: str, package_name: str
) -> list[Any]:
    prefix = _github_packages_owner_endpoint_prefix(repository, owner)
    endpoint = (
        f"{prefix}/packages/nuget/"
        f"{urllib.parse.quote(package_name, safe='')}/versions?per_page=100"
    )
    return _gh_api_paginated(repository, endpoint)


def _github_packages_versions(
    repository: str, owner: str, package_type: str, package_name: str
) -> list[Any]:
    prefix = _github_packages_owner_endpoint_prefix(repository, owner)
    endpoint = (
        f"{prefix}/packages/{urllib.parse.quote(package_type, safe='')}/"
        f"{urllib.parse.quote(package_name, safe='')}/versions?per_page=100"
    )
    return _gh_api_paginated(repository, endpoint)


def _pypi_project_json(package_name: str) -> Json | None:
    normalized = _pep503_name(package_name)
    url = (
        f"https://pypi.org/pypi/{urllib.parse.quote(normalized, safe='')}/json"
    )
    payload = _registry_json_request(
        url,
        api_name="PyPI JSON API",
        subject=f"package {normalized!r}",
    )
    if payload is None:
        return None
    if not isinstance(payload, dict):
        msg = f"PyPI JSON API returned non-object payload for {normalized!r}"
        raise TypeError(msg)
    return payload


def _nuget_versions_json(package_name: str) -> Json | None:
    normalized = package_name.lower()
    url = (
        "https://api.nuget.org/v3-flatcontainer/"
        f"{urllib.parse.quote(normalized, safe='')}/index.json"
    )
    payload = _registry_json_request(
        url,
        api_name="NuGet flat-container API",
        subject=f"package {normalized!r}",
    )
    if payload is None:
        return None
    if not isinstance(payload, dict):
        msg = (
            f"NuGet flat-container API returned non-object payload for "
            f"{normalized!r}"
        )
        raise TypeError(msg)
    return payload


def _npm_package_json(package_name: str) -> Json | None:
    url = (
        "https://registry.npmjs.org/"
        f"{urllib.parse.quote(package_name, safe='')}"
    )
    payload = _registry_json_request(
        url,
        api_name="npm registry API",
        subject=f"package {package_name!r}",
    )
    if payload is None:
        return None
    if not isinstance(payload, dict):
        msg = (
            f"npm registry API returned non-object payload for {package_name!r}"
        )
        raise TypeError(msg)
    return payload


def _rubygems_versions_json(package_name: str) -> list[Any] | None:
    url = (
        "https://rubygems.org/api/v1/versions/"
        f"{urllib.parse.quote(package_name, safe='')}.json"
    )
    payload = _registry_json_request(
        url,
        api_name="RubyGems versions API",
        subject=f"gem {package_name!r}",
    )
    if payload is None:
        return None
    if not isinstance(payload, list):
        msg = f"RubyGems versions API returned non-list payload for {package_name!r}"
        raise TypeError(msg)
    return payload


def _registry_json_request(
    url: str,
    *,
    api_name: str,
    subject: str,
) -> object | None:
    request = urllib.request.Request(  # noqa: S310
        url,
        headers={
            "Accept": "application/json",
            "User-Agent": "three-workflow-release-control/1.0",
        },
    )
    try:
        with urllib.request.urlopen(  # noqa: S310
            request, timeout=_REGISTRY_JSON_TIMEOUT_SECONDS
        ) as response:
            status = response.getcode()
            if status != 200:
                msg = f"{api_name} request failed for {subject}: HTTP {status}"
                raise RuntimeError(msg)
            raw = response.read()
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            return None
        msg = f"{api_name} request failed for {subject}: HTTP {exc.code}"
        raise RuntimeError(msg) from exc
    except urllib.error.URLError as exc:
        msg = f"{api_name} request failed for {subject}: {exc.reason}"
        raise RuntimeError(msg) from exc
    except http.client.HTTPException as exc:
        msg = f"{api_name} request failed for {subject}: {exc}"
        raise RuntimeError(msg) from exc
    except OSError as exc:
        msg = f"{api_name} request failed for {subject}: {exc}"
        raise RuntimeError(msg) from exc
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        msg = f"{api_name} returned invalid JSON for {subject}: {exc}"
        raise RuntimeError(msg) from exc
    return payload


def _supports_remote_observation(snapshot: Mapping[str, Any]) -> bool:
    return snapshot.get("family") == "github-release" or (
        _supports_public_registry_remote_observation(snapshot)
        or _supports_github_packages_remote_observation(snapshot)
    )


def _supports_github_packages_remote_observation(
    snapshot: Mapping[str, Any],
) -> bool:
    destination = snapshot.get("destination")
    github_hosts = {
        "nuget": "nuget.pkg.github.com",
        "npm": "npm.pkg.github.com",
        "rubygems": "rubygems.pkg.github.com",
    }
    family = snapshot.get("family")
    return (
        isinstance(family, str)
        and isinstance(destination, Mapping)
        and destination.get("host") == github_hosts.get(family)
    )


def _supports_public_registry_remote_observation(
    snapshot: Mapping[str, Any],
) -> bool:
    destination = snapshot.get("destination")
    if not isinstance(destination, Mapping):
        return False
    family = snapshot.get("family")
    host = destination.get("host")
    return (
        (family == "pypi" and host == "pypi.org")
        or (family == "nuget" and host == "nuget.org")
        or (family == "npm" and host == "registry.npmjs.org")
        or (family == "rubygems" and host == "rubygems.org")
    )


def _supports_pypi_remote_observation(snapshot: Mapping[str, Any]) -> bool:
    destination = snapshot.get("destination")
    return (
        snapshot.get("family") == "pypi"
        and isinstance(destination, Mapping)
        and destination.get("host") == "pypi.org"
    )


def _requires_live_external_remote_observation(
    node_id: str,
    node: Mapping[str, Any],
    snapshot_id: str,
    snapshot: Mapping[str, Any],
    execution_sets: Mapping[str, Any] | None,
    enabled: set[str],
) -> bool:
    if execution_sets is None:
        return True
    candidates_key = (
        "publish-intent-node-ids"
        if execution_sets.get("dry-run")
        else "active-publish-node-ids"
    )
    candidates = execution_sets.get(candidates_key, [])
    required = node_id in candidates
    capabilities = snapshot.get("capabilities")
    if (
        required
        and isinstance(capabilities, Mapping)
        and capabilities.get("credential-posture") == "oidc"
    ):
        identity = node.get("resolved-publish-identity")
        package_name = (
            identity.get("package-name")
            if isinstance(identity, Mapping)
            else None
        )
        if isinstance(package_name, str) and package_name:
            token = f"{snapshot_id}#{node.get('project-id')}#{package_name}"
            required = token in enabled
    return required


def _requires_live_github_token_remote_observation(
    node_id: str,
    execution_sets: Mapping[str, Any] | None,
) -> bool:
    if execution_sets is None:
        return True
    return node_id in _remote_observation_publish_candidate_ids(execution_sets)


def _remote_observation_publish_candidate_ids(
    execution_sets: Mapping[str, Any],
) -> Sequence[Any]:
    candidates_key = (
        "publish-intent-node-ids"
        if execution_sets.get("dry-run")
        else "active-publish-node-ids"
    )
    candidates = execution_sets.get(candidates_key, [])
    if isinstance(candidates, str):
        return []
    return candidates if isinstance(candidates, Sequence) else []


def _pep503_name(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


def _nuget_version_key(version: str) -> str:
    if version != version.strip():
        msg = f"NuGet version has surrounding whitespace: {version!r}"
        raise ValueError(msg)
    public_version, metadata_separator, metadata = version.partition("+")
    if metadata_separator:
        _validate_nuget_identifiers(
            metadata,
            _NUGET_BUILD_METADATA_PART_RE,
            "build metadata",
            version,
        )
    release, prerelease_separator, prerelease = public_version.partition("-")
    release_parts = release.split(".")
    if not 1 <= len(release_parts) <= _NUGET_MAX_NUMERIC_PARTS or not all(
        _NUGET_VERSION_PART_RE.fullmatch(part) for part in release_parts
    ):
        msg = (
            f"NuGet version has invalid numeric release components: {version!r}"
        )
        raise ValueError(msg)
    normalized_numbers = [str(int(part)) for part in release_parts]
    while len(normalized_numbers) < _NUGET_IDENTITY_NUMERIC_PARTS:
        normalized_numbers.append("0")
    if (
        len(normalized_numbers) == _NUGET_MAX_NUMERIC_PARTS
        and normalized_numbers[3] == "0"
    ):
        normalized_numbers.pop()
    normalized = ".".join(normalized_numbers)
    if not prerelease_separator:
        return normalized
    prerelease_parts = _validate_nuget_identifiers(
        prerelease,
        _NUGET_PRERELEASE_PART_RE,
        "prerelease",
        version,
    )
    return f"{normalized}-{'.'.join(part.lower() for part in prerelease_parts)}"


def _validate_nuget_identifiers(
    value: str,
    pattern: re.Pattern[str],
    label: str,
    version: str,
) -> list[str]:
    parts = value.split(".")
    if not value or not all(pattern.fullmatch(part) for part in parts):
        msg = f"NuGet version has invalid {label} identifiers: {version!r}"
        raise ValueError(msg)
    return parts


def _classify_github_release_payload(  # noqa: C901, PLR0911, PLR0912
    release: Json,
    node_id: str,
    node: Json,
    repository: str,
    commit_sha: str,
    tag: str,
    *,
    plan_id: str | None = None,
    artifact_variant_ids_by_id: Mapping[str, object] | None = None,
    release_group_nodes: Mapping[str, Json] | None = None,
    release_group_variant_ids: Mapping[str, Mapping[str, object]] | None = None,
) -> str:
    if release.get("draft") is True:
        return "conflicting"
    desired = node.get("desired-publish-state", {})
    desired_prerelease = (
        isinstance(desired, Mapping)
        and desired.get("release-state") == "prerelease"
    )
    desired_release = (
        isinstance(desired, Mapping)
        and desired.get("release-state") == "release"
    )
    actual_prerelease = release.get("prerelease")
    if actual_prerelease is None:
        actual_prerelease = release.get("isPrerelease")
    if not isinstance(actual_prerelease, bool):
        return "conflicting"
    planned_assets = _planned_github_release_assets(node)
    release_nodes = _github_release_observation_nodes_for_payload(
        node_id,
        node,
        release_group_nodes,
    )
    release_planned_assets = _planned_github_release_asset_union(
        release_nodes.values(),
    )
    valid_sidecar_assets = _valid_github_release_asset_proof_sidecar_names(
        release,
        node_id,
        node,
        tag,
        repository=repository,
        release_target_sha=commit_sha,
        artifact_variant_ids_by_id=artifact_variant_ids_by_id,
    )
    valid_sidecar_assets.update(
        _valid_github_release_group_asset_proof_sidecar_names(
            release,
            release_nodes,
            tag,
            repository=repository,
            release_target_sha=commit_sha,
            release_group_variant_ids=release_group_variant_ids,
        ),
    )
    actual_assets = _observed_github_release_assets(
        release,
        valid_sidecar_assets,
    )
    if (
        planned_assets is None
        or release_planned_assets is None
        or actual_assets is None
    ):
        return "conflicting"
    release_assets_match = actual_assets == release_planned_assets
    release_assets_are_planned = actual_assets <= release_planned_assets
    node_assets_present = planned_assets <= actual_assets
    if actual_prerelease is False and (
        not release_assets_match or actual_prerelease != desired_prerelease
    ):
        return "conflicting"
    if not node_assets_present or not release_assets_are_planned:
        if actual_prerelease is True and desired_release:
            return "partial-authoritative"
        return "partial"
    if not _github_release_asset_labels_match(
        node,
        release,
        valid_sidecar_assets,
    ):
        if actual_prerelease is False:
            return "conflicting"
        if desired_release:
            return "partial-authoritative"
        return "partial"
    if not _github_release_asset_attestation_evidence_matches(
        release=release,
        node_id=node_id,
        node=node,
        repository=repository,
        commit_sha=commit_sha,
        tag=tag,
        plan_id=plan_id,
        valid_sidecar_assets=valid_sidecar_assets,
    ):
        if actual_prerelease is True and not desired_prerelease:
            return "partial-authoritative"
        if actual_prerelease is False:
            return "conflicting"
        return "partial"
    if actual_prerelease == desired_prerelease:
        return "exact-satisfied"
    if actual_prerelease is True and not desired_prerelease:
        return "partial-authoritative"
    return "partial"


def _planned_github_release_assets(node: Json) -> set[str] | None:
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        return None
    planned_assets_by_id = projection.get("asset-names-by-artifact-id")
    if not isinstance(planned_assets_by_id, Mapping):
        return None
    return {str(value) for value in planned_assets_by_id.values()}


def _github_release_observation_nodes_for_payload(
    node_id: str,
    node: Json,
    release_group_nodes: Mapping[str, Json] | None,
) -> dict[str, Json]:
    if release_group_nodes is None:
        return {node_id: node}
    result = dict(release_group_nodes)
    result.setdefault(node_id, node)
    return result


def _planned_github_release_asset_union(
    nodes: Iterable[Json],
) -> set[str] | None:
    release_assets: set[str] = set()
    for node in nodes:
        planned_assets = _planned_github_release_assets(node)
        if planned_assets is None:
            return None
        release_assets.update(planned_assets)
    return release_assets


def _planned_artifact_variant_ids_for_node(
    plan: Mapping[str, object],
    node: Mapping[str, object],
) -> dict[str, str]:
    graph = plan.get("graph")
    if not isinstance(graph, Mapping):
        return {}
    artifacts = graph.get("artifacts")
    if not isinstance(artifacts, Mapping):
        return {}
    artifact_ids = node.get("artifact-ids")
    if not isinstance(artifact_ids, Sequence) or isinstance(
        artifact_ids,
        str | bytes,
    ):
        return {}
    variants: dict[str, str] = {}
    for raw_artifact_id in artifact_ids:
        if not isinstance(raw_artifact_id, str):
            continue
        artifact = artifacts.get(raw_artifact_id)
        if not isinstance(artifact, Mapping):
            continue
        variant_id = artifact.get("variant-id")
        if isinstance(variant_id, str):
            variants[raw_artifact_id] = variant_id
    return variants


def _observed_github_release_assets(
    release: Json,
    valid_sidecar_assets: Collection[str],
) -> set[str] | None:
    assets = release.get("assets")
    if not isinstance(assets, list):
        return None
    actual_assets: set[str] = set()
    for asset in assets:
        if not isinstance(asset, Mapping) or not isinstance(
            asset.get("name"), str
        ):
            return None
        name = str(asset["name"])
        if name in valid_sidecar_assets:
            continue
        actual_assets.add(name)
    return actual_assets


def _github_release_asset_labels_match(  # noqa: C901, PLR0911, PLR0912
    node: Json,
    release: Json,
    valid_sidecar_assets: Collection[str],
) -> bool:
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        return False
    planned_labels_by_id = projection.get("asset-labels-by-artifact-id")
    names_by_id = projection.get("asset-names-by-artifact-id")
    if not isinstance(names_by_id, Mapping):
        return False
    if not isinstance(planned_labels_by_id, Mapping):
        return False
    expected: dict[str, str | None] = {}
    for artifact_id, raw_name in names_by_id.items():
        if not isinstance(artifact_id, str) or not isinstance(raw_name, str):
            return False
        raw_label = planned_labels_by_id.get(artifact_id)
        if raw_label is None:
            expected[raw_name] = None
        elif isinstance(raw_label, str):
            expected[raw_name] = raw_label if raw_label else None
        else:
            return False
    observed: dict[str, str | None] = {}
    assets = release.get("assets")
    if not isinstance(assets, list):
        return False
    expected_names = set(expected)
    for asset in assets:
        if not isinstance(asset, Mapping):
            return False
        name = asset.get("name")
        if isinstance(name, str) and name in valid_sidecar_assets:
            continue
        if isinstance(name, str) and name in expected_names:
            label = asset.get("label")
            observed[name] = label if isinstance(label, str) and label else None
    return observed == expected


def _github_release_asset_attestation_evidence_matches(  # noqa: C901, PLR0911, PLR0912
    *,
    release: Json,
    node_id: str,
    node: Json,
    repository: str,
    commit_sha: str,
    tag: str,
    plan_id: str | None = None,
    valid_sidecar_assets: Collection[str] = frozenset(),
) -> bool:
    signer_workflow = _planned_github_release_signer_workflow(node)
    if signer_workflow is None:
        return False
    assets = release.get("assets")
    if not isinstance(assets, list):
        return False
    planned_assets = _planned_github_release_assets(node)
    if planned_assets is None:
        return False
    observed_assets: dict[str, Mapping[str, object]] = {}
    for asset in assets:
        if not isinstance(asset, Mapping):
            return False
        name = asset.get("name")
        size = asset.get("size")
        digest = asset.get("digest")
        if not isinstance(name, str) or not isinstance(size, int):
            return False
        if name in valid_sidecar_assets:
            continue
        if name not in planned_assets:
            continue
        if not isinstance(digest, str) or not digest.startswith("sha256:"):
            return False
        sha256 = digest.removeprefix("sha256:")
        if re.fullmatch(r"[0-9a-f]{64}", sha256) is None:
            return False
        observed_assets[name] = asset
    if set(observed_assets) != planned_assets:
        return False
    wrapper_proofs = _github_release_asset_proofs_from_release(release)
    for name, asset in observed_assets.items():
        expected_size = cast("int", asset["size"])
        expected_sha256 = cast("str", asset["digest"]).removeprefix("sha256:")
        source_digest = _github_release_asset_wrapper_proofs_source_digest(
            proofs=wrapper_proofs.get(name, []),
            name=name,
            expected_size=expected_size,
            expected_sha256=expected_sha256,
            node_id=node_id,
            node=node,
            repository=repository,
            commit_sha=commit_sha,
            tag=tag,
            signer_workflow=signer_workflow,
            plan_id=plan_id,
        )
        if source_digest is None:
            return False
        if not _download_and_verify_github_release_asset_attestation(
            repository=repository,
            tag=tag,
            asset_name=name,
            expected_size=expected_size,
            expected_sha256=expected_sha256,
            signer_workflow=signer_workflow,
            commit_sha=source_digest,
        ):
            return False
    return True


def _planned_github_release_signer_workflow(
    node: Mapping[str, Any],
) -> str | None:
    attestation = node.get("attestation")
    if not isinstance(attestation, Mapping):
        return None
    signer_workflow = attestation.get("signer-workflow")
    return (
        signer_workflow
        if isinstance(signer_workflow, str) and signer_workflow
        else None
    )


def _planned_github_release_repository(
    plan: Json,
    node: Mapping[str, Any],
) -> str | None:
    snapshot_id = node.get("target-instance-snapshot-id")
    graph = plan.get("graph")
    snapshots = (
        graph.get("target-instance-snapshots")
        if isinstance(graph, Mapping)
        else None
    )
    snapshot = (
        snapshots.get(snapshot_id) if isinstance(snapshots, Mapping) else None
    )
    if not isinstance(snapshot, Mapping):
        return None
    if snapshot.get("family") != "github-release":
        return None
    destination = snapshot.get("destination")
    if not isinstance(destination, Mapping):
        return None
    owner = destination.get("owner")
    repo = destination.get("repo")
    if not isinstance(owner, str) or not owner:
        return None
    if not isinstance(repo, str) or not repo:
        return None
    return f"{owner}/{repo}"


def _download_and_verify_github_release_asset_attestation(
    *,
    repository: str,
    tag: str,
    asset_name: str,
    expected_size: int,
    expected_sha256: str,
    signer_workflow: str,
    commit_sha: str,
) -> bool:
    with tempfile.TemporaryDirectory(
        prefix="three-gh-release-asset-"
    ) as temp_dir:
        destination = Path(temp_dir) / asset_name
        if not _gh_release_download_asset(
            repository=repository,
            tag=tag,
            asset_name=asset_name,
            destination_dir=Path(temp_dir),
        ):
            return False
        if not destination.is_file():
            return False
        if destination.stat().st_size != expected_size:
            return False
        if _file_sha256_bytes(destination) != expected_sha256:
            return False
        return _gh_attestation_verify_asset(
            repository=repository,
            asset_path=destination,
            asset_name=asset_name,
            expected_sha256=expected_sha256,
            signer_workflow=signer_workflow,
            commit_sha=commit_sha,
        )


def _file_sha256_bytes(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _gh_release_download_asset(
    *,
    repository: str,
    tag: str,
    asset_name: str,
    destination_dir: Path,
) -> bool:
    env = os.environ.copy()
    if "GH_TOKEN" not in env and "GITHUB_TOKEN" in env:
        env["GH_TOKEN"] = env["GITHUB_TOKEN"]
    result = subprocess.run(
        [
            "gh",
            "release",
            "download",
            tag,
            "--repo",
            repository,
            "--pattern",
            asset_name,
            "--dir",
            str(destination_dir),
            "--clobber",
        ],
        cwd=Path.cwd(),
        env=env,
        capture_output=True,
        text=True,
        check=False,
    )
    return result.returncode == 0


def _gh_attestation_verify_asset(
    *,
    repository: str,
    asset_path: Path,
    asset_name: str,
    expected_sha256: str,
    signer_workflow: str,
    commit_sha: str,
) -> bool:
    return (
        _gh_attestation_verify_asset_evidence(
            repository=repository,
            asset_path=asset_path,
            asset_name=asset_name,
            expected_sha256=expected_sha256,
            signer_workflow=signer_workflow,
            commit_sha=commit_sha,
        )
        is not None
    )


def _gh_attestation_verify_asset_evidence(
    *,
    repository: str,
    asset_path: Path,
    asset_name: str,
    expected_sha256: str,
    signer_workflow: str,
    commit_sha: str,
) -> Json | None:
    env = os.environ.copy()
    if "GH_TOKEN" not in env and "GITHUB_TOKEN" in env:
        env["GH_TOKEN"] = env["GITHUB_TOKEN"]
    result = subprocess.run(
        [
            "gh",
            "attestation",
            "verify",
            str(asset_path),
            "--repo",
            repository,
            "--signer-workflow",
            signer_workflow,
            "--source-digest",
            commit_sha,
            "--predicate-type",
            _GITHUB_ATTESTATION_PREDICATE,
            "--format",
            "json",
        ],
        cwd=Path.cwd(),
        env=env,
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        return None
    try:
        payload = json.loads(result.stdout) if result.stdout.strip() else {}
    except json.JSONDecodeError:
        return None
    if not _attestation_payload_has_subject(
        payload,
        asset_name=asset_name,
        expected_sha256=expected_sha256,
    ):
        return None
    return {
        "predicate-type": _GITHUB_ATTESTATION_PREDICATE,
        "subject-name": asset_name,
        "subject-digest": f"sha256:{expected_sha256}",
        "signer-workflow": signer_workflow,
        "source-repository": repository,
        "source-digest": commit_sha,
        "attestation-id": _attestation_payload_id(payload)
        or f"{repository}:{asset_name}:{expected_sha256}",
        "attestation-url": _attestation_payload_url(payload)
        or (
            f"https://github.com/{repository}/attestations"
            f"?subject-digest=sha256:{expected_sha256}"
        ),
        "sha256": expected_sha256,
        "asset-name": asset_name,
    }


def _attestation_payload_id(payload: object) -> str | None:
    value = _first_string_at_keys(
        payload,
        (
            "attestationId",
            "attestation-id",
            "id",
            "logIndex",
        ),
    )
    return value if value else None


def _attestation_payload_url(payload: object) -> str | None:
    value = _first_string_at_keys(
        payload,
        (
            "attestationUrl",
            "attestation-url",
            "url",
        ),
    )
    return value if value else None


def _first_string_at_keys(value: object, keys: Collection[str]) -> str | None:
    if isinstance(value, Mapping):
        for key, item in value.items():
            if key in keys and isinstance(item, str) and item:
                return item
            nested = _first_string_at_keys(item, keys)
            if nested is not None:
                return nested
    elif isinstance(value, Sequence) and not isinstance(value, str | bytes):
        for item in value:
            nested = _first_string_at_keys(item, keys)
            if nested is not None:
                return nested
    return None


def _attestation_payload_has_subject(
    payload: object, *, asset_name: str, expected_sha256: str
) -> bool:
    for statement in _attestation_statements(payload):
        predicate_type = statement.get("predicateType") or statement.get(
            "predicate-type"
        )
        if predicate_type != _GITHUB_ATTESTATION_PREDICATE:
            continue
        subjects = statement.get("subject")
        if not isinstance(subjects, Sequence) or isinstance(
            subjects, (str, bytes)
        ):
            continue
        for subject in subjects:
            if not isinstance(subject, Mapping):
                continue
            if subject.get("name") != asset_name:
                continue
            digest = subject.get("digest")
            if not isinstance(digest, Mapping):
                continue
            if digest.get("sha256") == expected_sha256:
                return True
    return False


def _attestation_statements(payload: object) -> Iterable[Mapping[str, object]]:
    if isinstance(payload, Mapping):
        yield from _attestation_entry_statements(payload)
    elif isinstance(payload, list):
        for item in payload:
            if isinstance(item, Mapping):
                yield from _attestation_entry_statements(item)


def _attestation_entry_statements(
    entry: Mapping[str, object],
) -> Iterable[Mapping[str, object]]:
    verification = entry.get("verificationResult")
    if isinstance(verification, Mapping):
        statement = verification.get("statement")
        if isinstance(statement, Mapping):
            yield statement


def _github_release_asset_proofs_from_release(
    release: Json,
) -> dict[str, list[Mapping[str, object]]]:
    raw = release.get("github-release-asset-proofs")
    if raw is None:
        raw = release.get("asset-proofs")
    if not isinstance(raw, list):
        return {}
    proofs: dict[str, list[Mapping[str, object]]] = {}
    for item in raw:
        if not isinstance(item, Mapping):
            return {}
        binding = item.get("binding")
        asset_name = (
            binding.get("asset-name") if isinstance(binding, Mapping) else None
        )
        if isinstance(asset_name, str):
            proofs.setdefault(asset_name, []).append(item)
    return proofs


def _valid_github_release_asset_proof_sidecar_names(
    release: Json,
    node_id: str,
    node: Json,
    tag: str,
    *,
    repository: str | None = None,
    release_target_sha: str | None = None,
    artifact_variant_ids_by_id: Mapping[str, object] | None = None,
) -> set[str]:
    sidecar_names = _github_release_asset_proof_sidecar_asset_names(release)
    if not sidecar_names:
        return set()
    signer_workflow = _planned_github_release_signer_workflow(node)
    valid_names: set[str] = set()
    for entry in _github_release_asset_proof_sidecar_entries(release):
        if entry.get("valid") is not True:
            continue
        name = entry.get("asset-name")
        proof = entry.get("proof")
        if not isinstance(name, str) or name not in sidecar_names:
            continue
        if not isinstance(proof, Mapping):
            continue
        if not _is_valid_github_release_asset_proof_sidecar_file(name, proof):
            continue
        if _github_release_asset_proof_is_release_bound_sidecar(
            proof,
            node_id,
            node,
            tag,
            repository=repository,
            release_target_sha=release_target_sha,
            signer_workflow=signer_workflow,
            artifact_variant_ids_by_id=artifact_variant_ids_by_id,
        ):
            valid_names.add(name)
    return valid_names


def _valid_github_release_group_asset_proof_sidecar_names(
    release: Json,
    release_nodes: Mapping[str, Json],
    tag: str,
    *,
    repository: str | None = None,
    release_target_sha: str | None = None,
    release_group_variant_ids: Mapping[str, Mapping[str, object]] | None = None,
) -> set[str]:
    valid_names: set[str] = set()
    for node_id, node in release_nodes.items():
        variant_ids = (
            release_group_variant_ids.get(node_id)
            if release_group_variant_ids is not None
            else None
        )
        valid_names.update(
            _valid_github_release_asset_proof_sidecar_names(
                release,
                node_id,
                node,
                tag,
                repository=repository,
                release_target_sha=release_target_sha,
                artifact_variant_ids_by_id=variant_ids,
            ),
        )
    return valid_names


def _github_release_asset_proof_sidecar_asset_names(release: Json) -> set[str]:
    assets = release.get("assets")
    if not isinstance(assets, list):
        return set()
    names: set[str] = set()
    for asset in assets:
        if not isinstance(asset, Mapping):
            continue
        name = asset.get("name")
        if isinstance(
            name, str
        ) and _is_github_release_asset_proof_sidecar_name(
            name,
        ):
            names.add(name)
    return names


def _github_release_asset_proof_sidecar_entries(
    release: Json,
) -> list[Mapping[str, object]]:
    entries = release.get("_github-release-asset-proof-sidecars")
    if not isinstance(entries, list):
        return []
    return [entry for entry in entries if isinstance(entry, Mapping)]


def _is_valid_github_release_asset_proof_sidecar_file(
    name: str,
    proof: Mapping[str, object],
) -> bool:
    if not _is_github_release_asset_proof_sidecar_name(name):
        return False
    if not _is_valid_receipt(dict(proof)):
        return False
    try:
        return _github_release_asset_proof_sidecar_filename(proof) == name
    except (TypeError, ValueError):
        return False


def _github_release_asset_proof_sidecar_filename(
    proof: Mapping[str, object],
) -> str:
    binding = _mapping(proof.get("binding"), "binding")
    run = _mapping(proof.get("run"), "run")
    binding_json = github_release_asset_binding_json(
        publish_node_id=_string(
            binding.get("publish-node-id"),
            "binding.publish-node-id",
        ),
        artifact_id=_string(binding.get("artifact-id"), "binding.artifact-id"),
        release_tag=_string(binding.get("release-tag"), "binding.release-tag"),
        asset_name=_string(binding.get("asset-name"), "binding.asset-name"),
    )
    name = artifact_name(
        "github-release-asset-proof",
        ArtifactNameInputs(
            _int(run.get("run-id"), "run.run-id"),
            _int(run.get("run-attempt"), "run.run-attempt"),
            binding_json=binding_json,
        ),
    )
    return f"{name}.json"


def _read_github_release_payload_manifest(
    path: Path,
) -> dict[str, tuple[int, str]]:
    assets: dict[str, tuple[int, str]] = {}
    for line_number, raw_line in enumerate(
        path.read_text(encoding="utf-8").splitlines(),
        start=1,
    ):
        if not raw_line:
            continue
        columns = raw_line.split("\t")
        if len(columns) < 3:
            msg = f"invalid GitHub Release payload manifest row {line_number}"
            raise ValueError(msg)
        name, raw_size, sha256 = columns[:3]
        if not name:
            msg = (
                f"GitHub Release payload manifest row {line_number} has no name"
            )
            raise ValueError(msg)
        try:
            size = int(raw_size)
        except ValueError as exc:
            msg = (
                "GitHub Release payload manifest row "
                f"{line_number} has invalid size"
            )
            raise ValueError(msg) from exc
        if size < 0 or re.fullmatch(r"[0-9a-f]{64}", sha256) is None:
            msg = (
                "GitHub Release payload manifest row "
                f"{line_number} has invalid digest"
            )
            raise ValueError(msg)
        existing = assets.get(name)
        current = (size, sha256)
        if existing is not None and existing != current:
            msg = (
                "GitHub Release payload manifest contains conflicting rows "
                f"for {name!r}"
            )
            raise ValueError(msg)
        assets[name] = current
    return assets


def _github_release_asset_proof_matches_current_sidecar_coverage(  # noqa: PLR0911
    proof: Mapping[str, object],
    *,
    expected_plan_id: str | None,
    expected_run_id: int | None,
    expected_run_attempt: int | None,
    expected_assets_by_name: Mapping[str, tuple[int, str]] | None,
) -> bool:
    if (
        expected_plan_id is not None
        and proof.get("plan-id") != expected_plan_id
    ):
        return False
    run = proof.get("run")
    if expected_run_id is not None or expected_run_attempt is not None:
        if not isinstance(run, Mapping):
            return False
        if expected_run_id is not None and run.get("run-id") != expected_run_id:
            return False
        if (
            expected_run_attempt is not None
            and run.get("run-attempt") != expected_run_attempt
        ):
            return False
    if expected_assets_by_name is None:
        return True
    binding = proof.get("binding")
    artifact = proof.get("artifact")
    if not isinstance(binding, Mapping) or not isinstance(artifact, Mapping):
        return False
    asset_name = binding.get("asset-name")
    if not isinstance(asset_name, str):
        return False
    expected = expected_assets_by_name.get(asset_name)
    if expected is None:
        return False
    expected_size, expected_sha256 = expected
    return (
        artifact.get("byte-size") == expected_size
        and artifact.get("sha256") == expected_sha256
    )


def _github_release_asset_proof_is_release_bound_sidecar(  # noqa: C901, PLR0911
    proof: Mapping[str, object],
    node_id: str,
    node: Mapping[str, Any],
    tag: str,
    *,
    repository: str | None = None,
    release_target_sha: str | None = None,
    signer_workflow: str | None,
    artifact_variant_ids_by_id: Mapping[str, object] | None = None,
) -> bool:
    if (
        proof.get("kind") != "github-release-asset-proof"
        or proof.get("api-version")
        != "three.release.github-release-asset-proof/v1alpha1"
        or proof.get("project-id") != node.get("project-id")
        or signer_workflow is None
    ):
        return False
    binding = proof.get("binding")
    artifact = proof.get("artifact")
    attestation = proof.get("attestation")
    run = proof.get("run")
    if (
        not isinstance(binding, Mapping)
        or not isinstance(artifact, Mapping)
        or not isinstance(attestation, Mapping)
        or not isinstance(run, Mapping)
    ):
        return False
    asset_name = binding.get("asset-name")
    artifact_id = binding.get("artifact-id")
    if not isinstance(asset_name, str) or not isinstance(artifact_id, str):
        return False
    if binding.get("publish-node-id") != node_id:
        return False
    artifact_ids = node.get("artifact-ids")
    if not isinstance(artifact_ids, Sequence) or isinstance(
        artifact_ids,
        str | bytes,
    ):
        return False
    active_artifact_ids = {
        raw_artifact_id
        for raw_artifact_id in artifact_ids
        if isinstance(raw_artifact_id, str)
    }
    if artifact_id not in active_artifact_ids:
        return False
    if artifact_variant_ids_by_id is None:
        return False
    planned_variant_id = artifact_variant_ids_by_id.get(artifact_id)
    if (
        not isinstance(planned_variant_id, str)
        or proof.get("variant-id") != planned_variant_id
    ):
        return False
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        return False
    asset_names_by_artifact_id = projection.get("asset-names-by-artifact-id")
    if not isinstance(asset_names_by_artifact_id, Mapping):
        return False
    if asset_names_by_artifact_id.get(artifact_id) != asset_name:
        return False
    sha256 = artifact.get("sha256")
    source_digest = attestation.get("source-digest")
    proof_release_target_sha = proof.get(
        "release-target-sha", run.get("head-sha")
    )
    matches = (
        binding.get("release-tag") == tag
        and run.get("live") is True
        and run.get("dry-run") is False
        and run.get("validation-only") is False
        and isinstance(source_digest, str)
        and run.get("head-sha") == source_digest
        and (
            release_target_sha is None
            or proof_release_target_sha == release_target_sha
        )
        and attestation.get("subject-name") == asset_name
        and isinstance(sha256, str)
        and attestation.get("subject-digest") == f"sha256:{sha256}"
        and attestation.get("signer-workflow") == signer_workflow
    )
    if not matches:
        return False
    return repository is None or (
        run.get("repository") == repository
        and attestation.get("source-repository") == repository
    )


def _is_github_release_asset_proof_sidecar_name(name: str) -> bool:
    return _GITHUB_RELEASE_ASSET_PROOF_SIDECAR_RE.fullmatch(name) is not None


def _github_release_asset_wrapper_proofs_source_digest(
    *,
    proofs: Sequence[Mapping[str, object]],
    name: str,
    expected_size: int,
    expected_sha256: str,
    node_id: str,
    node: Json,
    repository: str,
    commit_sha: str,
    tag: str,
    signer_workflow: str,
    plan_id: str | None = None,
) -> str | None:
    if not proofs:
        return None
    artifact_ids = _github_release_artifact_ids_by_asset_name(node)
    artifact_id = artifact_ids.get(name)
    if artifact_id is None:
        return None
    for proof in proofs:
        source_digest = _github_release_asset_wrapper_proof_source_digest(
            proof=proof,
            name=name,
            artifact_id=artifact_id,
            expected_size=expected_size,
            expected_sha256=expected_sha256,
            node_id=node_id,
            node=node,
            repository=repository,
            commit_sha=commit_sha,
            tag=tag,
            signer_workflow=signer_workflow,
            plan_id=plan_id,
        )
        if source_digest is not None:
            return source_digest
    return None


def _github_release_asset_wrapper_proof_matches(
    *,
    proof: Mapping[str, object],
    name: str,
    artifact_id: str,
    expected_size: int,
    expected_sha256: str,
    node_id: str,
    node: Json,
    repository: str,
    commit_sha: str,
    tag: str,
    signer_workflow: str,
    plan_id: str | None = None,
) -> bool:
    return (
        _github_release_asset_wrapper_proof_source_digest(
            proof=proof,
            name=name,
            artifact_id=artifact_id,
            expected_size=expected_size,
            expected_sha256=expected_sha256,
            node_id=node_id,
            node=node,
            repository=repository,
            commit_sha=commit_sha,
            tag=tag,
            signer_workflow=signer_workflow,
            plan_id=plan_id,
        )
        is not None
    )


def _github_release_asset_wrapper_proof_source_digest(  # noqa: C901, PLR0911, PLR0912
    *,
    proof: Mapping[str, object],
    name: str,
    artifact_id: str,
    expected_size: int,
    expected_sha256: str,
    node_id: str,
    node: Json,
    repository: str,
    commit_sha: str,
    tag: str,
    signer_workflow: str,
    plan_id: str | None = None,
) -> str | None:
    if (
        proof.get("kind") != "github-release-asset-proof"
        or proof.get("api-version")
        != "three.release.github-release-asset-proof/v1alpha1"
        or proof.get("plan-id") != plan_id
        or proof.get("project-id") != node.get("project-id")
    ):
        return None
    binding = proof.get("binding")
    artifact = proof.get("artifact")
    attestation = proof.get("attestation")
    run = proof.get("run")
    if not isinstance(binding, Mapping):
        return None
    if not isinstance(artifact, Mapping) or not isinstance(
        attestation,
        Mapping,
    ):
        return None
    if not isinstance(run, Mapping):
        return None
    source_digest = attestation.get("source-digest")
    release_target_sha = proof.get("release-target-sha", run.get("head-sha"))
    if not isinstance(source_digest, str):
        return None
    if (
        release_target_sha != commit_sha
        or run.get("head-sha") != source_digest
        or run.get("repository") != repository
        or run.get("live") is not True
        or run.get("dry-run") is not False
        or run.get("validation-only") is not False
    ):
        return None
    if binding.get("publish-node-id") != node_id:
        return None
    if binding.get("artifact-id") != artifact_id:
        return None
    if binding.get("asset-name") != name or binding.get("release-tag") != tag:
        return None
    if artifact.get("byte-size") != expected_size:
        return None
    if artifact.get("sha256") != expected_sha256:
        return None
    if attestation.get("predicate-type") != _GITHUB_ATTESTATION_PREDICATE:
        return None
    if attestation.get("subject-name") != name:
        return None
    if attestation.get("subject-digest") != f"sha256:{expected_sha256}":
        return None
    if attestation.get("signer-workflow") != signer_workflow:
        return None
    if attestation.get("source-repository") != repository:
        return None
    return source_digest


def _github_release_artifact_ids_by_asset_name(node: Json) -> dict[str, str]:
    artifact_ids = node.get("artifact-ids")
    if not isinstance(artifact_ids, Sequence) or isinstance(
        artifact_ids,
        str | bytes,
    ):
        return {}
    active_artifact_ids = {
        raw_artifact_id
        for raw_artifact_id in artifact_ids
        if isinstance(raw_artifact_id, str)
    }
    projection = node.get("projection")
    if not isinstance(projection, Mapping):
        return {}
    names_by_id = projection.get("asset-names-by-artifact-id")
    if not isinstance(names_by_id, Mapping):
        return {}
    return {
        asset_name: artifact_id
        for artifact_id, asset_name in names_by_id.items()
        if isinstance(artifact_id, str)
        and artifact_id in active_artifact_ids
        and isinstance(asset_name, str)
    }


def _github_release_by_tag(repository: str, tag: str) -> Json | None:
    try:
        payload = _gh_api(
            repository,
            f"repos/{repository}/releases/tags/{urllib.parse.quote(tag, safe='/')}",
        )
    except RuntimeError as exc:
        if _is_github_not_found_error(exc):
            return None
        raise
    if not isinstance(payload, dict):
        msg = f"release lookup for {tag!r} returned non-object payload"
        raise TypeError(msg)
    release_id = payload.get("id")
    if isinstance(release_id, int):
        assets = _github_release_assets(repository, release_id)
        sidecars = _download_github_release_asset_proof_sidecars(
            repository=repository,
            tag=tag,
            assets=assets,
        )
        payload["assets"] = assets
        payload["_github-release-asset-proof-sidecars"] = sidecars
        payload["github-release-asset-proofs"] = [
            sidecar["proof"]
            for sidecar in sidecars
            if sidecar.get("valid") is True
            and isinstance(sidecar.get("proof"), Mapping)
        ]
    return payload


def _github_release_assets(repository: str, release_id: int) -> list[Json]:
    payload = _gh_api_paginated(
        repository,
        f"repos/{repository}/releases/{release_id}/assets?per_page=100",
    )
    assets: list[Json] = []
    for item in payload:
        if not isinstance(item, dict):
            msg = f"release assets lookup for {release_id!r} returned non-object item"
            raise TypeError(msg)
        assets.append(item)
    return assets


def _download_github_release_asset_proof_sidecars(
    *,
    repository: str,
    tag: str,
    assets: Sequence[Mapping[str, object]],
) -> list[Json]:
    proof_asset_names = [
        str(name)
        for asset in assets
        if isinstance(name := asset.get("name"), str)
        and _is_github_release_asset_proof_sidecar_name(name)
    ]
    if not proof_asset_names:
        return []
    sidecars: list[Json] = []
    with tempfile.TemporaryDirectory(
        prefix="three-gh-release-proof-"
    ) as temp_dir:
        destination = Path(temp_dir)
        for asset_name in sorted(proof_asset_names):
            sidecar: Json = {"asset-name": asset_name, "valid": False}
            if not _gh_release_download_asset(
                repository=repository,
                tag=tag,
                asset_name=asset_name,
                destination_dir=destination,
            ):
                sidecars.append(sidecar)
                continue
            proof_path = destination / asset_name
            proof = _read_receipt(proof_path)
            if _is_valid_github_release_asset_proof_sidecar_file(
                asset_name,
                proof,
            ):
                sidecar["valid"] = True
                sidecar["proof"] = proof
            sidecars.append(sidecar)
    return sidecars


def _is_github_not_found_error(exc: RuntimeError) -> bool:
    message = str(exc)
    return "HTTP 404" in message or "404 Not Found" in message


def _gh_api(
    repository: str,
    endpoint: str,
    *,
    method: str = "GET",
    fields: Mapping[str, object] | None = None,
) -> Any:
    env = os.environ.copy()
    if "GH_TOKEN" not in env and "GITHUB_TOKEN" in env:
        env["GH_TOKEN"] = env["GITHUB_TOKEN"]
    command = ["gh", "api", endpoint, "--method", method]
    for key, value in (fields or {}).items():
        if isinstance(value, bool):
            command.extend(["-F", f"{key}={'true' if value else 'false'}"])
        else:
            command.extend(["-f", f"{key}={value}"])
    result = subprocess.run(
        command,
        cwd=Path.cwd(),
        env=env,
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        msg = f"gh api failed for {endpoint}: {result.stderr.strip()}"
        raise RuntimeError(msg)
    if not result.stdout.strip():
        return {}
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError as exc:
        msg = f"gh api returned invalid JSON for {endpoint}: {exc}"
        raise RuntimeError(msg) from exc


def _gh_api_paginated(repository: str, endpoint: str) -> list[Any]:
    env = os.environ.copy()
    if "GH_TOKEN" not in env and "GITHUB_TOKEN" in env:
        env["GH_TOKEN"] = env["GITHUB_TOKEN"]
    result = subprocess.run(
        ["gh", "api", endpoint, "--paginate", "--slurp"],
        cwd=Path.cwd(),
        env=env,
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        msg = f"gh api failed for {endpoint}: {result.stderr.strip()}"
        raise RuntimeError(msg)
    if not result.stdout.strip():
        return []
    try:
        payload = json.loads(result.stdout)
    except json.JSONDecodeError as exc:
        msg = f"gh api returned invalid JSON for {endpoint}: {exc}"
        raise RuntimeError(msg) from exc
    if not isinstance(payload, list):
        msg = f"gh api returned non-list payload for {endpoint}"
        raise TypeError(msg)
    if all(isinstance(page, list) for page in payload):
        return [item for page in payload for item in page]
    return payload


def _github_actions_run_artifacts(
    *,
    repository: str,
    run_id: str,
    run_attempt: str | None = None,
    prefixed_artifact_cap: int | None = None,
    excluded_prefixed_artifact_names: Collection[str] = (),
) -> list[Mapping[str, object]]:
    if prefixed_artifact_cap is not None:
        if run_attempt is None:
            msg = "run_attempt is required for bounded CI artifact enumeration"
            raise ValueError(msg)
        return _github_actions_run_prefixed_artifacts_bounded(
            repository=repository,
            run_id=run_id,
            run_attempt=run_attempt,
            prefixed_artifact_cap=prefixed_artifact_cap,
            excluded_prefixed_artifact_names=excluded_prefixed_artifact_names,
        )
    pages = _gh_api_paginated(
        repository,
        f"repos/{repository}/actions/runs/{run_id}/artifacts?per_page=100",
    )
    artifacts: list[Mapping[str, object]] = []
    seen_artifact_ids: set[str] = set()
    for index, page in enumerate(pages):
        for artifact in _github_actions_run_artifact_page_items(page, index):
            artifact_id = artifact.get("id")
            if artifact_id is not None:
                artifact_id_key = str(artifact_id)
                if artifact_id_key in seen_artifact_ids:
                    continue
                seen_artifact_ids.add(artifact_id_key)
            artifacts.append(artifact)
    return artifacts


def _github_actions_run_prefixed_artifacts_bounded(
    *,
    repository: str,
    run_id: str,
    run_attempt: str,
    prefixed_artifact_cap: int,
    excluded_prefixed_artifact_names: Collection[str] = (),
) -> list[Mapping[str, object]]:
    artifacts: list[Mapping[str, object]] = []
    seen_artifact_ids: set[str] = set()
    counted_prefixed_artifacts = 0
    current_attempt_prefix = _ci_attempt_physical_artifact_name_prefix(
        run_id=run_id,
        run_attempt=run_attempt,
    )
    page_number = 1
    scanned_item_count = 0
    while True:
        page = _gh_api(
            repository,
            (
                f"repos/{repository}/actions/runs/{run_id}/artifacts"
                f"?per_page=100&page={page_number}"
            ),
        )
        page_items = _github_actions_run_artifact_page_items(
            page,
            page_number - 1,
        )
        scanned_item_count += len(page_items)
        _raise_for_ci_live_namespace_item_bound(scanned_item_count)
        if not page_items:
            break
        for artifact in page_items:
            artifact_id = artifact.get("id")
            if artifact_id is not None:
                artifact_id_key = str(artifact_id)
                if artifact_id_key in seen_artifact_ids:
                    continue
                seen_artifact_ids.add(artifact_id_key)
            artifact_name = artifact.get("name")
            if (
                artifact.get("expired") is True
                or not isinstance(artifact_name, str)
                or not artifact_name.startswith(current_attempt_prefix)
            ):
                continue
            artifacts.append(artifact)
            if artifact_name not in excluded_prefixed_artifact_names:
                counted_prefixed_artifacts += 1
            if counted_prefixed_artifacts > prefixed_artifact_cap:
                return artifacts
        if len(page_items) < 100:
            break
        _raise_for_ci_live_namespace_probe_bound(
            page_number=page_number,
            scanned_item_count=scanned_item_count,
        )
        page_number += 1
    return artifacts


def _raise_for_ci_live_namespace_item_bound(scanned_item_count: int) -> None:
    if scanned_item_count <= _CI_VALIDATION_LIVE_NAMESPACE_ENUMERATION_ITEM_CAP:
        return
    msg = (
        "CI validation artifact namespace enumeration unavailable during "
        "bounded probe: total artifact item bound exceeded"
    )
    raise RuntimeError(msg)


def _raise_for_ci_live_namespace_probe_bound(
    *,
    page_number: int,
    scanned_item_count: int,
) -> None:
    if (
        page_number < _CI_VALIDATION_LIVE_NAMESPACE_ENUMERATION_PAGE_CAP
        and scanned_item_count
        < _CI_VALIDATION_LIVE_NAMESPACE_ENUMERATION_ITEM_CAP
    ):
        return
    msg = (
        "CI validation artifact namespace enumeration unavailable during "
        "bounded probe: page or total artifact item bound reached before "
        "namespace closure"
    )
    raise RuntimeError(msg)


def _github_actions_run_artifact_page_items(
    page: object,
    index: int,
) -> Sequence[Mapping[str, object]]:
    if isinstance(page, Mapping):
        page_artifacts = page.get("artifacts")
        if not isinstance(page_artifacts, Sequence) or isinstance(
            page_artifacts,
            str | bytes,
        ):
            msg = f"artifact API page {index} is missing artifacts array"
            raise TypeError(msg)
        artifacts: list[Mapping[str, object]] = []
        for artifact in page_artifacts:
            if not isinstance(artifact, Mapping):
                msg = f"artifact API page {index} contains non-object"
                raise TypeError(msg)
            artifacts.append(artifact)
        return artifacts
    if isinstance(page, Sequence) and not isinstance(page, str | bytes):
        artifacts: list[Mapping[str, object]] = []
        for artifact in page:
            if not isinstance(artifact, Mapping):
                msg = f"artifact API page {index} contains non-object"
                raise TypeError(msg)
            artifacts.append(artifact)
        return artifacts
    msg = f"artifact API page {index} has unsupported shape"
    raise TypeError(msg)


def _publish_node_diagnostic(
    code: str,
    message: str,
    node_id: str,
    node: Json,
    snapshot_id: str,
    *,
    details: Json,
) -> Json:
    return _diagnostic(
        code,
        "validation",
        "publish-node",
        message,
        details,
        project_id=node["project-id"],
        publish_node_id=node_id,
        target_instance_snapshot_id=snapshot_id,
        resolved_publish_identity=node["resolved-publish-identity"],
    )


def _diagnostic(
    code: str,
    phase: str,
    scope_kind: str,
    message: str,
    details: Json,
    **extra: Any,
) -> Json:
    result: Json = {
        "api-version": "three.release.planner-diagnostic/v1alpha1",
        "kind": "planner-diagnostic",
        "code": code,
        "message": message,
        "phase": phase,
        "scope-kind": scope_kind,
        "blocking": True,
        "details": details,
    }
    result.update(
        {
            key.replace("_", "-"): value
            for key, value in extra.items()
            if value is not None
        }
    )
    return result


def _diagnostics_document(diagnostics: Sequence[Json]) -> Json:
    document = {
        "api-version": "three.release.planner-diagnostics/v1alpha1",
        "kind": "planner-diagnostics",
        "diagnostics": list(diagnostics),
    }
    validate_contract(document)
    return document


def _normalize_project_ids(value: str) -> list[str]:
    return sorted(
        {
            item.strip()
            for chunk in value.split("\n")
            for item in chunk.split(",")
            if item.strip()
        }
    )


def _split_repository(repository: str) -> tuple[str, str]:
    parts = repository.split("/", 1)
    if len(parts) != 2 or not parts[0] or not parts[1]:
        msg = "repository must use owner/name form"
        raise ValueError(msg)
    return parts[0], parts[1]


def _utc_now() -> str:
    return (
        datetime.now(UTC)
        .replace(microsecond=0)
        .isoformat()
        .replace(
            "+00:00",
            "Z",
        )
    )


def _ci_timing_start() -> tuple[datetime, int]:
    return datetime.now(UTC), time.perf_counter_ns()


def _ci_timing_finish(start: tuple[datetime, int]) -> Json:
    started_at, started_ns = start
    completed_ns = time.perf_counter_ns()
    completed_at = datetime.now(UTC)
    duration_ms = max(0, (completed_ns - started_ns) // 1_000_000)
    elapsed_ms = int((completed_at - started_at).total_seconds() * 1000)
    if (
        completed_at < started_at
        or abs(elapsed_ms - duration_ms) > _CI_TIMING_DURATION_TOLERANCE_MS
    ):
        completed_at = started_at + timedelta(milliseconds=duration_ms)
    return {
        "started-at": _utc_timestamp_milliseconds(started_at),
        "completed-at": _utc_timestamp_milliseconds(completed_at),
        "duration-ms": duration_ms,
    }


def _ci_attach_timing(
    result: Mapping[str, object],
    start: tuple[datetime, int],
) -> Json:
    timed = dict(result)
    timed["timing"] = _ci_timing_finish(start)
    return timed


def _ci_profile_phase_record(
    phases: list[Json] | None,
    phase: str,
    start: tuple[datetime, int],
    *,
    outcome: str,
    cwd: Path | None = None,
    artifact_ref: str | None = None,
    output_path: Path | None = None,
    error: str | None = None,
    **metadata: object,
) -> None:
    if phases is None:
        return
    record: Json = {
        "phase": phase,
        "outcome": outcome,
        **_ci_timing_finish(start),
    }
    if cwd is not None:
        record["cwd"] = cwd.as_posix()
    if artifact_ref is not None:
        record["artifact-ref"] = artifact_ref
    if output_path is not None:
        record["output-path"] = output_path.as_posix()
    if error is not None:
        record["error"] = error
    for key, value in metadata.items():
        if value is None:
            continue
        normalized_key = key.replace("_", "-")
        if isinstance(value, Path):
            record[normalized_key] = value.as_posix()
        else:
            record[normalized_key] = value
    phases.append(record)


def _ci_release_shaped_profile_telemetry(
    profile_phases: Sequence[Mapping[str, object]] | None,
    *,
    release_build_telemetry: Mapping[str, object] | None,
    release_build_telemetries: Sequence[Mapping[str, object]] | None = None,
    repo_root: Path,
) -> Json:
    profile_telemetry: Json = {
        "kind": "release-shaped-validation-profile-telemetry",
        "schema-version": 1,
        "phases": [
            _ci_normalize_top_level_profile_phase_paths(
                phase,
                repo_root=repo_root,
            )
            for phase in profile_phases or ()
        ],
    }
    release_builds = [
        cast("Json", item)
        for item in (
            release_build_telemetries
            if release_build_telemetries is not None
            else (
                [release_build_telemetry]
                if release_build_telemetry is not None
                else []
            )
        )
        if isinstance(item, Mapping)
    ]
    if release_builds:
        profile_telemetry["release-build"] = release_builds[0]
        if len(release_builds) > 1:
            profile_telemetry["release-builds"] = release_builds
    return profile_telemetry


def _ci_normalize_top_level_profile_phase_paths(
    phase: Mapping[str, object],
    *,
    repo_root: Path,
) -> Json:
    normalized: Json = dict(phase)
    for key in (
        "cwd",
        "output-path",
        "binlog-path",
        "binlog-directory",
        "cache-path",
        "descriptor-path",
    ):
        value = normalized.get(key)
        if isinstance(value, str):
            normalized[key] = _ci_normalize_top_level_profile_phase_path(
                value,
                repo_root=repo_root,
            )
    for key in ("output-paths", "binlog-paths"):
        value = normalized.get(key)
        if isinstance(value, Sequence) and not isinstance(value, str | bytes):
            normalized[key] = [
                _ci_normalize_top_level_profile_phase_path(
                    item,
                    repo_root=repo_root,
                )
                if isinstance(item, str)
                else item
                for item in value
            ]
    return normalized


def _ci_normalize_top_level_profile_phase_path(
    value: str,
    *,
    repo_root: Path,
) -> str:
    path = Path(value)
    if path.is_absolute():
        return _ci_profile_relative_path(path, repo_root)
    return PurePosixPath(value.replace("\\", "/")).as_posix()


def _ci_release_build_profile_telemetry(
    bundle_dir: Path | None,
    *,
    repo_root: Path,
) -> Json | None:
    if bundle_dir is None:
        return None
    telemetry_path = bundle_dir / "release-build-profile-telemetry.json"
    telemetry = _read_optional_mapping_json(telemetry_path)
    powershell_telemetry: list[Json] = []
    profile_root = _ci_release_build_profile_root(
        bundle_dir,
        telemetry,
        repo_root=repo_root,
    )
    powershell_dir = (
        profile_root / "powershell" if profile_root is not None else None
    )
    if powershell_dir is not None and powershell_dir.is_dir():
        for path in sorted(powershell_dir.glob("*.json")):
            payload = _read_optional_mapping_json(path)
            if payload is None:
                continue
            payload = dict(payload)
            payload["path"] = _ci_profile_relative_path(path, repo_root)
            payload = cast(
                "Json",
                _ci_normalize_profile_telemetry_paths(
                    payload,
                    repo_root=repo_root,
                    bundle_dir=bundle_dir,
                ),
            )
            powershell_telemetry.append(payload)
    if telemetry is None and not powershell_telemetry:
        return None
    result: Json = {
        "bundle-dir": _ci_profile_relative_path(bundle_dir, repo_root),
    }
    if profile_root is not None:
        result["profile-root"] = _ci_profile_relative_path(
            profile_root,
            repo_root,
        )
    if telemetry is not None:
        executor_telemetry = {
            **dict(telemetry),
            "path": _ci_profile_relative_path(telemetry_path, repo_root),
        }
        result["executor"] = _ci_normalize_profile_telemetry_paths(
            executor_telemetry,
            repo_root=repo_root,
            bundle_dir=bundle_dir,
        )
    if powershell_telemetry:
        result["powershell"] = powershell_telemetry
    return result


def _ci_slowest_release_build_profile_telemetries(
    profile_phases: Sequence[Mapping[str, object]],
    *,
    repo_root: Path,
    limit: int = _CI_RELEASE_PROFILE_EVIDENCE_SLOW_BUILD_LIMIT,
) -> list[Json]:
    if limit <= 0:
        return []
    candidates = [
        candidate
        for phase in profile_phases
        for candidate in (
            _ci_release_build_capture_candidate(phase, repo_root=repo_root),
        )
        if candidate is not None
    ]
    selected: list[Json] = []
    seen: set[str] = set()
    for _duration, _sort_key, bundle_dir, identity in sorted(
        candidates,
        key=lambda item: (-item[0], item[1]),
    ):
        bundle_key = bundle_dir.as_posix()
        if bundle_key in seen:
            continue
        seen.add(bundle_key)
        telemetry = _ci_release_build_profile_telemetry(
            bundle_dir,
            repo_root=repo_root,
        )
        if telemetry is not None:
            telemetry.update(identity)
            selected.append(telemetry)
        if len(selected) >= limit:
            break
    return selected


def _ci_release_build_capture_candidate(
    phase: Mapping[str, object],
    *,
    repo_root: Path,
) -> tuple[int, str, Path, Json] | None:
    if phase.get("phase") != "release-build-execute-build":
        return None
    duration = phase.get("duration-ms")
    output_path = phase.get("output-path")
    if (
        not isinstance(duration, int)
        or isinstance(duration, bool)
        or not isinstance(output_path, str)
        or not output_path
    ):
        return None
    bundle_dir = Path(output_path)
    if not bundle_dir.is_absolute():
        bundle_dir = repo_root / bundle_dir
    identity = _ci_release_build_capture_identity(phase)
    if identity is None:
        return None
    return (
        duration,
        _ci_release_build_capture_sort_key(phase, bundle_dir),
        bundle_dir,
        identity,
    )


def _ci_slowest_release_build_profile_telemetries_with_fallback(
    profile_phases: Sequence[Mapping[str, object]],
    *,
    fallback_bundle_dir: Path | None,
    repo_root: Path,
) -> list[Json]:
    selected = _ci_slowest_release_build_profile_telemetries(
        profile_phases,
        repo_root=repo_root,
    )
    if selected or fallback_bundle_dir is None:
        return selected
    fallback = _ci_release_build_profile_telemetry(
        fallback_bundle_dir,
        repo_root=repo_root,
    )
    return [fallback] if fallback is not None else []


def _ci_release_build_capture_sort_key(
    phase: Mapping[str, object],
    bundle_dir: Path,
) -> str:
    bundle_id = phase.get("bundle-id")
    if isinstance(bundle_id, str) and bundle_id:
        return bundle_id
    return bundle_dir.as_posix()


def _ci_release_build_capture_identity(
    phase: Mapping[str, object],
) -> Json | None:
    identity: Json = {}
    for key in (
        "request-digest",
        "bundle-id",
        "work-group-id",
        "runner-family",
    ):
        value = phase.get(key)
        if not isinstance(value, str) or not value:
            return None
        identity[key] = value
    return identity


def _ci_release_build_profile_root(
    bundle_dir: Path,
    telemetry: Mapping[str, object] | None,
    *,
    repo_root: Path,
) -> Path | None:
    if telemetry is not None:
        profile_root = telemetry.get("profile-root")
        if isinstance(profile_root, str) and profile_root:
            path = Path(profile_root)
            if not path.is_absolute():
                repo_relative_path = repo_root / path
                path = (
                    repo_relative_path
                    if repo_relative_path.exists()
                    else bundle_dir / path
                )
            return path
    legacy_profile = bundle_dir / "_profile"
    return legacy_profile if legacy_profile.is_dir() else None


def _read_optional_mapping_json(path: Path) -> Mapping[str, object] | None:
    if not path.is_file():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return None
    return payload if isinstance(payload, Mapping) else None


def _ci_profile_relative_path(path: Path, repo_root: Path) -> str:
    try:
        return path.resolve().relative_to(repo_root.resolve()).as_posix()
    except ValueError:
        return path.as_posix()


def _ci_normalize_profile_telemetry_paths(
    value: object,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> object:
    if isinstance(value, Mapping):
        normalized: Json = {}
        for key, item in value.items():
            key_text = str(key)
            if key_text == "profile-root" and isinstance(item, str):
                normalized[key_text] = _ci_normalize_profile_root_path_text(
                    item,
                    repo_root=repo_root,
                    bundle_dir=bundle_dir,
                )
            elif key_text in _CI_PROFILE_PATH_KEYS and isinstance(item, str):
                normalized[key_text] = _ci_normalize_profile_path_text(
                    item,
                    repo_root=repo_root,
                    bundle_dir=bundle_dir,
                )
            elif key_text in _CI_PROFILE_PATH_SEQUENCE_KEYS:
                normalized[key_text] = _ci_normalize_profile_path_sequence(
                    item,
                    repo_root=repo_root,
                    bundle_dir=bundle_dir,
                )
            elif key_text in _CI_PROFILE_ARGV_KEYS:
                normalized[key_text] = _ci_normalize_profile_argv_sequence(
                    item,
                    repo_root=repo_root,
                    bundle_dir=bundle_dir,
                )
            else:
                normalized[key_text] = _ci_normalize_profile_telemetry_paths(
                    item,
                    repo_root=repo_root,
                    bundle_dir=bundle_dir,
                )
        return normalized
    if isinstance(value, Sequence) and not isinstance(value, str | bytes):
        return [
            _ci_normalize_profile_telemetry_paths(
                item,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
            )
            for item in value
        ]
    return value


def _ci_normalize_profile_path_sequence(
    value: object,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> object:
    if not isinstance(value, Sequence) or isinstance(value, str | bytes):
        return value
    return [
        _ci_normalize_profile_path_text(
            item,
            repo_root=repo_root,
            bundle_dir=bundle_dir,
        )
        if isinstance(item, str)
        else _ci_normalize_profile_telemetry_paths(
            item,
            repo_root=repo_root,
            bundle_dir=bundle_dir,
        )
        for item in value
    ]


def _ci_normalize_profile_argv_sequence(
    value: object,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> object:
    if not isinstance(value, Sequence) or isinstance(value, str | bytes):
        return value
    normalized: list[object] = []
    path_value_expected = False
    for item in value:
        if not isinstance(item, str):
            normalized.append(item)
            path_value_expected = False
            continue
        if path_value_expected:
            normalized.append(
                _ci_normalize_profile_path_text(
                    item,
                    repo_root=repo_root,
                    bundle_dir=bundle_dir,
                )
            )
            path_value_expected = False
            continue
        normalized.append(
            _ci_normalize_profile_argv_text(
                item,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
            )
        )
        path_value_expected = _ci_profile_argv_switch_expects_path_value(item)
    return normalized


def _ci_normalize_profile_argv_text(
    value: str,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> str:
    match = _CI_MSBUILD_BINLOG_ARG_RE.match(value)
    if match is not None:
        payload = _ci_rewrite_msbuild_binlog_payload_paths(
            match.group("payload"),
            lambda path: _ci_normalize_profile_path_text(
                path,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
            ),
        )
        return f"{match.group('prefix')}{payload}"
    assignment = _CI_PROFILE_ARGV_PATH_ASSIGNMENT_RE.match(value)
    if assignment is not None:
        return (
            f"{assignment.group('switch')}{assignment.group('separator')}"
            f"{_ci_normalize_profile_path_text(assignment.group('path'), repo_root=repo_root, bundle_dir=bundle_dir)}"
        )
    definition = _CI_PROFILE_ARGV_PATH_DEFINITION_RE.match(value)
    if definition is not None:
        return (
            f"{definition.group('prefix')}"
            f"{_ci_normalize_profile_path_text(definition.group('path'), repo_root=repo_root, bundle_dir=bundle_dir)}"
        )
    prefixed = _CI_PROFILE_ARGV_PATH_PREFIX_RE.match(value)
    if prefixed is not None:
        return (
            f"{prefixed.group('prefix')}"
            f"{_ci_normalize_profile_path_text(prefixed.group('path'), repo_root=repo_root, bundle_dir=bundle_dir)}"
        )
    standalone = _ci_normalize_profile_standalone_argv_path(
        value,
        repo_root=repo_root,
        bundle_dir=bundle_dir,
    )
    return value if standalone is None else standalone


def _ci_profile_argv_switch_expects_path_value(value: str) -> bool:
    return value.lower() in _CI_PROFILE_ARGV_PATH_VALUE_SWITCHES


def _ci_profile_argv_path_value_claim_kind(
    value: str,
) -> Literal["file", "directory"] | None:
    normalized = value.lower()
    if normalized in _CI_PROFILE_ARGV_DIRECTORY_PATH_VALUE_SWITCHES:
        return "directory"
    if normalized in _CI_PROFILE_ARGV_PATH_VALUE_SWITCHES:
        return "file"
    return None


def _ci_profile_argv_text_is_opaque_command(value: str) -> bool:
    return (
        _CI_MSBUILD_BINLOG_ARG_RE.match(value) is None
        and _CI_PROFILE_ARGV_PATH_ASSIGNMENT_RE.match(value) is None
        and _CI_PROFILE_ARGV_PATH_DEFINITION_RE.match(value) is None
        and _CI_PROFILE_ARGV_PATH_PREFIX_RE.match(value) is None
        and not _ci_profile_argv_switch_expects_path_value(value)
    )


def _ci_rewrite_msbuild_binlog_payload_paths(
    value: str,
    rewrite_path: Callable[[str], str | None],
) -> str:
    rewritten: list[str] = []
    for index, item in enumerate(value.split(";")):
        name, separator, property_value = item.partition("=")
        if separator and name.lower() == "logfile":
            rewritten_path = _ci_rewrite_msbuild_binlog_path_text(
                property_value,
                rewrite_path,
            )
            rewritten.append(f"{name}{separator}{rewritten_path}")
            continue
        if separator or not item:
            rewritten.append(item)
            continue
        unquoted = _ci_trim_msbuild_binlog_path_quotes(item)
        if index == 0 or _ci_msbuild_binlog_payload_item_looks_path_bearing(
            unquoted,
        ):
            rewritten.append(
                _ci_rewrite_msbuild_binlog_path_text(item, rewrite_path),
            )
        else:
            rewritten.append(item)
    return ";".join(rewritten)


def _ci_rewrite_msbuild_binlog_path_text(
    value: str,
    rewrite_path: Callable[[str], str | None],
) -> str:
    quote = ""
    path_text = value
    if (
        len(value) >= _CI_QUOTED_PROFILE_PATH_MIN_LENGTH
        and value[0] == value[-1]
        and value[0] in {"'", '"'}
    ):
        quote = value[0]
        path_text = value[1:-1]
    rewritten = rewrite_path(path_text)
    if rewritten is None:
        return value
    return f"{quote}{rewritten}{quote}"


def _ci_trim_msbuild_binlog_path_quotes(value: str) -> str:
    if (
        len(value) >= _CI_QUOTED_PROFILE_PATH_MIN_LENGTH
        and value[0] == value[-1]
        and value[0] in {"'", '"'}
    ):
        return value[1:-1]
    return value


def _ci_msbuild_binlog_payload_item_looks_path_bearing(value: str) -> bool:
    if (
        not value
        or "://" in value
        or any(character in value for character in "*?[]")
    ):
        return False
    if value.startswith(("//", "\\\\")):
        return True
    if re.match(r"^[A-Za-z]:[\\/]", value):
        return True
    if value.startswith("/"):
        remainder = value[1:]
        slash_positions = [
            position
            for position in (remainder.find("/"), remainder.find("\\"))
            if position != -1
        ]
        first_slash = min(slash_positions, default=-1)
        option_marker = remainder.find(":")
        return (
            first_slash != -1
            and (option_marker == -1 or option_marker > first_slash)
        ) or value in _CI_PROFILE_POSIX_SINGLE_COMPONENT_ABSOLUTE_PATHS
    return "/" in value or "\\" in value


def _ci_normalize_profile_standalone_argv_path(
    value: str,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> str | None:
    if not value:
        return None
    path = Path(value)
    if path.is_absolute():
        for root in (repo_root, bundle_dir):
            with suppress(OSError, ValueError):
                return path.resolve().relative_to(root.resolve()).as_posix()
        return None
    if "\\" not in value and "/" not in value:
        return None
    if "://" in value or any(character in value for character in "*?[]"):
        return None
    return PurePosixPath(value.replace("\\", "/")).as_posix()


def _ci_normalize_profile_path_text(
    value: str,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> str:
    if not value:
        return value
    path = Path(value)
    if path.is_absolute():
        for root in (repo_root, bundle_dir):
            try:
                return path.resolve().relative_to(root.resolve()).as_posix()
            except (OSError, ValueError):
                continue
        return path.as_posix()
    return PurePosixPath(value.replace("\\", "/")).as_posix()


def _ci_normalize_profile_root_path_text(
    value: str,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> str:
    normalized = _ci_normalize_profile_path_text(
        value,
        repo_root=repo_root,
        bundle_dir=bundle_dir,
    )
    path = PurePosixPath(normalized)
    bundle_relative = _ci_profile_relative_path(bundle_dir, repo_root)
    bundle_path = PurePosixPath(bundle_relative)
    if (
        normalized
        and not Path(value).is_absolute()
        and path.parts
        and path.parts[:1] != bundle_path.parts[:1]
    ):
        return (bundle_path / path).as_posix()
    return normalized


def _ci_validation_result_timing(
    validation_result: Mapping[str, object] | None,
) -> object:
    if validation_result is None:
        return None
    timing = validation_result.get("timing")
    if not isinstance(timing, Mapping):
        return timing
    return dict(timing)


def _ci_validation_result_command_timings(
    validation_result: Mapping[str, object] | None,
) -> list[Json]:
    commands = (
        None if validation_result is None else validation_result.get("commands")
    )
    if not isinstance(commands, Sequence) or isinstance(commands, str | bytes):
        return []
    result: list[Json] = []
    for command in commands:
        if not isinstance(command, Mapping) or "timing" not in command:
            continue
        result.append(
            {
                "index": command.get("index"),
                "label": command.get("label"),
                "capability": command.get("capability"),
                "outcome": command.get("outcome"),
                "timing": _ci_validation_command_timing(command),
            }
        )
    return result


def _ci_validation_command_timing(command: Mapping[str, object]) -> object:
    timing = command.get("timing")
    if not isinstance(timing, Mapping):
        return timing
    return dict(timing)


def _utc_timestamp_milliseconds(value: datetime) -> str:
    return (
        value.astimezone(UTC)
        .isoformat(timespec="milliseconds")
        .replace(
            "+00:00",
            "Z",
        )
    )


def _ci_affected_range(args: argparse.Namespace) -> Json:
    status = args.range_status or "unavailable"
    if status == "available":
        changed_files = json.loads(args.changed_files_json or "[]")
        if not isinstance(changed_files, list) or not all(
            isinstance(item, str) for item in changed_files
        ):
            msg = "--changed-files-json must be a JSON string array"
            raise TypeError(msg)
        return {
            "status": "available",
            "base-sha": args.base_sha or None,
            "base-tip-sha": args.base_tip_sha or None,
            "head-sha": args.head_sha or None,
            "changed-files": sorted(changed_files),
            "source": args.mode,
            "diagnostic": None,
            "diagnostic-detail": None,
        }
    return {
        "status": "unavailable",
        "base-sha": args.base_sha or None,
        "base-tip-sha": args.base_tip_sha or None,
        "head-sha": args.head_sha or None,
        "changed-files": None,
        "source": args.mode,
        "diagnostic": "range-unconfirmed",
        "diagnostic-detail": args.range_diagnostic_detail,
    }


def _ci_executable_work_groups(
    plan: Mapping[str, object],
) -> list[Mapping[str, Any]]:
    groups = plan.get("work-groups")
    if not isinstance(groups, Sequence) or isinstance(groups, str | bytes):
        return []
    result: list[Mapping[str, Any]] = []
    for group in groups:
        if not isinstance(group, Mapping):
            continue
        if group.get("kind") == "evidence-aggregation":
            continue
        work_group_id = group.get("work-group-id")
        if isinstance(work_group_id, str):
            result.append(_mapping(group, "work-group"))
    return sorted(result, key=lambda item: str(item["work-group-id"]))


def _executable_ci_work_group_ids(plan: Mapping[str, object]) -> list[str]:
    return [
        str(group["work-group-id"])
        for group in _ci_executable_work_groups(plan)
    ]


def _ci_work_group_matrix_entry(
    plan: Mapping[str, object],
    group: Mapping[str, Any],
    *,
    dependency_layer: int,
    writer_job: str,
) -> Json:
    runner_family = str(group["runner-family"])
    return {
        "work-group-id": str(group["work-group-id"]),
        "kind": str(group.get("kind")),
        "runner-family": runner_family,
        "runner": runner_family,
        "ecosystem": group.get("ecosystem"),
        "coverage-target": group.get("coverage-target"),
        "selector-variant": group.get("selector-variant"),
        "depends-on": [
            str(item)
            for item in cast("Sequence[object]", group.get("depends-on", []))
        ],
        "dependency-layer": dependency_layer,
        "writer-job": writer_job,
        "validation-commands": _ci_validation_commands(plan, group),
        "no-publish": True,
    }


def _ci_validation_commands(
    plan: Mapping[str, object],
    group: Mapping[str, Any],
) -> list[Json]:
    kind = str(group.get("kind"))
    if kind == "ecosystem-gate":
        return _ci_ecosystem_validation_commands(plan, group)
    if kind == "descriptor-validation":
        return [
            _ci_command(
                "validate scoped workflow-release descriptors",
                [
                    "uv",
                    "run",
                    "python",
                    "eng/scripts/workflow_release_control.py",
                    "validate-ci-validation-descriptors",
                    "--plan",
                    ".three-ci-validation/plan/validation-plan.json",
                    "--work-group-id",
                    str(group.get("work-group-id")),
                    "--repo-root",
                    ".",
                ],
            )
        ]
    if kind == "lightweight-preflight":
        return [
            _ci_builtin_command(
                "validate lightweight preflight policy",
                "lightweight-preflight",
            )
        ]
    if kind == "release-shaped-artifact":
        return [
            _ci_builtin_command(
                "validate release-shaped artifact obligations",
                "release-shaped-artifact",
            )
        ]
    if kind == "workflow-release-tooling":
        return _ci_workflow_release_tooling_validation_commands(group)
    return []


def _ci_work_group_matrix_command_context(group: Mapping[str, Any]) -> Json:
    return {
        "work-group-id": str(group.get("work-group-id")),
        "kind": str(group.get("kind")),
        "runner-family": group.get("runner-family"),
        "coverage-target": group.get("coverage-target"),
        "no-publish": True,
    }


def _ci_ecosystem_validation_commands(
    plan: Mapping[str, object],
    group: Mapping[str, Any],
) -> list[Json]:
    ecosystem = str(group.get("ecosystem"))
    root = _ci_work_group_subject_root(plan, group)
    expectation = cast(
        "Mapping[str, object]",
        group.get("expected-evidence", {}),
    )
    capabilities = [
        str(item)
        for item in cast(
            "Sequence[object]",
            expectation.get("planned-capabilities", []),
        )
    ]
    if ecosystem == "dotnet":
        return _ci_dotnet_validation_commands(root, capabilities)
    if ecosystem == "python":
        return _ci_python_validation_commands(root, capabilities)
    if ecosystem in {"javascript", "typescript"}:
        return _ci_javascript_validation_commands(root, capabilities)
    if ecosystem == "ruby":
        return _ci_ruby_validation_commands(root, capabilities)
    return []


def _ci_dotnet_validation_commands(
    root: str,
    capabilities: Sequence[str],
) -> list[Json]:
    target = root if root != "." else "dirs.proj"
    commands: list[Json] = []
    if "build" in capabilities:
        commands.append(
            _ci_command(
                "dotnet build",
                ["dotnet", "build", target],
                capability="build",
            )
        )
    if "test" in capabilities:
        dotnet_test_argv = [
            "dotnet",
            "test",
            target,
        ]
        if "build" in capabilities:
            dotnet_test_argv.extend(["--no-restore", "--no-build"])
        commands.append(
            _ci_command(
                "dotnet test",
                dotnet_test_argv,
                capability="test",
            )
        )
    if "type-check" in capabilities:
        commands.append(
            _ci_command(
                "dotnet type check",
                ["dotnet", "build", target],
                capability="type-check",
            )
        )
    if "format" in capabilities:
        commands.append(
            _ci_command(
                "dotnet format check",
                ["dotnet", "format", target, "--verify-no-changes"],
                capability="format",
            )
        )
    return commands


def _ci_python_validation_commands(
    root: str,
    capabilities: Sequence[str],
) -> list[Json]:
    commands: list[Json] = []
    if "build" in capabilities:
        commands.append(
            _ci_command(
                "python build",
                [
                    "uv",
                    "build",
                    "--out-dir",
                    ".three-ci-validation/work/validation-build",
                    root,
                ],
                capability="build",
            )
        )
    if "test" in capabilities:
        commands.append(
            _ci_command(
                "python tests",
                ["uv", "run", "pytest", root],
                capability="test",
            )
        )
    if "lint" in capabilities:
        commands.append(
            _ci_command(
                "python lint",
                ["uv", "run", "ruff", "check", "--force-exclude", root],
                capability="lint",
            )
        )
    if "format" in capabilities:
        commands.append(
            _ci_command(
                "python format check",
                [
                    "uv",
                    "run",
                    "ruff",
                    "format",
                    "--quiet",
                    "--force-exclude",
                    "--check",
                    root,
                ],
                capability="format",
            )
        )
    if "type-check" in capabilities:
        commands.append(
            _ci_command(
                "python type check",
                [
                    "uv",
                    "run",
                    "--project",
                    root,
                    "--python",
                    "3.13",
                    "--with",
                    "pyrefly",
                    "pyrefly",
                    "check",
                    root,
                    "--summary=none",
                    "--output-format=min-text",
                ],
                capability="type-check",
            )
        )
    return commands


def _ci_javascript_validation_commands(
    root: str,
    capabilities: Sequence[str],
) -> list[Json]:
    script_by_capability = {
        "build": "build",
        "test": "test",
        "lint": "lint",
        "type-check": "typecheck",
    }
    commands = [
        _ci_command(
            "javascript-typescript install",
            ["pnpm", "install", "--frozen-lockfile"],
        )
    ]
    commands.extend(
        _ci_command(
            f"javascript-typescript {script}",
            ["pnpm", "--dir", root, "run", script],
            capability=capability,
        )
        for capability, script in script_by_capability.items()
        if capability in capabilities
    )
    if "format" in capabilities:
        commands.append(
            _ci_command(
                "javascript-typescript format check",
                [
                    "pnpm",
                    "--dir",
                    root,
                    "exec",
                    "biome",
                    "format",
                    "--check",
                    ".",
                ],
                capability="format",
            )
        )
    return commands


def _ci_ruby_validation_commands(
    root: str,
    capabilities: Sequence[str],
) -> list[Json]:
    commands: list[Json] = []
    if "build" in capabilities:
        commands.append(
            _ci_command(
                "ruby versioning tool restore",
                ["dotnet", "tool", "restore"],
                capability="build",
            )
        )
        commands.append(
            _ci_command(
                "ruby gem build",
                [
                    "ruby",
                    "-e",
                    (
                        "root=ARGV.fetch(0); "
                        "out=ARGV.fetch(1); "
                        "gemspec=Dir[File.join(root, '*.gemspec')].sort.first; "
                        'abort("no gemspec found under #{root}") unless gemspec; '
                        "system('gem', 'build', gemspec, '--output', out) "
                        "or exit($?.exitstatus || 1)"
                    ),
                    root,
                    ".three-ci-validation/work/validation-build.gem",
                ],
                capability="build",
            )
        )
    return commands


def _ci_workflow_release_tooling_validation_commands(
    group: Mapping[str, Any],
) -> list[Json]:
    target = group.get("coverage-target")
    surface = ""
    if isinstance(target, Mapping) and target.get("type") == "tooling-surface":
        surface = str(target.get("id") or "")
    if surface == "fact-provider":
        return _ci_python_validation_commands(
            "src/public/lib/three-workflow-release-metadata",
            ["lint", "type-check", "test"],
        )
    path_by_surface = {
        "planner": "src/public/lib/three-workflow-release-planner",
        "classifier": "src/public/lib/three-workflow-release-planner",
        "descriptor-contract": "src/public/lib/three-workflow-release-contracts",
        "workflow-release-contract": "src/public/lib/three-workflow-release-contracts",
        "authoring-validation": "src/public/lib/three-workflow-release-authoring",
        "target-catalog": "src/public/lib/three-workflow-release-planner",
        "build-execution": "src/public/lib/three-workflow-release-build",
        "publish-execution": "src/public/lib/three-workflow-release-publish",
        "smoke-validation": "tests/test_workflow_release_control.py",
        "descriptor-schema-documentation": (
            "src/public/lib/three-workflow-release-authoring"
        ),
    }
    if surface == "workflow-orchestration":
        return [
            _ci_command(
                "workflow-release orchestration tests",
                [
                    "uv",
                    "run",
                    "python",
                    "-m",
                    "pytest",
                    "tests/test_workflow_release_control.py",
                    "-q",
                ],
            )
        ]
    path = path_by_surface.get(surface)
    if path is None:
        return [
            _ci_builtin_command(
                "validate workflow-release tooling surface",
                "workflow-release-tooling",
            )
        ]
    return [
        _ci_command(
            f"workflow-release {surface} tooling lint",
            ["uv", "run", "ruff", "check", "--force-exclude", path],
        )
    ]


def _ci_work_group_subject_root(
    plan: Mapping[str, object],
    group: Mapping[str, Any],
) -> str:
    target = group.get("coverage-target")
    subject_id = None
    if isinstance(target, Mapping) and target.get("type") == "subject":
        subject_id = target.get("id")
    subjects = plan.get("subjects")
    if isinstance(subjects, Sequence) and not isinstance(subjects, str | bytes):
        for subject in subjects:
            if (
                isinstance(subject, Mapping)
                and subject.get("subject-id") == subject_id
                and isinstance(subject.get("root"), str)
            ):
                return str(subject["root"])
    return "."


def _ci_command(
    label: str,
    argv: Sequence[str],
    *,
    capability: str | None = None,
) -> Json:
    return {
        "label": label,
        "argv": [str(item) for item in argv],
        "capability": capability,
    }


def _ci_builtin_command(label: str, builtin: str) -> Json:
    return {
        "label": label,
        "argv": [],
        "builtin": builtin,
        "capability": None,
    }


def _ci_work_group_dependency_layers(
    plan: Mapping[str, object],
) -> dict[str, int]:
    groups = {
        str(group["work-group-id"]): group
        for group in _ci_executable_work_groups(plan)
    }
    layers: dict[str, int] = {}

    def layer(work_group_id: str, visiting: set[str]) -> int:
        if work_group_id in layers:
            return layers[work_group_id]
        if work_group_id in visiting:
            msg = f"work group dependency cycle includes {work_group_id}"
            raise RuntimeError(msg)
        visiting.add(work_group_id)
        group = groups[work_group_id]
        dependencies = [
            str(item)
            for item in cast("Sequence[object]", group.get("depends-on", []))
            if str(item) in groups
        ]
        value = (
            max(layer(dependency, visiting) for dependency in dependencies) + 1
            if dependencies
            else 0
        )
        visiting.remove(work_group_id)
        layers[work_group_id] = value
        return value

    for work_group_id in sorted(groups):
        layer(work_group_id, set())
    return layers


def _ci_work_group_matrix_layers(
    matrix: Sequence[Mapping[str, object]],
) -> list[list[Json]]:
    layer_count = (
        max(_ci_dependency_layer_index(item) for item in matrix) + 1
        if matrix
        else 0
    )
    return [
        [
            dict(item)
            for item in matrix
            if _ci_dependency_layer_index(item) == layer_index
        ]
        for layer_index in range(layer_count)
    ]


def _ci_dependency_layer_index(item: Mapping[str, object]) -> int:
    layer = item.get("dependency-layer")
    if isinstance(layer, int | str):
        return int(layer)
    msg = "dependency-layer must be an integer"
    raise TypeError(msg)


def _ci_dependency_blocked(
    *,
    plan: Mapping[str, object],
    assignments: Mapping[str, object],
    work_group_id: str,
    observed_artifacts_dir: str,
    changed_files_snapshot: Mapping[str, object] | None,
    fact_snapshot: Mapping[str, object] | None,
) -> bool:
    _ = (
        assignments,
        observed_artifacts_dir,
        changed_files_snapshot,
        fact_snapshot,
    )
    dependencies = [
        str(item)
        for item in cast(
            "Sequence[object]",
            _ci_work_group(plan, work_group_id).get("depends-on", []),
        )
    ]
    return bool(dependencies)


def _read_json_value(value: str) -> object:
    return json.loads(value)


def _ci_validation_diagnostics(
    plan: Mapping[str, object],
    work_group_id: str,
    *,
    outcome: str,
) -> list[Json]:
    if outcome == "success":
        return []
    return [_ci_validation_diagnostic(plan, work_group_id, outcome)]


def _ci_validation_diagnostic(
    plan: Mapping[str, object],
    work_group_id: str,
    outcome: str,
) -> Json:
    if outcome == "blocking-failure":
        group = _ci_work_group(plan, work_group_id)
        kind = str(group.get("kind") or "validation-work")
        if kind == "release-shaped-artifact":
            return ci_validation_diagnostic(
                diagnostic_id=(
                    f"artifact-shape-unconfirmed/{work_group_id}/bytes"
                ),
                code=DiagnosticFamily.ARTIFACT_SHAPE_UNCONFIRMED.value,
                detail=DiagnosticDetail.INCOMPLETE.value,
                message=(
                    "Release-shaped artifact validation did not produce "
                    "byte-bound no-publish artifact evidence."
                ),
                source_type="work-group",
                source_id=work_group_id,
                severity=DiagnosticSeverity.BLOCKING_FAILURE.value,
                verdict_effect=DiagnosticVerdictEffect.FAILED.value,
            )
        return ci_validation_diagnostic(
            diagnostic_id=f"validation-work-failed/{work_group_id}/execution",
            code=DiagnosticFamily.VALIDATION_WORK_FAILED.value,
            detail=DiagnosticDetail.TOOLING.value,
            message=(
                f"No-publish CI validation execution for {kind} did not "
                "complete successfully."
            ),
            source_type="work-group",
            source_id=work_group_id,
            severity=DiagnosticSeverity.BLOCKING_FAILURE.value,
            verdict_effect=DiagnosticVerdictEffect.FAILED.value,
        )
    return ci_validation_diagnostic(
        diagnostic_id=f"validation-work-skipped/{work_group_id}/dependency",
        code=DiagnosticFamily.VALIDATION_WORK_SKIPPED.value,
        detail=DiagnosticDetail.DEPENDENCY_BLOCKED.value,
        message=(
            "No-publish CI validation execution was skipped because a planned "
            "prerequisite work group did not produce a dependency result "
            "admitted for gating from same-batch results or admitted upstream "
            "batch evidence."
        ),
        source_type="work-group",
        source_id=work_group_id,
        severity=DiagnosticSeverity.WARNING.value,
        verdict_effect=DiagnosticVerdictEffect.NONE.value,
    )


def _ci_capability_failure_diagnostic(
    work_group_id: str,
    capability: str,
) -> Json:
    detail_by_capability = {
        "build": DiagnosticDetail.BUILD.value,
        "test": DiagnosticDetail.TEST.value,
        "lint": DiagnosticDetail.LINT.value,
        "format": DiagnosticDetail.FORMAT.value,
        "type-check": DiagnosticDetail.TYPE_CHECK.value,
    }
    return ci_validation_diagnostic(
        diagnostic_id=(
            f"validation-work-failed/{work_group_id}/capability/{capability}"
        ),
        code=DiagnosticFamily.VALIDATION_WORK_FAILED.value,
        detail=detail_by_capability.get(
            capability, DiagnosticDetail.TOOLING.value
        ),
        message=(
            f"No-publish CI validation command for planned capability "
            f"{capability!r} did not complete successfully."
        ),
        source_type="work-group",
        source_id=work_group_id,
        severity=DiagnosticSeverity.BLOCKING_FAILURE.value,
        verdict_effect=DiagnosticVerdictEffect.FAILED.value,
    )


def _ci_validation_outcome(
    plan: Mapping[str, object],
    work_group_id: str,
    *,
    dependency_blocked: bool,
    validation_result: Mapping[str, object] | None,
    assignments: Mapping[str, object] | None = None,
    observed_artifacts_dir: str = "",
    observed_commit_sha: str = "",
    changed_files_snapshot: Mapping[str, object] | None = None,
    fact_snapshot: Mapping[str, object] | None = None,
) -> _CiValidationOutcome:
    if dependency_blocked:
        return "skipped"
    if (
        validation_result is not None
        and _ci_validation_result_has_success_evidence(
            plan,
            work_group_id,
            validation_result,
            assignments=assignments,
            observed_artifacts_dir=observed_artifacts_dir,
            observed_commit_sha=observed_commit_sha,
            changed_files_snapshot=changed_files_snapshot,
            fact_snapshot=fact_snapshot,
        )
    ):
        return "success"
    return "blocking-failure"


def _ci_validation_result_has_success_evidence(
    plan: Mapping[str, object],
    work_group_id: str,
    validation_result: Mapping[str, object],
    *,
    assignments: Mapping[str, object] | None = None,
    observed_artifacts_dir: str = "",
    observed_commit_sha: str = "",
    changed_files_snapshot: Mapping[str, object] | None = None,
    fact_snapshot: Mapping[str, object] | None = None,
) -> bool:
    if validation_result.get("outcome") != "success" or not (
        _ci_validation_result_identity_matches(
            plan,
            work_group_id,
            validation_result,
            observed_commit_sha=observed_commit_sha,
        )
    ):
        return False
    commands = validation_result.get("commands")
    if not isinstance(commands, Sequence) or isinstance(commands, str | bytes):
        return False
    is_release_shaped = (
        _ci_work_group(plan, work_group_id).get("kind")
        == "release-shaped-artifact"
    )
    command_mappings = [
        command for command in commands if isinstance(command, Mapping)
    ]
    if not command_mappings or (
        is_release_shaped and len(command_mappings) != len(commands)
    ):
        return False
    if is_release_shaped:
        release_results = _ci_release_shaped_results_from_validation_result(
            plan,
            work_group_id,
            validation_result,
            fact_snapshot=fact_snapshot,
        )
        return (
            all(
                command.get("outcome") == "success"
                for command in command_mappings
            )
            and _ci_release_shaped_result_has_admissible_source(
                plan=plan,
                work_group_id=work_group_id,
                validation_result=validation_result,
                command_mappings=command_mappings,
                assignments=assignments,
                observed_artifacts_dir=observed_artifacts_dir,
                observed_commit_sha=observed_commit_sha,
                changed_files_snapshot=changed_files_snapshot,
                fact_snapshot=fact_snapshot,
            )
            and release_results is not None
            and not _ci_release_shaped_results_contain_plan_fabrication(
                plan, work_group_id, release_results
            )
        )
    expectation = _ci_evidence_expectation(plan, work_group_id)
    planned_capabilities = expectation.get("planned-capabilities")
    if isinstance(planned_capabilities, Sequence) and not isinstance(
        planned_capabilities, str | bytes
    ):
        commands_by_capability = _ci_command_results_by_capability(
            validation_result,
        )
        return all(
            commands_by_capability.get(str(capability))
            and all(
                command.get("outcome") == "success"
                for command in commands_by_capability[str(capability)]
            )
            for capability in planned_capabilities
        )
    return all(
        command.get("outcome") == "success" for command in command_mappings
    )


def _ci_validation_result_identity_matches(
    plan: Mapping[str, object],
    work_group_id: str,
    validation_result: Mapping[str, object],
    *,
    observed_commit_sha: str = "",
) -> bool:
    planned_work_group = _ci_work_group(plan, work_group_id)
    if not (
        validation_result.get("work-group-id") == work_group_id
        and validation_result.get("kind") == planned_work_group.get("kind")
        and validation_result.get("runner-family")
        == planned_work_group.get("runner-family")
    ):
        return False
    validation_tree = plan.get("validation-tree")
    if not isinstance(validation_tree, Mapping):
        return False
    result_commit = validation_result.get("observed-commit-sha")
    return bool(
        result_commit == validation_tree.get("commit-sha")
        and (not observed_commit_sha or result_commit == observed_commit_sha)
        and validation_result.get("coverage-target")
        == planned_work_group.get("coverage-target")
    )


def _ci_release_shaped_result_has_admissible_source(
    *,
    plan: Mapping[str, object],
    work_group_id: str,
    validation_result: Mapping[str, object],
    command_mappings: Sequence[Mapping[str, object]],
    assignments: Mapping[str, object] | None,
    observed_artifacts_dir: str,
    observed_commit_sha: str,
    changed_files_snapshot: Mapping[str, object] | None,
    fact_snapshot: Mapping[str, object] | None,
) -> bool:
    if (
        not observed_commit_sha
        or validation_result.get("observed-commit-sha") != observed_commit_sha
    ):
        return False
    source_command = _ci_no_publish_source_command_from_validation_result(
        validation_result,
    )
    if source_command is not None:
        source_detail: Json = {
            "evidence-source": "no-publish-validation",
            "source-proof": dict(
                cast("Mapping[str, object]", source_command["source-proof"]),
            ),
            "artifact-obligation-results": [
                dict(item)
                for item in cast(
                    "Sequence[Mapping[str, object]]",
                    source_command["artifact-obligation-results"],
                )
            ],
        }
        return _ci_no_publish_release_shaped_source_proof_is_admissible(
            {
                "work-group-id": work_group_id,
                "coverage-target": validation_result.get("coverage-target"),
                "execution-tree": {
                    "observed-commit-sha": observed_commit_sha,
                },
            },
            source_detail,
            source_validation_result=validation_result,
        )
    return False


def _ci_release_shaped_results_from_validation_result(
    plan: Mapping[str, object],
    work_group_id: str,
    validation_result: Mapping[str, object],
    *,
    fact_snapshot: Mapping[str, object] | None,
) -> list[Mapping[str, object]] | None:
    commands = validation_result.get("commands")
    if not isinstance(commands, Sequence) or isinstance(commands, str | bytes):
        return None
    results: list[Mapping[str, object]] = []
    for command in commands:
        if not isinstance(command, Mapping):
            continue
        command_results = command.get("artifact-obligation-results")
        if not isinstance(command_results, Sequence) or isinstance(
            command_results, str | bytes
        ):
            continue
        for result in command_results:
            if not isinstance(result, Mapping):
                return None
            results.append(result)
    if not _ci_release_shaped_results_match_plan(
        plan,
        work_group_id,
        results,
        fact_snapshot=fact_snapshot,
    ):
        return None
    return results


def _ci_release_shaped_results_match_plan(
    plan: Mapping[str, object],
    work_group_id: str,
    results: Sequence[Mapping[str, object]],
    *,
    fact_snapshot: Mapping[str, object] | None,
) -> bool:
    obligations = _ci_plan_records_for_work_group(
        plan, "artifact-obligations", work_group_id
    )
    if not obligations:
        return False
    obligations_by_id = {
        str(obligation["artifact-obligation-id"]): obligation
        for obligation in obligations
    }
    result_ids = [
        str(result.get("artifact-obligation-id")) for result in results
    ]
    if len(result_ids) != len(set(result_ids)) or set(result_ids) != set(
        obligations_by_id
    ):
        return False
    return all(
        _ci_release_shaped_result_matches_obligation(
            result,
            obligations_by_id[str(result.get("artifact-obligation-id"))],
            fact_snapshot=fact_snapshot,
        )
        for result in results
    )


def _ci_release_shaped_results_contain_plan_fabrication(
    plan: Mapping[str, object],
    work_group_id: str,
    results: Sequence[Mapping[str, object]],
) -> bool:
    obligations = _ci_plan_records_for_work_group(
        plan, "artifact-obligations", work_group_id
    )
    obligations_by_id = {
        str(obligation["artifact-obligation-id"]): obligation
        for obligation in obligations
    }
    return any(
        _ci_release_result_is_fabricated_from_plan(result, obligations_by_id)
        for result in results
    )


def _ci_release_result_is_fabricated_from_plan(
    result: Mapping[str, object],
    obligations_by_id: Mapping[str, Mapping[str, object]],
) -> bool:
    obligation = obligations_by_id.get(
        str(result.get("artifact-obligation-id"))
    )
    artifact = result.get("artifact")
    if obligation is None or not isinstance(artifact, Mapping):
        return False
    observed = artifact.get("observed")
    if not isinstance(observed, Mapping):
        return False
    digests = observed.get("digests")
    if not isinstance(digests, Sequence) or isinstance(digests, str | bytes):
        return False
    return any(
        isinstance(item, Mapping)
        and isinstance(item.get("artifact-ref"), str)
        and item.get("digest")
        == _ci_fabricated_release_artifact_digest(
            obligation,
            str(item["artifact-ref"]),
        )
        for item in digests
    )


def _ci_fabricated_release_artifact_digest(
    obligation: Mapping[str, object],
    artifact_ref: str,
) -> str:
    return canonical_json_digest(
        {
            "artifact-obligation-id": obligation["artifact-obligation-id"],
            "artifact-ref": artifact_ref,
            "artifact": obligation["artifact"],
            "release-receipt": obligation["release-receipt"],
        }
    )


def _ci_release_shaped_result_matches_obligation(
    result: Mapping[str, object],
    obligation: Mapping[str, object],
    *,
    fact_snapshot: Mapping[str, object] | None,
) -> bool:
    artifact = result.get("artifact")
    release_receipt = result.get("release-receipt")
    descriptor = result.get("descriptor")
    if not isinstance(artifact, Mapping) or not isinstance(
        release_receipt, Mapping
    ):
        return False
    if not isinstance(descriptor, Mapping):
        return False
    descriptor_path = str(obligation.get("descriptor-path"))
    descriptor_fact = _ci_descriptor_fact(fact_snapshot, descriptor_path)
    expected_descriptor_identity = (
        descriptor_fact.get("descriptor-identity")
        if descriptor_fact is not None
        else None
    )
    if (
        not isinstance(expected_descriptor_identity, str)
        or not expected_descriptor_identity
    ):
        return False
    planned_artifact = obligation.get("artifact")
    planned_receipt = obligation.get("release-receipt")
    expected_refs = _ci_artifact_expected_refs(obligation)
    return (
        bool(expected_refs)
        and descriptor.get("path") == descriptor_path
        and descriptor.get("identity") == expected_descriptor_identity
        and result.get("outcome") == "success"
        and result.get("diagnostics") == []
        and result.get("profile-coverage") == obligation.get("profile-coverage")
        and artifact.get("planned") == planned_artifact
        and _ci_artifact_observed_refs(artifact) == expected_refs
        and _ci_artifact_observed_digests_match_refs(artifact, expected_refs)
        and artifact.get("outcome") == "success"
        and artifact.get("diagnostics") == []
        and release_receipt.get("planned") == planned_receipt
        and release_receipt.get("expected") is True
        and release_receipt.get("schema-checked") is True
        and release_receipt.get("outcome") == "success"
        and release_receipt.get("diagnostics") == []
    )


def _ci_artifact_expected_refs(
    obligation: Mapping[str, object],
) -> list[str]:
    artifact = obligation.get("artifact")
    if not isinstance(artifact, Mapping):
        return []
    refs = artifact.get("expected-artifact-refs")
    if not isinstance(refs, Sequence) or isinstance(refs, str | bytes):
        return []
    return [str(item) for item in refs if isinstance(item, str)]


def _ci_artifact_observed_refs(artifact: Mapping[str, object]) -> list[str]:
    observed = artifact.get("observed")
    if not isinstance(observed, Mapping):
        return []
    refs = observed.get("refs")
    if not isinstance(refs, Sequence) or isinstance(refs, str | bytes):
        return []
    return [str(item) for item in refs if isinstance(item, str)]


def _ci_artifact_observed_digests_match_refs(
    artifact: Mapping[str, object],
    expected_refs: Sequence[str],
) -> bool:
    observed = artifact.get("observed")
    if not isinstance(observed, Mapping):
        return False
    digests = observed.get("digests")
    if not isinstance(digests, Sequence) or isinstance(digests, str | bytes):
        return False
    seen: set[str] = set()
    for item in digests:
        if not isinstance(item, Mapping):
            return False
        artifact_ref = item.get("artifact-ref")
        digest = item.get("digest")
        if (
            not isinstance(artifact_ref, str)
            or artifact_ref in seen
            or item.get("algorithm") != "sha256"
            or item.get("digest-available") is not True
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            or item.get("diagnostics") != []
        ):
            return False
        seen.add(artifact_ref)
    return seen == set(expected_refs)


def _ci_release_shaped_observed_refs(
    results: Sequence[Mapping[str, object]],
) -> list[str]:
    refs: list[str] = []
    for result in results:
        artifact = result.get("artifact")
        if isinstance(artifact, Mapping):
            refs.extend(_ci_artifact_observed_refs(artifact))
    return refs


def _ci_validation_evidence(
    plan: Mapping[str, object],
    work_group_id: str,
    *,
    outcome: str,
    diagnostics: Sequence[Mapping[str, object]],
    validation_result: Mapping[str, object] | None = None,
    fact_snapshot: Mapping[str, object] | None = None,
    batch_bundle: bool = False,
) -> Json:
    expectation = _ci_evidence_expectation(plan, work_group_id)
    category = str(expectation["category"])
    if isinstance(expectation.get("planned-capabilities"), Sequence):
        capabilities = [
            str(item)
            for item in cast(
                "Sequence[object]",
                expectation["planned-capabilities"],
            )
        ]
        capability_results = _ci_capability_results(
            work_group_id=work_group_id,
            capabilities=capabilities,
            outcome=outcome,
            diagnostics=diagnostics,
            validation_result=validation_result,
        )
        return {
            "category": category,
            "planned-capabilities": capabilities,
            "capability-results": capability_results,
            "artifact-refs": [],
        }
    category_result: Json = {
        "outcome": outcome,
        "diagnostics": [dict(item) for item in diagnostics],
    }
    if batch_bundle:
        category_result["category"] = category
        if category == "release-shaped-artifact" and outcome != "success":
            detail = _ci_validation_detail(
                plan,
                work_group_id,
                category,
                diagnostics,
                outcome=outcome,
                fact_snapshot=fact_snapshot,
            )
            if validation_result is not None:
                _ci_add_release_shaped_profile_telemetry(
                    detail,
                    validation_result,
                )
            category_result["detail"] = detail
    else:
        category_result["detail"] = _ci_validation_detail(
            plan,
            work_group_id,
            category,
            diagnostics,
            outcome=outcome,
            fact_snapshot=fact_snapshot,
        )
    artifact_refs: list[str] = []
    if (
        category == "release-shaped-artifact"
        and outcome == "success"
        and validation_result is not None
    ):
        release_results = _ci_release_shaped_results_from_validation_result(
            plan,
            work_group_id,
            validation_result,
            fact_snapshot=fact_snapshot,
        )
        if release_results is not None:
            detail: Json = {
                "artifact-obligation-results": [
                    dict(result) for result in release_results
                ]
            }
            source_proof = (
                _ci_release_shaped_source_proof_from_validation_result(
                    validation_result,
                )
            )
            if source_proof is not None:
                detail.update(source_proof)
            _ci_add_release_shaped_profile_telemetry(
                detail,
                validation_result,
            )
            artifact_refs = _ci_release_shaped_observed_refs(release_results)
            if batch_bundle:
                category_result["artifact-refs"] = artifact_refs
                category_result["detail"] = detail
            else:
                category_result["detail"] = detail
    return {
        "category": category,
        "planned-capabilities": None,
        "category-result": category_result,
        "artifact-refs": artifact_refs,
    }


def _ci_add_release_shaped_profile_telemetry(
    detail: Json,
    validation_result: Mapping[str, object],
) -> None:
    profile_telemetry = (
        _ci_release_shaped_profile_telemetry_from_validation_result(
            validation_result,
        )
    )
    if profile_telemetry is not None:
        detail["profile-telemetry"] = profile_telemetry


def _ci_release_shaped_source_proof_from_validation_result(
    validation_result: Mapping[str, object],
) -> Json | None:
    commands = validation_result.get("commands")
    if not isinstance(commands, Sequence) or isinstance(commands, str | bytes):
        return None
    if len(commands) != 1:
        return None
    command = commands[0]
    if not (
        isinstance(command, Mapping)
        and command.get("outcome") == "success"
        and isinstance(command.get("artifact-obligation-results"), Sequence)
        and not isinstance(
            command.get("artifact-obligation-results"), str | bytes
        )
    ):
        return None
    evidence_source = command.get("evidence-source")
    if evidence_source != "no-publish-validation":
        return None
    source_proof = command.get("source-proof")
    if not isinstance(source_proof, Mapping):
        return None
    return {
        "evidence-source": "no-publish-validation",
        "source-proof": dict(source_proof),
    }


def _ci_release_shaped_profile_telemetry_from_validation_result(
    validation_result: Mapping[str, object],
) -> Json | None:
    commands = validation_result.get("commands")
    if not isinstance(commands, Sequence) or isinstance(commands, str | bytes):
        return None
    if len(commands) != 1:
        return None
    command = commands[0]
    if not isinstance(command, Mapping):
        return None
    telemetry = command.get("profile-telemetry")
    return dict(telemetry) if isinstance(telemetry, Mapping) else None


def _ci_attach_uploaded_release_profile_evidence(
    validation_result: Json,
    *,
    result_path: Path,
    repo_root: Path,
) -> None:
    commands = validation_result.get("commands")
    if not isinstance(commands, list):
        return
    for command in commands:
        if not isinstance(command, dict):
            continue
        telemetry = command.get("profile-telemetry")
        if not isinstance(telemetry, dict):
            continue
        upload_timing = _ci_timing_start()
        _ci_scrub_uploaded_release_profile_evidence_claims(telemetry)
        try:
            copied, path_aliases, skipped_paths = (
                _ci_copy_release_profile_evidence(
                    telemetry,
                    result_path=result_path,
                    repo_root=repo_root,
                )
            )
        except (OSError, shutil.Error) as exc:
            _ci_record_release_profile_evidence_upload_failure(
                telemetry,
                upload_timing,
                error=str(exc),
            )
            continue
        if copied:
            _ci_add_uploaded_release_profile_aliases(telemetry, path_aliases)
            telemetry["uploaded-evidence-path"] = (
                _ci_upload_payload_relative_path(
                    _ci_release_profile_evidence_dir_for_result(result_path),
                    result_path=result_path,
                )
            )
            telemetry["uploaded-evidence-files"] = copied
        if skipped_paths:
            _ci_record_release_profile_evidence_upload_failure(
                telemetry,
                upload_timing,
                error=(
                    "profile evidence upload skipped or failed "
                    f"path(s): {', '.join(skipped_paths)}"
                ),
            )


def _ci_record_release_profile_evidence_upload_failure(
    telemetry: Json,
    start: tuple[datetime, int],
    *,
    error: str,
) -> None:
    phases = telemetry.get("phases")
    if not isinstance(phases, list):
        return
    phases.append(
        {
            "phase": "profile-evidence-upload",
            "outcome": "failure",
            **_ci_timing_finish(start),
            "error": error or "profile evidence upload failed",
        },
    )


def _ci_copy_tree_skipping_symlinks(source: Path, target: Path) -> list[str]:
    if source.is_symlink():
        return [
            _ci_release_profile_evidence_skip_label(source, reason="symlink")
        ]
    try:
        source_root = source.resolve(strict=True)
    except OSError as exc:
        return [
            _ci_release_profile_evidence_skip_label(
                source,
                reason=f"unresolvable: {exc}",
            )
        ]
    if not source.is_dir():
        return [
            _ci_release_profile_evidence_skip_label(
                source,
                reason="not a directory",
            )
        ]
    skipped: list[str] = []
    try:
        target.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        return [
            _ci_release_profile_evidence_skip_label(
                source,
                reason=f"destination unavailable: {exc}",
            )
        ]
    _ci_copy_tree_entries_skipping_symlinks(
        source,
        target,
        source_base=source,
        source_root=source_root,
        skipped=skipped,
    )
    return skipped


def _ci_remove_existing_profile_upload_target(target: Path) -> None:
    if target.is_symlink() or target.is_file():
        target.unlink()
    elif target.exists():
        shutil.rmtree(target)


def _ci_copy_tree_entries_skipping_symlinks(
    source_dir: Path,
    target_dir: Path,
    *,
    source_base: Path,
    source_root: Path,
    skipped: list[str],
) -> None:
    try:
        entries = sorted(source_dir.iterdir())
    except OSError as exc:
        skipped.append(
            _ci_release_profile_evidence_skip_label(
                _ci_relative_path_or_self(source_dir, source_base),
                reason=f"unreadable: {exc}",
            )
        )
        return
    for source in entries:
        relative_source = source.relative_to(source_base)
        if source.is_symlink():
            skipped.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason="symlink",
                )
            )
            continue
        try:
            source.resolve(strict=True).relative_to(source_root)
        except OSError as exc:
            skipped.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason=f"unresolvable: {exc}",
                )
            )
            continue
        except ValueError:
            skipped.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason="outside source root",
                )
            )
            continue
        target = target_dir / source.name
        if source.is_dir():
            try:
                target.mkdir(parents=True, exist_ok=True)
            except OSError as exc:
                skipped.append(
                    _ci_release_profile_evidence_skip_label(
                        relative_source,
                        reason=f"copy failed: {exc}",
                    )
                )
                continue
            _ci_copy_tree_entries_skipping_symlinks(
                source,
                target,
                source_base=source_base,
                source_root=source_root,
                skipped=skipped,
            )
        elif source.is_file():
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, target, follow_symlinks=False)
            except (OSError, shutil.Error) as exc:
                skipped.append(
                    _ci_release_profile_evidence_skip_label(
                        relative_source,
                        reason=f"copy failed: {exc}",
                    )
                )
        else:
            skipped.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason="not a regular file",
                )
            )


def _ci_mark_result_profile_evidence_upload_staging_failure(
    result_path: Path,
    start: tuple[datetime, int],
    *,
    error: str,
    force: bool = False,
) -> None:
    try:
        validation_result = _read_json(result_path)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return
    if not isinstance(validation_result, dict):
        return
    commands = validation_result.get("commands")
    if not isinstance(commands, list):
        return
    changed = False
    timing_result = _ci_timing_finish(start)
    for command in commands:
        if not isinstance(command, dict):
            continue
        telemetry = command.get("profile-telemetry")
        if not isinstance(telemetry, dict):
            continue
        if not force and not _ci_has_uploaded_release_profile_evidence_claims(
            telemetry
        ):
            continue
        _ci_scrub_uploaded_release_profile_evidence_claims(telemetry)
        phases = telemetry.get("phases")
        if isinstance(phases, list):
            phases.append(
                {
                    "phase": "profile-evidence-upload",
                    "outcome": "failure",
                    **timing_result,
                    "error": error or "profile evidence upload staging failed",
                },
            )
        changed = True
    if changed:
        _write_json(result_path, validation_result)


def _ci_scrub_staged_release_profile_sidecar(
    profile_upload_target: Path,
) -> None:
    for sidecar_path in _ci_staged_release_profile_sidecar_paths(
        profile_upload_target,
    ):
        _ci_scrub_staged_release_profile_sidecar_file(sidecar_path)


def _ci_staged_release_profile_sidecar_paths(
    profile_upload_target: Path,
) -> list[Path]:
    if not profile_upload_target.is_dir() or profile_upload_target.is_symlink():
        return []
    sidecars: list[Path] = []
    root_sidecar = (
        profile_upload_target / "release-build-profile-telemetry.json"
    )
    if root_sidecar.is_file() and not root_sidecar.is_symlink():
        sidecars.append(root_sidecar)
    release_builds_dir = profile_upload_target / "release-builds"
    if release_builds_dir.is_dir() and not release_builds_dir.is_symlink():
        for build_dir in sorted(release_builds_dir.iterdir()):
            if not build_dir.is_dir() or build_dir.is_symlink():
                continue
            sidecar = build_dir / "release-build-profile-telemetry.json"
            if sidecar.is_file() and not sidecar.is_symlink():
                sidecars.append(sidecar)
    return sidecars


def _ci_scrub_staged_release_profile_sidecar_file(sidecar_path: Path) -> None:
    if not sidecar_path.is_file() or sidecar_path.is_symlink():
        return
    try:
        sidecar = _read_json(sidecar_path)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
        return
    if not _ci_has_uploaded_release_profile_evidence_claims(sidecar):
        return
    _ci_scrub_uploaded_release_profile_evidence_claims(sidecar)
    _write_json(sidecar_path, sidecar)


def _ci_reconcile_staged_release_profile_evidence_claims(
    result_path: Path,
    profile_upload_target: Path,
    start: tuple[datetime, int],
) -> None:
    missing_claims: list[str] = []
    try:
        validation_result = _read_json(result_path)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
        validation_result = {}
    missing_claims.extend(
        _ci_missing_uploaded_release_profile_evidence_claims(
            validation_result,
            profile_upload_target=profile_upload_target,
        )
    )
    for sidecar_path in _ci_staged_release_profile_sidecar_paths(
        profile_upload_target,
    ):
        try:
            sidecar = _read_json(sidecar_path)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
            sidecar = {}
        missing_claims.extend(
            _ci_missing_uploaded_release_profile_evidence_claims(
                sidecar,
                profile_upload_target=profile_upload_target,
            )
        )
    missing_claims = sorted(dict.fromkeys(missing_claims))
    if not missing_claims:
        return
    _ci_mark_result_profile_evidence_upload_staging_failure(
        result_path,
        start,
        error=(
            "profile evidence upload staging missing claimed path(s): "
            f"{', '.join(missing_claims)}"
        ),
        force=True,
    )
    _ci_scrub_staged_release_profile_sidecar(profile_upload_target)


def _ci_missing_uploaded_release_profile_evidence_claims(
    value: object,
    *,
    profile_upload_target: Path,
) -> list[str]:
    return [
        claim_path
        for claim_path, claim_kind in (
            _ci_uploaded_release_profile_evidence_claims(
                value,
                profile_upload_target=profile_upload_target,
            )
        )
        if not _ci_uploaded_release_profile_claim_is_staged(
            claim_path,
            claim_kind,
            profile_upload_target=profile_upload_target,
        )
    ]


def _ci_uploaded_release_profile_evidence_claims(
    value: object,
    *,
    profile_upload_target: Path,
) -> list[tuple[str, Literal["file", "directory", "profile-directory"]]]:
    claims: list[tuple[str, Literal["file", "directory", "profile-directory"]]]
    claims = []
    if isinstance(value, dict):
        uploaded_path = value.get("uploaded-evidence-path")
        if isinstance(uploaded_path, str):
            claims.append((uploaded_path, "profile-directory"))
        binlog_path = value.get("binlog-uploaded-evidence-path")
        if isinstance(binlog_path, str):
            claims.append((binlog_path, "file"))
        for key in (
            "uploaded-evidence-files",
            "binlog-uploaded-evidence-paths",
        ):
            sequence = value.get(key)
            if isinstance(sequence, Sequence) and not isinstance(
                sequence,
                str | bytes,
            ):
                claims.extend(
                    (item, "file") for item in sequence if isinstance(item, str)
                )
        argv = value.get("uploaded-evidence-argv")
        if isinstance(argv, Sequence) and not isinstance(argv, str | bytes):
            claims.extend(
                _ci_uploaded_release_profile_argv_claims(
                    argv,
                    profile_upload_target=profile_upload_target,
                )
            )
        for item in value.values():
            claims.extend(
                _ci_uploaded_release_profile_evidence_claims(
                    item,
                    profile_upload_target=profile_upload_target,
                )
            )
    elif isinstance(value, list):
        for item in value:
            claims.extend(
                _ci_uploaded_release_profile_evidence_claims(
                    item,
                    profile_upload_target=profile_upload_target,
                )
            )
    return claims


def _ci_uploaded_release_profile_argv_claims(
    argv: Sequence[object],
    *,
    profile_upload_target: Path,
) -> list[tuple[str, Literal["file", "directory"]]]:
    claims: list[tuple[str, Literal["file", "directory"]]] = []
    path_value_claim_kind: Literal["file", "directory"] | None = None
    for index, item in enumerate(argv):
        if not isinstance(item, str):
            path_value_claim_kind = None
            continue
        if path_value_claim_kind is not None:
            claims.extend(
                _ci_uploaded_release_profile_explicit_path_claims(
                    item,
                    path_value_claim_kind,
                    profile_upload_target=profile_upload_target,
                )
            )
            path_value_claim_kind = None
            continue
        if index == 0 and _ci_profile_argv_text_is_opaque_command(item):
            path_value_claim_kind = None
            continue
        match = _CI_MSBUILD_BINLOG_ARG_RE.match(item)
        if match is not None:
            claims.extend(
                _ci_msbuild_binlog_payload_file_claims(
                    match.group("payload"),
                    profile_upload_target=profile_upload_target,
                )
            )
        else:
            claims.extend(
                _ci_uploaded_release_profile_argv_item_claims(
                    item,
                    profile_upload_target=profile_upload_target,
                )
            )
        path_value_claim_kind = _ci_profile_argv_path_value_claim_kind(item)
    return claims


def _ci_uploaded_release_profile_explicit_path_claims(
    value: str,
    claim_kind: Literal["file", "directory"],
    *,
    profile_upload_target: Path,
) -> list[tuple[str, Literal["file", "directory"]]]:
    claim = _ci_trim_msbuild_binlog_path_quotes(value)
    if not claim:
        return []
    if _ci_uploaded_release_profile_claim_looks_evidence_upload(
        claim,
        profile_upload_target=profile_upload_target,
    ):
        return [(claim, claim_kind)]
    return []


def _ci_uploaded_release_profile_standalone_path_claims(
    value: str,
    claim_kind: Literal["file", "directory"],
    *,
    profile_upload_target: Path,
) -> list[tuple[str, Literal["file", "directory"]]]:
    return _ci_uploaded_release_profile_explicit_path_claims(
        value,
        claim_kind,
        profile_upload_target=profile_upload_target,
    )


def _ci_uploaded_release_profile_argv_item_claims(
    value: str,
    *,
    profile_upload_target: Path,
) -> list[tuple[str, Literal["file", "directory"]]]:
    assignment = _CI_PROFILE_ARGV_PATH_ASSIGNMENT_RE.match(value)
    if assignment is not None:
        claim_kind = _ci_profile_argv_path_value_claim_kind(
            assignment.group("switch"),
        )
        if claim_kind is None:
            return []
        return _ci_uploaded_release_profile_explicit_path_claims(
            assignment.group("path"),
            claim_kind,
            profile_upload_target=profile_upload_target,
        )
    definition = _CI_PROFILE_ARGV_PATH_DEFINITION_RE.match(value)
    if definition is not None:
        return _ci_uploaded_release_profile_explicit_path_claims(
            definition.group("path"),
            "file",
            profile_upload_target=profile_upload_target,
        )
    prefixed = _CI_PROFILE_ARGV_PATH_PREFIX_RE.match(value)
    if prefixed is not None:
        return _ci_uploaded_release_profile_standalone_path_claims(
            prefixed.group("path"),
            "file",
            profile_upload_target=profile_upload_target,
        )
    return _ci_uploaded_release_profile_standalone_path_claims(
        value,
        "file",
        profile_upload_target=profile_upload_target,
    )


def _ci_msbuild_binlog_payload_file_claims(
    value: str,
    *,
    profile_upload_target: Path,
) -> list[tuple[str, Literal["file", "directory"]]]:
    claims: list[tuple[str, Literal["file", "directory"]]] = []
    for index, item in enumerate(value.split(";")):
        name, separator, property_value = item.partition("=")
        if separator and name.lower() == "logfile":
            claims.extend(
                _ci_uploaded_release_profile_explicit_path_claims(
                    property_value,
                    "file",
                    profile_upload_target=profile_upload_target,
                )
            )
            continue
        if separator or not item:
            continue
        unquoted = _ci_trim_msbuild_binlog_path_quotes(item)
        if index == 0 or _ci_msbuild_binlog_payload_item_looks_path_bearing(
            unquoted,
        ):
            claims.extend(
                _ci_uploaded_release_profile_explicit_path_claims(
                    item,
                    "file",
                    profile_upload_target=profile_upload_target,
                )
            )
    return claims


def _ci_staged_profile_claims_from_path_text(
    value: str,
    claim_kind: Literal["file", "directory"],
    *,
    profile_upload_target: Path,
) -> list[tuple[str, Literal["file", "directory"]]]:
    return _ci_uploaded_release_profile_standalone_path_claims(
        value,
        claim_kind,
        profile_upload_target=profile_upload_target,
    )


def _ci_uploaded_release_profile_claim_looks_staged(
    value: str,
    *,
    profile_upload_target: Path,
) -> bool:
    if not value:
        return False
    path = Path(value)
    if path.is_absolute():
        try:
            path.resolve(strict=False).relative_to(
                profile_upload_target.resolve(strict=False),
            )
        except (OSError, ValueError):
            return False
        return True
    normalized = PurePosixPath(value.replace("\\", "/")).as_posix()
    target_name = profile_upload_target.name
    return normalized == target_name or normalized.startswith(f"{target_name}/")


def _ci_uploaded_release_profile_claim_looks_evidence_upload(
    value: str,
    *,
    profile_upload_target: Path,
) -> bool:
    if _ci_uploaded_release_profile_claim_looks_staged(
        value,
        profile_upload_target=profile_upload_target,
    ):
        return True
    normalized = PurePosixPath(value.replace("\\", "/")).as_posix()
    return any(
        _CI_PROFILE_EVIDENCE_UPLOAD_DIR_RE.match(part) is not None
        for part in normalized.split("/")
    )


def _ci_uploaded_release_profile_claim_path(
    value: str,
    *,
    profile_upload_target: Path,
) -> Path:
    path = Path(value)
    if not path.is_absolute():
        path = profile_upload_target.parent / PurePosixPath(
            value.replace("\\", "/"),
        )
    return path


def _ci_uploaded_release_profile_claim_is_staged(
    value: str,
    claim_kind: Literal["file", "directory", "profile-directory"],
    *,
    profile_upload_target: Path,
) -> bool:
    path = _ci_uploaded_release_profile_claim_path(
        value,
        profile_upload_target=profile_upload_target,
    )
    try:
        resolved_path = path.resolve(strict=False)
        resolved_target = profile_upload_target.resolve(strict=False)
    except OSError:
        return False
    if claim_kind == "profile-directory":
        return (
            resolved_path == resolved_target
            and path.is_dir()
            and not path.is_symlink()
        )
    try:
        resolved_path.relative_to(resolved_target)
    except (OSError, ValueError):
        return False
    if claim_kind == "directory":
        return path.is_dir() and not path.is_symlink()
    return path.is_file() and not path.is_symlink()


def _ci_scrub_uploaded_release_profile_evidence_claims(value: object) -> None:
    if isinstance(value, dict):
        for key in _CI_UPLOADED_PROFILE_EVIDENCE_CLAIM_KEYS:
            value.pop(key, None)
        for item in value.values():
            _ci_scrub_uploaded_release_profile_evidence_claims(item)
    elif isinstance(value, list):
        for item in value:
            _ci_scrub_uploaded_release_profile_evidence_claims(item)


def _ci_has_uploaded_release_profile_evidence_claims(value: object) -> bool:
    if isinstance(value, dict):
        return any(
            key in value for key in _CI_UPLOADED_PROFILE_EVIDENCE_CLAIM_KEYS
        ) or any(
            _ci_has_uploaded_release_profile_evidence_claims(item)
            for item in value.values()
        )
    if isinstance(value, list):
        return any(
            _ci_has_uploaded_release_profile_evidence_claims(item)
            for item in value
        )
    return False


def _ci_copy_release_profile_evidence(
    telemetry: Mapping[str, object],
    *,
    result_path: Path,
    repo_root: Path,
) -> tuple[list[str], dict[str, str], list[str]]:
    release_builds = _ci_release_profile_evidence_builds(telemetry)
    if not release_builds:
        return [], {}, []
    mismatch = _ci_release_profile_evidence_build_mismatch(telemetry)
    if mismatch is not None:
        return [], {}, [mismatch]
    synced_singular_release_build = (
        _ci_synced_singular_release_profile_evidence_build(telemetry)
    )
    destination = _ci_release_profile_evidence_dir_for_result(result_path)
    if destination.exists():
        shutil.rmtree(destination)
    copied: list[str] = []
    global_path_aliases: dict[str, str] = {}
    skipped_paths: list[str] = []
    plural_release_builds = _ci_release_profile_evidence_has_plural_builds(
        telemetry,
    )
    for index, release_build in enumerate(release_builds):
        path_aliases: dict[str, str] = {}
        _ci_copy_release_build_profile_evidence(
            release_build,
            build_destination=(
                destination
                / "release-builds"
                / _ci_release_profile_evidence_build_dir_name(
                    release_build,
                    index=index,
                )
                if plural_release_builds
                else destination
            ),
            result_path=result_path,
            repo_root=repo_root,
            path_aliases=path_aliases,
            copied=copied,
            skipped_paths=skipped_paths,
        )
        if (
            index == 0
            and synced_singular_release_build is not None
            and synced_singular_release_build is not release_build
        ):
            _ci_add_uploaded_release_profile_aliases(
                synced_singular_release_build,
                path_aliases,
            )
        global_path_aliases.update(
            _ci_global_release_profile_path_aliases(path_aliases),
        )
    return copied, global_path_aliases, skipped_paths


def _ci_release_profile_evidence_has_plural_builds(
    telemetry: Mapping[str, object],
) -> bool:
    release_builds = telemetry.get("release-builds")
    return (
        isinstance(release_builds, Sequence)
        and not isinstance(release_builds, str | bytes)
        and any(isinstance(item, Mapping) for item in release_builds)
    )


def _ci_release_profile_evidence_build_mismatch(
    telemetry: Mapping[str, object],
) -> str | None:
    if "release-build" not in telemetry or "release-builds" not in telemetry:
        return None
    release_build = telemetry.get("release-build")
    release_builds = telemetry.get("release-builds")
    if not (
        isinstance(release_build, Mapping)
        and isinstance(release_builds, Sequence)
        and not isinstance(release_builds, str | bytes)
        and release_builds
    ):
        return None
    first = release_builds[0]
    if isinstance(first, Mapping) and release_build == first:
        return None
    return "release-build (must match release-builds[0])"


def _ci_synced_singular_release_profile_evidence_build(
    telemetry: Mapping[str, object],
) -> dict[str, object] | None:
    release_build = telemetry.get("release-build")
    release_builds = telemetry.get("release-builds")
    if not (
        isinstance(release_build, dict)
        and isinstance(release_builds, Sequence)
        and not isinstance(release_builds, str | bytes)
        and release_builds
        and release_build == release_builds[0]
    ):
        return None
    return release_build


def _ci_global_release_profile_path_aliases(
    path_aliases: Mapping[str, str],
) -> dict[str, str]:
    return {
        key: value
        for key, value in path_aliases.items()
        if Path(key).is_absolute() or key.startswith(".three-ci-validation/")
    }


def _ci_release_profile_evidence_builds(
    telemetry: Mapping[str, object],
) -> list[Mapping[str, object]]:
    release_builds = telemetry.get("release-builds")
    if isinstance(release_builds, Sequence) and not isinstance(
        release_builds,
        str | bytes,
    ):
        return [item for item in release_builds if isinstance(item, Mapping)]
    release_build = telemetry.get("release-build")
    return [release_build] if isinstance(release_build, Mapping) else []


def _ci_release_profile_evidence_build_dir_name(
    release_build: Mapping[str, object],
    *,
    index: int,
) -> str:
    bundle_dir_text = release_build.get("bundle-dir")
    if isinstance(bundle_dir_text, str) and bundle_dir_text:
        bundle_id = PurePosixPath(bundle_dir_text.replace("\\", "/")).name
        if re.fullmatch(r"[0-9a-f]{24}", bundle_id) is not None:
            return bundle_id
    return f"build-{index:03d}"


def _ci_copy_release_build_profile_evidence(
    release_build: Mapping[str, object],
    *,
    build_destination: Path,
    result_path: Path,
    repo_root: Path,
    path_aliases: dict[str, str],
    copied: list[str],
    skipped_paths: list[str],
) -> None:
    bundle_dir_text = release_build.get("bundle-dir")
    if not isinstance(bundle_dir_text, str) or not bundle_dir_text:
        return
    bundle_dir = Path(bundle_dir_text)
    if not bundle_dir.is_absolute():
        bundle_dir = repo_root / bundle_dir
    if not bundle_dir.is_dir():
        return
    profile_root = _ci_release_build_profile_root_from_metadata(
        release_build,
        bundle_dir=bundle_dir,
        repo_root=repo_root,
    )
    if profile_root is not None:
        profile_target = _ci_release_profile_root_relative_to_bundle(
            profile_root,
            bundle_dir=bundle_dir,
            repo_root=repo_root,
            skipped_paths=skipped_paths,
        )
        if profile_target is None:
            return
        copied.extend(
            _ci_copy_release_profile_evidence_tree(
                profile_root,
                build_destination / profile_target,
                result_path=result_path,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                path_aliases=path_aliases,
                skipped_paths=skipped_paths,
            )
        )
    try:
        sidecar_path = _ci_write_normalized_release_profile_sidecar(
            release_build,
            destination=build_destination,
            result_path=result_path,
            repo_root=repo_root,
            bundle_dir=bundle_dir,
            path_aliases=path_aliases,
        )
    except OSError as exc:
        sidecar_path = None
        with suppress(OSError):
            (
                build_destination / "release-build-profile-telemetry.json"
            ).unlink()
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                Path("release-build-profile-telemetry.json"),
                reason=f"normalized sidecar write failed: {exc}",
            )
        )
    if sidecar_path is not None:
        copied.append(sidecar_path)
    _ci_add_uploaded_release_profile_aliases(release_build, path_aliases)


def _ci_release_profile_root_relative_to_bundle(
    profile_root: Path,
    *,
    bundle_dir: Path,
    repo_root: Path,
    skipped_paths: list[str],
) -> Path | None:
    try:
        resolved_root = profile_root.resolve(strict=False)
        resolved_bundle = bundle_dir.resolve(strict=True)
        relative_root = resolved_root.relative_to(resolved_bundle)
    except ValueError:
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                profile_root,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                reason="outside bundle dir",
            )
        )
        return None
    except OSError:
        return _ci_relative_path_or_self(profile_root, bundle_dir)
    if not relative_root.parts:
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                profile_root,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                reason="not below bundle dir",
            )
        )
        return None
    if relative_root.parts[:1] != ("_profile",):
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                profile_root,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                reason="outside bundle profile root",
            )
        )
        return None
    return relative_root


def _ci_release_profile_evidence_skip_label(
    path: Path,
    *,
    reason: str,
    repo_root: Path | None = None,
    bundle_dir: Path | None = None,
) -> str:
    label = path.as_posix()
    if bundle_dir is not None:
        with suppress(ValueError):
            label = path.relative_to(bundle_dir).as_posix()
    if repo_root is not None and label == path.as_posix():
        with suppress(ValueError):
            label = path.relative_to(repo_root).as_posix()
    return f"{label} ({reason})"


def _ci_relative_path_or_self(path: Path, base: Path) -> Path:
    with suppress(ValueError):
        return path.relative_to(base)
    return path


def _ci_copy_release_profile_evidence_tree(
    source: Path,
    target: Path,
    *,
    result_path: Path,
    repo_root: Path,
    bundle_dir: Path,
    path_aliases: dict[str, str],
    skipped_paths: list[str],
) -> list[str]:
    if source.is_symlink():
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                source,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                reason="symlink",
            )
        )
        return []
    try:
        source_root = source.resolve(strict=True)
    except OSError as exc:
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                source,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                reason=f"unresolvable: {exc}",
            )
        )
        return []
    if not source.is_dir():
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                source,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                reason="not a directory",
            )
        )
        return []

    copied: list[str] = []
    target.mkdir(parents=True, exist_ok=True)
    uploaded_dir = _ci_upload_payload_relative_path(
        target,
        result_path=result_path,
    )
    _ci_add_release_profile_path_aliases(
        path_aliases,
        source,
        uploaded_dir,
        repo_root=repo_root,
        bundle_dir=bundle_dir,
    )
    _ci_copy_release_profile_evidence_tree_entries(
        source,
        target,
        source_base=source,
        source_root=source_root,
        result_path=result_path,
        repo_root=repo_root,
        bundle_dir=bundle_dir,
        path_aliases=path_aliases,
        copied=copied,
        skipped_paths=skipped_paths,
    )
    return copied


def _ci_copy_release_profile_evidence_tree_entries(
    source_dir: Path,
    target_dir: Path,
    *,
    source_base: Path,
    source_root: Path,
    result_path: Path,
    repo_root: Path,
    bundle_dir: Path,
    path_aliases: dict[str, str],
    copied: list[str],
    skipped_paths: list[str],
) -> None:
    try:
        entries = sorted(source_dir.iterdir())
    except OSError as exc:
        skipped_paths.append(
            _ci_release_profile_evidence_skip_label(
                _ci_relative_path_or_self(source_dir, source_base),
                reason=f"unreadable: {exc}",
            )
        )
        return
    for source in entries:
        relative_source = source.relative_to(source_base)
        if source.is_symlink():
            skipped_paths.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason="symlink",
                )
            )
            continue
        try:
            source.resolve(strict=True).relative_to(source_root)
        except OSError as exc:
            skipped_paths.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason=f"unresolvable: {exc}",
                )
            )
            continue
        except ValueError:
            skipped_paths.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason="outside source root",
                )
            )
            continue
        target = target_dir / source.name
        if source.is_dir():
            try:
                target.mkdir(parents=True, exist_ok=True)
            except OSError as exc:
                skipped_paths.append(
                    _ci_release_profile_evidence_skip_label(
                        relative_source,
                        reason=f"copy failed: {exc}",
                    )
                )
                continue
            uploaded_dir = _ci_upload_payload_relative_path(
                target,
                result_path=result_path,
            )
            _ci_add_release_profile_path_aliases(
                path_aliases,
                source,
                uploaded_dir,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
            )
            _ci_copy_release_profile_evidence_tree_entries(
                source,
                target,
                source_base=source_base,
                source_root=source_root,
                result_path=result_path,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
                path_aliases=path_aliases,
                copied=copied,
                skipped_paths=skipped_paths,
            )
        elif source.is_file():
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, target, follow_symlinks=False)
            except (OSError, shutil.Error) as exc:
                skipped_paths.append(
                    _ci_release_profile_evidence_skip_label(
                        relative_source,
                        reason=f"copy failed: {exc}",
                    )
                )
                continue
            uploaded_path = _ci_upload_payload_relative_path(
                target,
                result_path=result_path,
            )
            copied.append(uploaded_path)
            _ci_add_release_profile_path_aliases(
                path_aliases,
                source,
                uploaded_path,
                repo_root=repo_root,
                bundle_dir=bundle_dir,
            )
        else:
            skipped_paths.append(
                _ci_release_profile_evidence_skip_label(
                    relative_source,
                    reason="not a regular file",
                )
            )


def _ci_write_normalized_release_profile_sidecar(
    release_build: Mapping[str, object],
    *,
    destination: Path,
    result_path: Path,
    repo_root: Path,
    bundle_dir: Path,
    path_aliases: dict[str, str],
) -> str | None:
    executor = release_build.get("executor")
    if not isinstance(executor, Mapping):
        return None
    destination.mkdir(parents=True, exist_ok=True)
    target = destination / "release-build-profile-telemetry.json"
    uploaded_path = _ci_upload_payload_relative_path(
        target,
        result_path=result_path,
    )
    telemetry_path = bundle_dir / "release-build-profile-telemetry.json"
    sidecar_aliases = dict(path_aliases)
    _ci_add_release_profile_path_aliases(
        sidecar_aliases,
        telemetry_path,
        uploaded_path,
        repo_root=repo_root,
        bundle_dir=bundle_dir,
    )
    sidecar = copy.deepcopy(executor)
    _ci_scrub_uploaded_release_profile_evidence_claims(sidecar)
    _ci_add_uploaded_release_profile_aliases(sidecar, sidecar_aliases)
    _write_json(target, sidecar)
    path_aliases.update(sidecar_aliases)
    return uploaded_path


def _ci_add_release_profile_path_aliases(
    aliases: dict[str, str],
    source: Path,
    uploaded_path: str,
    *,
    repo_root: Path,
    bundle_dir: Path,
) -> None:
    candidate_paths = [source]
    with suppress(OSError):
        candidate_paths.append(source.resolve())
    for candidate in candidate_paths:
        aliases[candidate.as_posix()] = uploaded_path
        aliases[_ci_profile_relative_path(candidate, repo_root)] = uploaded_path
        with suppress(OSError, ValueError):
            aliases[
                candidate.resolve().relative_to(bundle_dir.resolve()).as_posix()
            ] = uploaded_path


def _ci_add_uploaded_release_profile_aliases(  # noqa: C901
    value: object,
    path_aliases: Mapping[str, str],
) -> None:
    if isinstance(value, dict):
        binlog_path = value.get("binlog-path")
        if isinstance(binlog_path, str):
            uploaded_binlog_path = _ci_uploaded_profile_path_alias(
                binlog_path,
                path_aliases,
            )
            if uploaded_binlog_path is not None:
                value["binlog-uploaded-evidence-path"] = uploaded_binlog_path
        binlog_paths = value.get("binlog-paths")
        if isinstance(binlog_paths, Sequence) and not isinstance(
            binlog_paths, str | bytes
        ):
            uploaded_binlog_paths = [
                alias
                for item in binlog_paths
                if isinstance(item, str)
                for alias in (
                    _ci_uploaded_profile_path_alias(item, path_aliases),
                )
                if alias is not None
            ]
            if uploaded_binlog_paths:
                value["binlog-uploaded-evidence-paths"] = uploaded_binlog_paths
        argv = value.get("argv")
        if isinstance(argv, Sequence) and not isinstance(argv, str | bytes):
            uploaded_argv = _ci_uploaded_profile_argv_alias_sequence(
                argv,
                path_aliases,
            )
            if list(argv) != uploaded_argv:
                value["uploaded-evidence-argv"] = uploaded_argv
        for item in value.values():
            _ci_add_uploaded_release_profile_aliases(item, path_aliases)
    elif isinstance(value, list):
        for item in value:
            _ci_add_uploaded_release_profile_aliases(item, path_aliases)


def _ci_uploaded_profile_argv_alias_sequence(
    argv: Sequence[object],
    path_aliases: Mapping[str, str],
) -> list[object]:
    uploaded_argv: list[object] = []
    path_value_expected = False
    for item in argv:
        if not isinstance(item, str):
            uploaded_argv.append(item)
            path_value_expected = False
            continue
        if path_value_expected:
            alias = _ci_uploaded_profile_path_alias(item, path_aliases)
            uploaded_argv.append(item if alias is None else alias)
            path_value_expected = False
            continue
        uploaded_argv.append(
            _ci_uploaded_profile_argv_alias(item, path_aliases)
        )
        path_value_expected = _ci_profile_argv_switch_expects_path_value(item)
    return uploaded_argv


def _ci_uploaded_profile_argv_alias(
    value: str,
    path_aliases: Mapping[str, str],
) -> str:
    match = _CI_MSBUILD_BINLOG_ARG_RE.match(value)
    if match is not None:
        payload = _ci_rewrite_msbuild_binlog_payload_paths(
            match.group("payload"),
            lambda path: _ci_uploaded_profile_path_alias(
                path,
                path_aliases,
            ),
        )
        return f"{match.group('prefix')}{payload}"
    assignment = _CI_PROFILE_ARGV_PATH_ASSIGNMENT_RE.match(value)
    if assignment is not None:
        uploaded_path = _ci_uploaded_profile_path_alias(
            assignment.group("path"),
            path_aliases,
        )
        return (
            value
            if uploaded_path is None
            else (
                f"{assignment.group('switch')}"
                f"{assignment.group('separator')}{uploaded_path}"
            )
        )
    definition = _CI_PROFILE_ARGV_PATH_DEFINITION_RE.match(value)
    if definition is not None:
        uploaded_path = _ci_uploaded_profile_path_alias(
            definition.group("path"),
            path_aliases,
        )
        return (
            value
            if uploaded_path is None
            else f"{definition.group('prefix')}{uploaded_path}"
        )
    prefixed = _CI_PROFILE_ARGV_PATH_PREFIX_RE.match(value)
    if prefixed is not None:
        uploaded_path = _ci_uploaded_profile_path_alias(
            prefixed.group("path"),
            path_aliases,
        )
        return (
            value
            if uploaded_path is None
            else f"{prefixed.group('prefix')}{uploaded_path}"
        )
    uploaded_path = _ci_uploaded_profile_path_alias(value, path_aliases)
    return value if uploaded_path is None else uploaded_path


def _ci_uploaded_profile_path_alias(
    value: str,
    path_aliases: Mapping[str, str],
) -> str | None:
    normalized = PurePosixPath(value.replace("\\", "/")).as_posix()
    return path_aliases.get(value) or path_aliases.get(normalized)


def _ci_release_build_profile_root_from_metadata(
    release_build: Mapping[str, object],
    *,
    bundle_dir: Path,
    repo_root: Path,
) -> Path | None:
    profile_root = release_build.get("profile-root")
    if isinstance(profile_root, str) and profile_root:
        path = Path(profile_root)
        if not path.is_absolute():
            repo_relative_path = repo_root / path
            path = (
                repo_relative_path
                if repo_relative_path.exists()
                else bundle_dir / path
            )
        return path
    executor = release_build.get("executor")
    if isinstance(executor, Mapping):
        executor_root = executor.get("profile-root")
        if isinstance(executor_root, str) and executor_root:
            path = Path(executor_root)
            if not path.is_absolute():
                repo_relative_path = repo_root / path
                path = (
                    repo_relative_path
                    if repo_relative_path.exists()
                    else bundle_dir / path
                )
            return path
    legacy_profile = bundle_dir / "_profile"
    return legacy_profile if legacy_profile.is_dir() else None


def _ci_release_profile_evidence_dir_for_result(result_path: Path) -> Path:
    return result_path.with_name(f"{result_path.stem}-profile-evidence")


def _ci_upload_payload_relative_path(
    path: Path,
    *,
    result_path: Path,
) -> str:
    try:
        return (
            path.resolve().relative_to(result_path.parent.resolve()).as_posix()
        )
    except ValueError:
        return path.name


def _ci_capability_results(
    *,
    work_group_id: str,
    capabilities: Sequence[str],
    outcome: str,
    diagnostics: Sequence[Mapping[str, object]],
    validation_result: Mapping[str, object] | None,
) -> list[Json]:
    if outcome == "skipped":
        return [
            {
                "capability": capability,
                "outcome": "skipped",
                "diagnostics": [dict(item) for item in diagnostics],
            }
            for capability in capabilities
        ]
    if (
        outcome != "success"
        and validation_result is not None
        and validation_result.get("outcome") == "success"
    ):
        validation_result = None
    if validation_result is None:
        return [
            {
                "capability": capability,
                "outcome": outcome,
                "diagnostics": [dict(item) for item in diagnostics],
            }
            for capability in capabilities
        ]
    commands_by_capability = _ci_command_results_by_capability(
        validation_result,
    )
    results: list[Json] = []
    for capability in capabilities:
        commands = commands_by_capability.get(capability, [])
        capability_outcome = (
            "success"
            if commands
            and all(command.get("outcome") == "success" for command in commands)
            else "blocking-failure"
        )
        capability_diagnostics = (
            []
            if capability_outcome == "success"
            else [_ci_capability_failure_diagnostic(work_group_id, capability)]
        )
        results.append(
            {
                "capability": capability,
                "outcome": capability_outcome,
                "diagnostics": capability_diagnostics,
            }
        )
    return results


def _ci_command_results_by_capability(
    validation_result: Mapping[str, object] | None,
) -> dict[str, list[Mapping[str, object]]]:
    commands = (
        None if validation_result is None else validation_result.get("commands")
    )
    if not isinstance(commands, Sequence) or isinstance(commands, str | bytes):
        return {}
    result: dict[str, list[Mapping[str, object]]] = {}
    for command in commands:
        if not isinstance(command, Mapping):
            continue
        capability = command.get("capability")
        if isinstance(capability, str):
            result.setdefault(capability, []).append(command)
    return result


def _ci_validation_detail(
    plan: Mapping[str, object],
    work_group_id: str,
    category: str,
    diagnostics: Sequence[Mapping[str, object]],
    *,
    outcome: str,
    fact_snapshot: Mapping[str, object] | None,
) -> Json:
    if category in {"lightweight-preflight", "workflow-release-tooling"}:
        return _ci_detail_profile_result(
            plan,
            work_group_id,
            category,
            diagnostics,
            outcome=outcome,
        )
    if category == "descriptor-validation":
        return {
            "descriptor-obligation-results": [
                _ci_descriptor_placeholder_result(
                    obligation,
                    diagnostics,
                    outcome=outcome,
                    fact_snapshot=fact_snapshot,
                )
                for obligation in _ci_plan_records_for_work_group(
                    plan, "descriptor-obligations", work_group_id
                )
            ],
        }
    if category == "release-shaped-artifact":
        return {
            "artifact-obligation-results": [
                _ci_artifact_placeholder_result(
                    obligation,
                    diagnostics,
                    fact_snapshot=fact_snapshot,
                    outcome=outcome,
                )
                for obligation in _ci_plan_records_for_work_group(
                    plan, "artifact-obligations", work_group_id
                )
            ],
        }
    return {}


def _ci_detail_profile_result(
    plan: Mapping[str, object],
    work_group_id: str,
    category: str,
    diagnostics: Sequence[Mapping[str, object]],
    *,
    outcome: str,
) -> Json:
    group = _ci_work_group(plan, work_group_id)
    expectation = _ci_evidence_expectation(plan, work_group_id)
    profile = _ci_detail_profile(plan, str(expectation["detail-profile"]))
    detail: Json = {
        "work-group-id": work_group_id,
        "detail-profile": expectation["detail-profile"],
        "coverage-target": group["coverage-target"],
        "selector-variant": group.get("selector-variant"),
        "runner-family": group["runner-family"],
        "outcome": outcome,
        "subcheck-results": [
            {
                "subcheck-id": item["subcheck-id"],
                "outcome": outcome,
                "diagnostics": [dict(item) for item in diagnostics],
            }
            for item in cast(
                "Sequence[Mapping[str, object]]",
                profile["required-subchecks"],
            )
        ],
        "diagnostics": [dict(item) for item in diagnostics],
    }
    if category == "workflow-release-tooling":
        detail["ecosystem"] = group.get("ecosystem")
    return detail


def _ci_descriptor_placeholder_result(
    obligation: Mapping[str, object],
    diagnostics: Sequence[Mapping[str, object]],
    *,
    outcome: str,
    fact_snapshot: Mapping[str, object] | None,
) -> Json:
    descriptor_path = _ci_descriptor_obligation_path(obligation)
    fact = _ci_descriptor_fact(fact_snapshot, descriptor_path)
    return {
        "descriptor-obligation-id": obligation["descriptor-obligation-id"],
        "descriptor": {
            "path": descriptor_path,
            "identity": fact.get("descriptor-identity") if fact else None,
            "owner-subject-id": fact.get("owner-subject-id") if fact else None,
            "source": fact.get("source") if fact else "ecosystem-provider",
        },
        "descriptor-scope": obligation["descriptor-scope"],
        "outcome": outcome,
        "diagnostics": [dict(item) for item in diagnostics],
    }


def _ci_artifact_placeholder_result(
    obligation: Mapping[str, object],
    diagnostics: Sequence[Mapping[str, object]],
    *,
    fact_snapshot: Mapping[str, object] | None,
    outcome: str,
) -> Json:
    artifact = dict(cast("Mapping[str, object]", obligation["artifact"]))
    receipt = dict(cast("Mapping[str, object]", obligation["release-receipt"]))
    descriptor_path = str(obligation["descriptor-path"])
    descriptor_fact = _ci_descriptor_fact(fact_snapshot, descriptor_path)
    expected_refs = _ci_artifact_expected_refs(obligation)
    observed_refs: list[str] = []
    observed_digests: list[Json] = []
    if outcome == "blocking-failure" and any(
        diagnostic.get("code")
        == DiagnosticFamily.ARTIFACT_SHAPE_UNCONFIRMED.value
        for diagnostic in diagnostics
        if isinstance(diagnostic, Mapping)
    ):
        observed_refs = expected_refs
        observed_digests = [
            {
                "artifact-ref": artifact_ref,
                "algorithm": "sha256",
                "digest": "",
                "digest-available": False,
                "diagnostics": [dict(item) for item in diagnostics],
            }
            for artifact_ref in expected_refs
        ]
    return {
        "artifact-obligation-id": obligation["artifact-obligation-id"],
        "descriptor": {
            "path": descriptor_path,
            "identity": descriptor_fact.get("descriptor-identity")
            if descriptor_fact is not None
            else None,
        },
        "profile-coverage": obligation["profile-coverage"],
        "artifact": {
            "planned": artifact,
            "observed": {"refs": observed_refs, "digests": observed_digests},
            "outcome": outcome,
            "diagnostics": [dict(item) for item in diagnostics],
        },
        "release-receipt": {
            "planned": receipt,
            "expected": True,
            "schema-checked": False,
            "outcome": outcome,
            "diagnostics": [dict(item) for item in diagnostics],
        },
        "outcome": outcome,
        "diagnostics": [dict(item) for item in diagnostics],
    }


def _ci_artifact_obligation_success_result(
    obligation: Mapping[str, object],
) -> Json:
    artifact = dict(cast("Mapping[str, object]", obligation["artifact"]))
    receipt = dict(cast("Mapping[str, object]", obligation["release-receipt"]))
    expected_refs = _ci_artifact_expected_refs(obligation)
    return {
        "artifact-obligation-id": obligation["artifact-obligation-id"],
        "descriptor": {
            "path": str(obligation["descriptor-path"]),
            "identity": None,
        },
        "profile-coverage": obligation["profile-coverage"],
        "artifact": {
            "planned": artifact,
            "observed": {
                "refs": expected_refs,
                "digests": [
                    {
                        "artifact-ref": artifact_ref,
                        "algorithm": "sha256",
                        "digest": _ci_fabricated_release_artifact_digest(
                            obligation, artifact_ref
                        ),
                        "digest-available": True,
                        "diagnostics": [],
                    }
                    for artifact_ref in expected_refs
                ],
            },
            "outcome": "success",
            "diagnostics": [],
        },
        "release-receipt": {
            "planned": receipt,
            "expected": True,
            "schema-checked": True,
            "outcome": "success",
            "diagnostics": [],
        },
        "outcome": "success",
        "diagnostics": [],
    }


def _ci_evidence_expectation(
    plan: Mapping[str, object],
    work_group_id: str,
) -> Mapping[str, object]:
    for item in _ci_plan_records_for_work_group(
        plan, "evidence-expectations", work_group_id
    ):
        return item
    msg = f"work group {work_group_id!r} has no evidence expectation"
    raise KeyError(msg)


def _ci_work_group(
    plan: Mapping[str, object],
    work_group_id: str,
) -> Mapping[str, object]:
    for item in _ci_plan_records_for_work_group(
        plan, "work-groups", work_group_id
    ):
        return item
    msg = f"work group {work_group_id!r} does not exist"
    raise KeyError(msg)


def _ci_detail_profile(
    plan: Mapping[str, object],
    profile_id: str,
) -> Mapping[str, object]:
    profiles = plan.get("detail-profiles")
    if isinstance(profiles, Sequence) and not isinstance(profiles, str | bytes):
        for item in profiles:
            if (
                isinstance(item, Mapping)
                and item.get("detail-profile-id") == profile_id
            ):
                return item
    msg = f"detail profile {profile_id!r} does not exist"
    raise KeyError(msg)


def _ci_plan_records_for_work_group(
    plan: Mapping[str, object],
    key: str,
    work_group_id: str,
) -> list[Mapping[str, object]]:
    records = plan.get(key)
    if not isinstance(records, Sequence) or isinstance(records, str | bytes):
        return []
    return [
        item
        for item in records
        if isinstance(item, Mapping)
        and item.get("work-group-id") == work_group_id
    ]


def _ci_descriptor_obligation_path(obligation: Mapping[str, object]) -> str:
    target = obligation.get("coverage-target")
    if isinstance(target, Mapping) and isinstance(target.get("id"), str):
        return str(target["id"])
    return str(obligation.get("descriptor-path"))


def _ci_descriptor_fact(
    fact_snapshot: Mapping[str, object] | None,
    descriptor_path: str,
) -> Mapping[str, object] | None:
    if fact_snapshot is None:
        return None
    providers = fact_snapshot.get("providers")
    if not isinstance(providers, Sequence) or isinstance(
        providers, str | bytes
    ):
        return None
    for provider in providers:
        if not isinstance(provider, Mapping):
            continue
        descriptors = provider.get("descriptors")
        if not isinstance(descriptors, Sequence) or isinstance(
            descriptors, str | bytes
        ):
            continue
        for descriptor in descriptors:
            if (
                isinstance(descriptor, Mapping)
                and descriptor.get("descriptor-path") == descriptor_path
            ):
                return descriptor
    return None


def _parse_bool(value: str | bool) -> bool:
    if isinstance(value, bool):
        return value
    return value.lower() == "true"


def _parse_strict_bool(value: str | bool) -> bool:
    if isinstance(value, bool):
        return value
    normalized = value.lower()
    if normalized == "true":
        return True
    if normalized == "false":
        return False
    msg = "expected 'true' or 'false'"
    raise argparse.ArgumentTypeError(msg)


def _ci_validation_reject_duplicate_json_keys(
    pairs: Sequence[tuple[str, object]],
) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            msg = f"duplicate JSON object key: {key}"
            raise ValueError(msg)
        result[key] = value
    return result


def _bool_str(value: bool) -> str:
    return "true" if value else "false"


def _read_json(path: Path) -> Json:
    payload = json.loads(
        path.read_text(encoding="utf-8"),
        object_pairs_hook=_ci_validation_reject_duplicate_json_keys,
    )
    if not isinstance(payload, dict):
        msg = f"{path} must contain a JSON object"
        raise TypeError(msg)
    return payload


def _read_string_array_file(path: Path, label: str) -> list[str]:
    payload = json.loads(
        path.read_text(encoding="utf-8"),
        object_pairs_hook=_ci_validation_reject_duplicate_json_keys,
    )
    return _string_list(payload, label)


def _mapping(value: object, path: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        msg = f"{path} must be a JSON object"
        raise TypeError(msg)
    return value


def _string(value: object, path: str) -> str:
    if not isinstance(value, str) or not value:
        msg = f"{path} must be a non-empty string"
        raise TypeError(msg)
    return value


def _int(value: object, path: str) -> int:
    if type(value) is not int:
        msg = f"{path} must be an integer"
        raise TypeError(msg)
    return value


def _string_list(value: object, path: str) -> list[str]:
    if not isinstance(value, Sequence) or isinstance(value, str | bytes):
        msg = f"{path} must be an array"
        raise TypeError(msg)
    result: list[str] = []
    for index, item in enumerate(value):
        if not isinstance(item, str) or not item:
            msg = f"{path}[{index}] must be a non-empty string"
            raise TypeError(msg)
        result.append(item)
    return result


def _require_mapping(value: object, label: str) -> None:
    if not isinstance(value, Mapping):
        msg = f"{label} must be a JSON object"
        raise TypeError(msg)


def _read_optional_json(value: str) -> Json | None:
    if not value:
        return None
    path = Path(value)
    if not path.is_file():
        return None
    return _read_json(path)


def _write_json(path: Path, document: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(document, indent=2, sort_keys=True, ensure_ascii=False)
        + "\n",
        encoding="utf-8",
    )


def _write_json_atomic(path: Path, document: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = (
        json.dumps(document, indent=2, sort_keys=True, ensure_ascii=False)
        + "\n"
    )
    temp_path: Path | None = None
    with tempfile.NamedTemporaryFile(
        "w",
        encoding="utf-8",
        dir=path.parent,
        prefix=f".{path.name}.",
        suffix=".tmp",
        delete=False,
    ) as handle:
        temp_path = Path(handle.name)
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    try:
        temp_path.replace(path)
    except OSError:
        with suppress(OSError):
            temp_path.unlink()
        raise


def _write_outputs(path: str | None, values: Mapping[str, str]) -> None:
    if not path:
        return
    with Path(path).open("a", encoding="utf-8") as handle:
        for key, value in values.items():
            if "\n" in value:
                token = hashlib.sha256(f"{key}\n{value}".encode()).hexdigest()
                handle.write(f"{key}<<{token}\n{value}\n{token}\n")
            else:
                handle.write(f"{key}={value}\n")


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except RuntimeError as exc:
        text = str(exc)
        if text.startswith("{"):
            sys.stderr.write(text + "\n")
        else:
            sys.stderr.write(f"{exc}\n")
        raise SystemExit(1) from exc